#!/usr/bin/env node
"use strict";
// Cyrus Test Flight STRESS bot (runner tf-lite-5): ONE scripted Mineflayer player that joins the disposable server and,
// until its deadline, places and breaks blocks next to itself (real BlockPlaceEvent / BlockBreakEvent) and teleports
// to a new spot every few seconds (real chunk loads and player movement). Started by runner.js inside the flight's
// private network namespace as uid 65534 with a heap cap and a hard timeout; talks only to 127.0.0.1. No free-form
// code. Output: "@@ST " JSON lines (one final result). Usage: node stress-bot.js <script.json> <run marker>

const fs = require("fs");
const path = require("path");
const net = require("net");
const L = require("./lib.js");

const now = () => Date.now();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clip = (s, n = 200) => String(s).replace(/\s+/g, " ").slice(0, n);
const emit = (o) => process.stdout.write("@@ST " + JSON.stringify(o) + "\n");
const within = (p, ms) => Promise.race([p, sleep(ms).then(() => { throw new Error(`timeout after ${ms} ms`); })]);

function rconConnect(port, password, timeoutMs) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let buf = Buffer.alloc(0), nextId = 900;
    const waiters = [];
    const timer = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
    sock.on("data", (d) => { buf = Buffer.concat([buf, d]); const { packets, rest } = L.rconParse(buf); buf = rest; for (const p of packets) for (const w of [...waiters]) w(p); });
    sock.on("error", (e) => { clearTimeout(timer); reject(e); });
    const request = (type, body, maxMs = timeoutMs) => new Promise((res, rej) => {
      const id = nextId++;
      let text = "", q = null, got = false;
      const done = () => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); res(text); };
      const w = (p) => {
        if (p.id === -1 && type === 3) { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); rej(new Error("rcon auth refused")); return; }
        if (p.id !== id) return;
        got = true; text += p.body; clearTimeout(q); q = setTimeout(done, type === 3 ? 0 : 150);
      };
      const hard = setTimeout(() => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(q); got ? res(text) : rej(new Error(`rcon timeout after ${maxMs} ms`)); }, maxMs);
      waiters.push(w);
      sock.write(L.rconPacket(id, type, body));
    });
    sock.on("connect", async () => {
      clearTimeout(timer);
      try { await request(3, password); resolve({ command: (c, ms) => request(2, c, ms), close: () => sock.destroy() }); } catch (e) { sock.destroy(); reject(e); }
    });
  });
}

async function main() {
  const script = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
  const username = "NxStress";
  const result = { schema: 1, username, joined: false, placed: 0, broken: 0, failed: 0, teleports: 0, notes: [], bot: { mineflayer: null } };
  const deadline = now() + script.seconds * 1000;
  const guard = setTimeout(() => { result.notes.push("stress bot hard timeout"); finish(); }, script.seconds * 1000 + 40000);
  let finished = false;
  function finish() { if (finished) return; finished = true; clearTimeout(guard); emit({ ev: "result", result }); setTimeout(() => process.exit(0), 200); }

  let mineflayer, Vec3;
  try {
    mineflayer = require(path.join(script.modulesDir, "mineflayer"));
    Vec3 = require(path.join(script.modulesDir, "vec3")).Vec3;
    result.bot.mineflayer = require(path.join(script.modulesDir, "mineflayer/package.json")).version;
  } catch (e) { result.notes.push(`mineflayer not available: ${clip(e.message)}`); return finish(); }
  let rcon = null;
  try { rcon = await rconConnect(script.rconPort, script.rconPassword, 10000); } catch (e) { result.notes.push(`stress bot RCON unavailable: ${clip(e.message)}`); }

  const bot = mineflayer.createBot({ host: "127.0.0.1", port: script.port, username, version: script.version, auth: "offline", hideErrors: true, checkTimeoutInterval: 120000, logErrors: false });
  let ended = null;
  bot.on("error", (e) => result.notes.push(`bot error: ${clip(e && e.message)}`));
  bot.on("end", (reason) => { ended = ended || clip(reason || "end"); });
  bot.on("kicked", (reason) => { ended = `kicked: ${clip(typeof reason === "string" ? reason : JSON.stringify(reason))}`; });
  const joined = await new Promise((resolve) => {
    const t = setTimeout(() => resolve(false), 30000);
    bot.once("spawn", () => { clearTimeout(t); resolve(true); });
    bot.once("end", () => { clearTimeout(t); resolve(false); });
  });
  if (!joined) { result.notes.push(ended ? `could not join: ${ended}` : "did not spawn within 30 s"); try { bot.quit(); } catch { /* */ } if (rcon) rcon.close(); return finish(); }
  result.joined = true;
  emit({ ev: "joined", at: now() });
  try {
    if (rcon) { await rcon.command(`gamemode creative ${username}`, 8000); await rcon.command(`give ${username} minecraft:stone 64`, 8000); }
  } catch (e) { result.notes.push(`setup: ${clip(e.message)}`); }
  await sleep(800);
  const spots = [[0, 0], [40, 24], [-48, 40], [72, -40], [-24, -88], [104, 72], [-120, -24], [56, 128], [-96, 104], [136, -112]];
  let spot = 0, lastTp = now(), k = 0;
  const offs = [[2, 0], [0, 2], [-2, 0], [0, -2]];
  while (now() < deadline && !ended) {
    try {
      if (now() - lastTp > 8000 && rcon) {
        spot = (spot + 1) % spots.length;
        const [x, z] = spots[spot];
        await rcon.command(`tp ${username} ${x + 0.5} -60 ${z + 0.5}`, 10000);
        result.teleports++; lastTp = now();
        await sleep(1200);
        continue;
      }
      const stone = bot.inventory.items().find((i) => i.name === "stone");
      if (stone && (!bot.heldItem || bot.heldItem.name !== "stone")) await within(bot.equip(stone, "hand"), 3000);
      const [dx, dz] = offs[k++ % offs.length];
      const base = bot.entity.position.floored();
      const target = base.offset(dx, 0, dz);
      const ground = bot.blockAt(target.offset(0, -1, 0));
      const at = bot.blockAt(target);
      if (ground && at && at.name === "air" && ground.name !== "air") {
        await within(bot.placeBlock(ground, new Vec3(0, 1, 0)), 4000);
        result.placed++;
      }
      const placed = bot.blockAt(target);
      if (placed && placed.name !== "air") { await within(bot.dig(placed, true), 4000); result.broken++; }
      await sleep(150);
    } catch (e) {
      result.failed++;
      if (result.notes.length < 8) result.notes.push(`action: ${clip(e && e.message, 120)}`);
      await sleep(300);
    }
  }
  if (ended) result.notes.push(`disconnected: ${ended}`);
  try { bot.quit("stress done"); } catch { /* gone */ }
  if (rcon) rcon.close();
  await sleep(300);
  finish();
}

main().catch((e) => { emit({ ev: "result", result: { schema: 1, joined: false, placed: 0, broken: 0, failed: 0, teleports: 0, notes: [`stress bot crashed: ${clip(e && (e.stack || e.message), 400)}`] } }); setTimeout(() => process.exit(0), 200); });
"use strict";
// Cyrus Test Flight STRESS phase (runner tf-lite-5): pure helpers shared by runner.js, stress-bot.js and the repo tests.
// After the boot checks, a scripted load runs against the disposable server (RCON summons of passive mobs, forced
// chunk loads, the mod's own commands, and on versions with a verified bot a Mineflayer player placing/breaking blocks
// and teleporting) while the runner samples the REAL tick rate (Δ `time query gametime` / Δ wall clock), Paper's MSPT,
// the entity count and the JVM's RSS. The verdict uses thresholds from the spec. TypeScript twin of the judge:
// lib/cyrus/testflight/stress.ts (parity-tested). No I/O here.

const STRESS_DEFAULTS = Object.freeze({
  seconds: 40, baselineSec: 6, sampleMs: 2000,
  summon: Object.freeze({ entity: "minecraft:pig", perSecond: 2, max: 80 }),
  chunks: Object.freeze({ perSecond: 4, max: 160 }),
  bot: true,
  commands: Object.freeze([]),
});
const THRESHOLD_DEFAULTS = Object.freeze({ tpsFail: 15, tpsWarn: 18, sustainSec: 10, msptWarn: 50, entityMax: 2500, stallSec: 10, rssGrowthWarnMb: 400 });
/** Only passive, harmless mobs are summoned (peaceful world; hostile mobs despawn or throw on 26.x). */
const PASSIVE_RE = /^(minecraft:)?(pig|cow|chicken|sheep|rabbit|cod|salmon|bat|armor_stand|villager)$/;
const COMMAND_RE = /^[a-z0-9_-]{1,32}( [a-z0-9_.:-]{1,32}){0,2}$/;
const RESERVED_RE = /^(stop|restart|reload|op|deop|kick|ban|ban-ip|pardon|whitelist|save-off|save-all|forceload|kill|execute|summon|tp|teleport|gamemode|fill|setblock|clone|time|gamerule|minecraft:)/i;
/** Words that would switch the mod off and fake a pass: never sent as stress commands. */
const SWITCH_OFF_RE = /\b(off|disable|stop|pause|toggle|reset|clear|remove|delete|uninstall|reload|unload|purge|wipe|perf)\b/i;
const intIn = (v, lo, hi) => Number.isInteger(v) && v >= lo && v <= hi;

function validateStress(s) {
  const e = [];
  if (!s || typeof s !== "object" || Array.isArray(s)) return ["stress must be an object"];
  if (s.seconds != null && !intIn(s.seconds, 10, 120)) e.push("stress.seconds must be 10-120");
  if (s.baselineSec != null && !intIn(s.baselineSec, 2, 20)) e.push("stress.baselineSec must be 2-20");
  if (s.sampleMs != null && !intIn(s.sampleMs, 500, 5000)) e.push("stress.sampleMs must be 500-5000");
  if (s.summon != null) {
    if (!PASSIVE_RE.test(String(s.summon.entity || ""))) e.push("stress.summon.entity must be a passive mob (pig, cow, chicken, sheep, rabbit, cod, salmon, bat, armor_stand, villager)");
    if (!intIn(s.summon.perSecond, 1, 10)) e.push("stress.summon.perSecond must be 1-10");
    if (!intIn(s.summon.max, 1, 300)) e.push("stress.summon.max must be 1-300");
  }
  if (s.chunks != null) {
    if (!intIn(s.chunks.perSecond, 1, 16)) e.push("stress.chunks.perSecond must be 1-16");
    if (!intIn(s.chunks.max, 1, 400)) e.push("stress.chunks.max must be 1-400");
  }
  if (s.bot != null && typeof s.bot !== "boolean") e.push("stress.bot must be a boolean");
  if (s.commands != null) {
    if (!Array.isArray(s.commands) || s.commands.length > 8) e.push("stress.commands: at most 8");
    else for (const [i, c] of s.commands.entries()) {
      if (typeof c !== "string" || !COMMAND_RE.test(c)) e.push(`stress.commands[${i}] must be a plain command label (+ up to 2 plain words)`);
      else if (RESERVED_RE.test(c) || SWITCH_OFF_RE.test(c)) e.push(`stress.commands[${i}]: '${c}' is reserved or would switch the mod off`);
    }
  }
  const t = s.thresholds || {};
  if (s.thresholds != null && (typeof s.thresholds !== "object" || Array.isArray(s.thresholds))) e.push("stress.thresholds must be an object");
  for (const [k, lo, hi] of [["tpsFail", 1, 19.9], ["tpsWarn", 1, 20], ["sustainSec", 2, 60], ["msptWarn", 10, 1000], ["entityMax", 50, 50000], ["stallSec", 2, 60], ["rssGrowthWarnMb", 50, 2000]]) {
    if (t[k] != null && !(typeof t[k] === "number" && t[k] >= lo && t[k] <= hi)) e.push(`stress.thresholds.${k} must be ${lo}-${hi}`);
  }
  if (t.tpsFail != null && t.tpsWarn != null && t.tpsWarn < t.tpsFail) e.push("stress.thresholds.tpsWarn must be >= tpsFail");
  return e;
}

function resolveStress(s) {
  return {
    seconds: s.seconds ?? STRESS_DEFAULTS.seconds,
    baselineSec: s.baselineSec ?? STRESS_DEFAULTS.baselineSec,
    sampleMs: s.sampleMs ?? STRESS_DEFAULTS.sampleMs,
    summon: s.summon === null ? null : { ...STRESS_DEFAULTS.summon, ...(s.summon || {}) },
    chunks: s.chunks === null ? null : { ...STRESS_DEFAULTS.chunks, ...(s.chunks || {}) },
    bot: s.bot ?? STRESS_DEFAULTS.bot,
    commands: [...(s.commands || [])],
    thresholds: { ...THRESHOLD_DEFAULTS, ...(s.thresholds || {}) },
  };
}

const strip = (s) => String(s || "").replace(/\u00a7[0-9a-fk-orx]/gi, "");
/** `time query gametime` -> "The time is 12345". */
function parseGametime(text) {
  const m = /time is (\d+)/i.exec(strip(text));
  return m ? Number(m[1]) : null;
}
/** Paper `mspt`: "Server tick times (avg/min/max) from last 5s, 10s, 1m:\n◴ 1.2/0.4/3.1, ..." -> the 5 s average. */
function parseMspt(text) {
  const m = /(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)/.exec(strip(text));
  return m ? Number(m[1]) : null;
}
/** `execute if entity @e` -> "Test passed, count: N" ("Test failed" = 0). */
function parseEntityCount(text) {
  const t = strip(text);
  const m = /count:\s*(\d+)/i.exec(t);
  if (m) return Number(m[1]);
  return /test failed/i.test(t) ? 0 : null;
}

/** Chunk coordinates on a square spiral around (0,0) starting at ring 2 (spawn chunks are loaded anyway), within ±limit. */
function spiralChunks(n, limit = 14) {
  const out = [];
  for (let r = 2; r <= limit && out.length < n; r++) {
    for (let x = -r; x <= r && out.length < n; x++) for (const z of [-r, r]) if (out.length < n) out.push([x, z]);
    for (let z = -r + 1; z <= r - 1 && out.length < n; z++) for (const x of [-r, r]) if (out.length < n) out.push([x, z]);
  }
  return out;
}

const median = (a) => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); const k = s.length >> 1; return s.length % 2 ? s[k] : (s[k - 1] + s[k]) / 2; };
const r2 = (v) => (v == null || !Number.isFinite(v) ? null : Math.round(v * 100) / 100);

/** Longest run (ms) of consecutive load samples matching pred (each sample covers its dtMs). */
function longestRun(samples, pred) {
  let best = 0, cur = 0;
  for (const s of samples) { if (pred(s)) { cur += s.dtMs || 0; best = Math.max(best, cur); } else cur = 0; }
  return best;
}

/**
 * Verdict for one stress run. samples: [{ phase: "baseline"|"load", dtMs, tps (null = stalled), mspt, entities, rssKb }].
 * extra: { crashed, crashDetail, botRan, exercised }. Never "pass" without load samples; a slow test host = not_run.
 */
function judgeStress(samples, thresholds, extra = {}) {
  const thr = { ...THRESHOLD_DEFAULTS, ...(thresholds || {}) };
  const base = samples.filter((s) => s.phase === "baseline" && s.tps != null).map((s) => s.tps);
  const load = samples.filter((s) => s.phase === "load");
  const tpsL = load.filter((s) => s.tps != null).map((s) => s.tps);
  const rss = samples.map((s) => s.rssKb).filter((x) => x > 0);
  const numbers = {
    baselineTps: r2(median(base)),
    tpsMin: r2(load.length ? Math.min(...load.map((s) => (s.tps == null ? 0 : s.tps))) : null),
    tpsMedian: r2(median(tpsL)),
    lowSec: r2(longestRun(load, (s) => s.tps == null || s.tps < thr.tpsFail) / 1000),
    warnSec: r2(longestRun(load, (s) => s.tps == null || s.tps < thr.tpsWarn) / 1000),
    stallSec: r2(longestRun(load, (s) => s.tps == null) / 1000),
    msptMax: r2(Math.max(0, ...load.map((s) => s.mspt || 0))),
    entitiesMax: Math.max(0, ...samples.map((s) => s.entities || 0)),
    rssPeakMb: rss.length ? Math.round(Math.max(...rss) / 1024) : null,
    rssGrowthMb: rss.length ? Math.round((Math.max(...rss) - rss[0]) / 1024) : null,
    loadSamples: load.length,
  };
  const reasons = [];
  let verdict;
  if (extra.crashed) { verdict = "fail"; reasons.push(`the server stopped during the stress test${extra.crashDetail ? `: ${extra.crashDetail}` : ""}`); }
  else if (!load.length) { verdict = "not_run"; reasons.push("no load samples were taken"); }
  else if (base.length && numbers.baselineTps < thr.tpsFail) { verdict = "not_run"; reasons.push(`the test server was already slow before any load (${numbers.baselineTps} TPS), so no verdict`); }
  else {
    const fails = [], warns = [];
    if (numbers.lowSec >= thr.sustainSec) fails.push(`TPS stayed under ${thr.tpsFail} for ${numbers.lowSec} s (lowest ${numbers.tpsMin})`);
    if (numbers.stallSec >= thr.stallSec) fails.push(`the server stopped answering for ${numbers.stallSec} s`);
    if (numbers.entitiesMax > thr.entityMax) fails.push(`entities ran away: ${numbers.entitiesMax} (limit ${thr.entityMax})`);
    if (!fails.length) {
      if (numbers.warnSec >= thr.sustainSec) warns.push(`TPS stayed under ${thr.tpsWarn} for ${numbers.warnSec} s (lowest ${numbers.tpsMin})`);
      if (longestRun(load, (s) => (s.mspt || 0) > thr.msptWarn) >= thr.sustainSec * 1000) warns.push(`MSPT stayed above ${thr.msptWarn} ms (max ${numbers.msptMax})`);
      if (numbers.rssGrowthMb != null && numbers.rssGrowthMb > thr.rssGrowthWarnMb) warns.push(`memory grew by ${numbers.rssGrowthMb} MB`);
    }
    verdict = fails.length ? "fail" : warns.length ? "warn" : "pass";
    reasons.push(...fails, ...warns);
    if (!reasons.length) reasons.push(`TPS held (median ${numbers.tpsMedian}, lowest ${numbers.tpsMin}) under load`);
  }
  return { verdict, reasons, numbers, thresholds: thr };
}

/** The Test Flight check status for a verdict ("warn" is a pass with evidence; the stored verdict keeps the warn). */
const checkStatusOf = (verdict) => (verdict === "fail" ? "fail" : verdict === "pass" || verdict === "warn" ? "pass" : "not_run");

module.exports = { STRESS_DEFAULTS, THRESHOLD_DEFAULTS, PASSIVE_RE, SWITCH_OFF_RE, validateStress, resolveStress, parseGametime, parseMspt, parseEntityCount, spiralChunks, judgeStress, checkStatusOf, longestRun };
