185	// ------------------------------------------------------------------ leak scan (by exact marker) ----
186	function procsWithMarker(marker) {
187	  const out = [];
188	  for (const d of fs.readdirSync("/proc")) {
189	    if (!/^\d+$/.test(d) || Number(d) === process.pid) continue;
190	    let cmd;
191	    try { cmd = fs.readFileSync(`/proc/${d}/cmdline`, "utf8"); } catch { continue; }
192	    if (cmd.split("\0").includes(marker)) out.push({ pid: Number(d), cmd: clip(cmd.replace(/\0/g, " "), 200) });
193	  }
194	  return out;
195	}
196	function killExact(pid, marker) {
197	  // Re-read the cmdline right before the kill so a recycled PID is never hit.
198	  try {
199	    const cmd = fs.readFileSync(`/proc/${pid}/cmdline`, "utf8");
200	    if (!cmd.split("\0").includes(marker)) return false;
201	    process.kill(pid, "SIGKILL");
202	    return true;
203	  } catch { return false; }
204	}
