357	/** Walk a directory without following symlinks: [{ rel, abs, size }] of regular files; throws on a symlink. */
358	function walkPlain(dir, rel = "", out = []) {
359	  for (const e of fs.readdirSync(path.join(dir, rel), { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
360	    const r = rel ? `${rel}/${e.name}` : e.name;
361	    if (e.isSymbolicLink()) throw new Error(`symlink refused: ${r}`);
362	    if (e.isDirectory()) walkPlain(dir, r, out);
363	    else if (e.isFile()) out.push({ rel: r, abs: path.join(dir, r), size: fs.statSync(path.join(dir, r)).size });
364	  }
365	  return out;
366	}
