368	/** Copy TF_ROOT/seeds/<from> into runDir/<to> (seed dirs are prepared by an operator; files are hashed + reported). */
369	const MAX_SEED_BYTES = 256 * 1024 * 1024;
370	function placeSeed(runDir, sd) {
371	  if (!L.SEED_NAME_RE.test(sd.from) || !L.SEED_TO_RE.test(sd.to) || sd.to.split("/").includes("..")) throw new Error(`refusing seed ${sd.from} -> ${sd.to}`);
372	  const src = path.join(TF_ROOT, "seeds", sd.from);
373	  if (!fs.lstatSync(src).isDirectory()) throw new Error(`seed ${sd.from} is not a directory`);
374	  const files = walkPlain(src);
375	  const bytes = files.reduce((a, f) => a + f.size, 0);
376	  if (bytes > MAX_SEED_BYTES) throw new Error(`seed ${sd.from} is larger than ${MAX_SEED_BYTES} bytes`);
377	  const dest = path.join(runDir, sd.to);
378	  if (!dest.startsWith(runDir + path.sep)) throw new Error(`seed escapes the run dir: ${sd.to}`);
379	  const h = crypto.createHash("sha256");
380	  for (const f of files) {
381	    const d = path.join(dest, f.rel);
382	    fs.mkdirSync(path.dirname(d), { recursive: true });
383	    fs.copyFileSync(f.abs, d);
384	    h.update(`${sha256File(f.abs)}  ${f.rel}\n`);
385	  }
386	  return { files: files.length, bytes, sha256: h.digest("hex") };
387	}
