389	/** Copy the requested server files out (or list a directory) after the stop. Never follows symlinks. */
390	const MAX_COLLECT_BYTES = 48 * 1024 * 1024;
391	function collectOut(runDir, spec) {
392	  const outDir = path.join(TF_ROOT, "collect", spec.runId);
393	  fs.mkdirSync(outDir, { recursive: true });
394	  const res = [];
395	  for (const [i, c] of (spec.collect || []).entries()) {
396	    if (!L.COLLECT_RE.test(c) || c.split("/").includes("..")) { res.push({ path: c, error: "refused" }); continue; }
397	    const abs = path.join(runDir, c.replace(/\/$/, ""));
398	    if (!abs.startsWith(runDir + path.sep)) { res.push({ path: c, error: "refused" }); continue; }
399	    let st;
400	    try { st = fs.lstatSync(abs); } catch { res.push({ path: c, error: "missing" }); continue; }
401	    if (st.isSymbolicLink()) { res.push({ path: c, error: "symlink" }); continue; }
402	    if (c.endsWith("/")) {
403	      if (!st.isDirectory()) { res.push({ path: c, error: "not a directory" }); continue; }
404	      let list = [];
405	      try { list = walkPlain(abs).map((f) => `${f.rel} ${f.size}`); } catch (e) { res.push({ path: c, error: e.message }); continue; }
406	      res.push({ path: c, kind: "listing", entries: list.length, listing: list.slice(0, 400) });
407	      continue;
408	    }
409	    if (!st.isFile()) { res.push({ path: c, error: "not a file" }); continue; }
410	    if (st.size > MAX_COLLECT_BYTES) { res.push({ path: c, error: `larger than ${MAX_COLLECT_BYTES} bytes` }); continue; }
411	    const dest = path.join(outDir, `${i}-${path.basename(abs)}`);
412	    fs.copyFileSync(abs, dest);
413	    res.push({ path: c, kind: "file", bytes: st.size, sha256: sha256File(dest), dest });
414	  }
415	  return res;
416	}
