418	/** Write a spec text file under runDir (path re-validated; parent dirs and file owned by the server uid). */
419	function writeServerFile(runDir, f) {
420	  if (!L.SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) throw new Error(`refusing server file path ${f.path}`);
421	  const dest = path.join(runDir, f.path);
422	  if (!dest.startsWith(runDir + path.sep)) throw new Error(`server file escapes the run dir: ${f.path}`);
423	  fs.mkdirSync(path.dirname(dest), { recursive: true });
424	  const tmp = `${dest}.tf-part`;
425	  fs.writeFileSync(tmp, f.content);
426	  fs.renameSync(tmp, dest);
427	  let d = path.dirname(dest);
428	  while (d.startsWith(runDir + path.sep)) { spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, d]); d = path.dirname(d); }
429	  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, dest]);
430	  return Buffer.byteLength(f.content, "utf8");
