433	// ------------------------------------------------------------------ RCON client ----
434	function rconConnect(port, password, timeoutMs) {
435	  return new Promise((resolve, reject) => {
436	    const sock = net.connect({ host: "127.0.0.1", port });
437	    let buf = Buffer.alloc(0);
438	    const waiters = [];
439	    let nextId = 100;
440	    const timer = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
441	    sock.on("data", (d) => {
442	      buf = Buffer.concat([buf, d]);
443	      const { packets, rest } = L.rconParse(buf);
444	      buf = rest;
445	      for (const p of packets) for (const w of waiters) w(p);
446	    });
447	    sock.on("error", (e) => { clearTimeout(timer); reject(e); });
448	    const request = (type, body, quietMs = 250, maxMs = timeoutMs) => new Promise((res, rej) => {
449	      const id = nextId++;
450	      let text = "", got = false, q = null;
451	      const done = () => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); clearTimeout(q); res({ id, text, got }); };
452	      const w = (p) => {
453	        if (p.id === -1 && type === 3) { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); rej(new Error("rcon auth refused")); return; }
454	        if (p.id !== id) return;
455	        got = true; text += p.body;
456	        clearTimeout(q); q = setTimeout(done, type === 3 ? 0 : quietMs);
457	      };
458	      const hard = setTimeout(() => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(q); got ? res({ id, text, got }) : rej(new Error(`rcon timeout after ${maxMs} ms`)); }, maxMs);
459	      waiters.push(w);
460	      sock.write(L.rconPacket(id, type, body));
461	    });
462	    sock.on("connect", async () => {
463	      clearTimeout(timer);
464	      try {
465	        await request(3, password);
466	        resolve({ command: (c, ms) => request(2, c, 250, ms), close: () => sock.destroy() });
467	      } catch (e) { sock.destroy(); reject(e); }
468	    });
469	  });
470	}
