476	  const T = Object.assign({ bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 }, spec.timeouts || {});
477	  const xmx = (spec.memory && spec.memory.xmxMb) || 1024;
478	  const rssCapKb = ((spec.memory && spec.memory.rssCapMb) || 1800) * 1024;
479	  const matchers = spec.logMatchers || L.DEFAULT_LOG_MATCHERS;
