695	/**
696	 * Run the playtest bot as uid 65534 inside this netns (heap cap, nice, hard timeout, exact-PID kill) and fold its result
697	 * into the `playtest` check. Server log lines written while a scenario ran are matched with the startup matchers: an
698	 * error logged during a scenario (e.g. an exception in a command handler) fails that scenario even if the bot saw the
699	 * expected outcome.
700	 */
701	async function stagePlaytest({ ctx, spec, C, out, lines, up, port, rconPort, rconPassword, matchers, ignores, notes }) {
702	  const chk = C.playtest;
703	  const plan = spec.playtest;
704	  if (!up) { chk.evidence.push("server not up; the playtest bot did not run"); return; }
705	  if (ctx.botError) { chk.evidence.push(`playtest bot unavailable: ${ctx.botError}`); return; }
706	  if (!PT.BOT_VERSIONS.includes(spec.version)) { chk.evidence.push(`no verified playtest bot for Minecraft ${spec.version} (verified: ${PT.BOT_VERSIONS.join(", ")})`); return; }
707	  const scriptPath = path.join(ctx.runDir, "tmp", "playtest.json");
708	  fs.writeFileSync(scriptPath, JSON.stringify({ port, rconPort, rconPassword, version: spec.version, plan, modulesDir: ctx.bot.modulesDir, lockSha256: ctx.bot.lockSha }), { mode: 0o600 });
709	  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, scriptPath]);
710	  const limitMs = ((plan.totalSec || PT.DEFAULTS.totalSec) + (plan.joinSec || PT.DEFAULTS.joinSec) + 20) * 1000;
711	  const fromLine = lines.length;
712	  const spans = {};
713	  let result = null, partial = "", stderr = "";
714	  const child = spawn("nice", ["-n", "10", "setpriv", `--reuid=${RUN_UID}`, `--regid=${RUN_UID}`, "--clear-groups", "--no-new-privs", "--",
715	    process.execPath, "--max-old-space-size=256", path.join(__dirname, "bot.js"), scriptPath, ctx.marker],
716	    { cwd: path.join(ctx.runDir, "tmp"), stdio: ["ignore", "pipe", "pipe"], env: { PATH: "/usr/bin:/bin", HOME: path.join(ctx.runDir, "tmp"), LANG: "C.UTF-8" } });
717	  const pid = child.pid;
718	  child.stdout.on("data", (d) => {
719	    const parts = (partial + d.toString("utf8")).split("\n");
720	    partial = parts.pop();
721	    for (const p of parts) {
722	      if (!p.startsWith("@@PT ")) continue;
723	      let ev; try { ev = JSON.parse(p.slice(5)); } catch { continue; }
724	      if (ev.ev === "scenario" && ev.phase === "start") spans[ev.id] = { from: lines.length, to: null };
725	      if (ev.ev === "scenario" && ev.phase === "end" && spans[ev.id]) spans[ev.id].to = lines.length;
726	      if (ev.ev === "result") result = ev.result;
727	    }
728	  });
729	  child.stderr.on("data", (d) => { if (stderr.length < 4000) stderr += d.toString("utf8"); });
730	  const exitP = new Promise((r) => child.on("exit", (code, sig) => r({ code, sig })));
731	  const ex = await Promise.race([exitP, sleep(limitMs).then(() => null)]);
732	  if (!ex) {
733	    if (killExact(pid, ctx.marker)) chk.evidence.push(`bot pid ${pid} over its ${limitMs} ms limit -> SIGKILL`);
734	    await Promise.race([exitP, sleep(3000)]);
735	  }
736	  await sleep(500); // let the server log the disconnect
737	  if (!result) { chk.evidence.push(`the bot produced no result (exit ${ex ? ex.code : "killed"})${stderr ? ": " + clip(stderr, 300) : ""}`); return; }
738	  // Server-side errors while each scenario ran.
739	  const { hits } = L.matchLogDetailed(lines, matchers, ignores, fromLine, lines.length);
740	  for (const sc of result.scenarios || []) {
741	    const sp = spans[sc.id];
742	    if (!sp) continue;
743	    const mine = hits.filter((h) => h.line - 1 >= sp.from && h.line - 1 < (sp.to == null ? lines.length : sp.to));
744	    if (mine.length) {
745	      sc.logHits = mine.slice(0, 6).map((h) => `L${h.line} [${h.matcher}] ${clip(h.text, 200)}`);
746	      if (sc.status === "pass") { sc.status = "fail"; sc.failedBy = "server_log"; }
747	    }
748	  }
749	  const outside = hits.filter((h) => !Object.values(spans).some((sp) => h.line - 1 >= sp.from && h.line - 1 < (sp.to == null ? lines.length : sp.to)));
750	  chk.status = PT.playtestCheckStatus(result);
751	  if (outside.length && chk.status === "pass") chk.status = "fail";
752	  const b = result.bot || {};
753	  chk.evidence.push(result.joined
754	    ? `bot ${result.username} joined Paper ${spec.version} in ${result.joinMs} ms (mineflayer ${b.mineflayer}, minecraft-protocol ${b.minecraftProtocol}, op ${result.op})`
755	    : `bot did not join: ${(result.notes || []).slice(-1)[0] || "no detail"}`);
756	  for (const sc of result.scenarios || []) {
757	    const bad = (sc.steps || []).find((s) => s.status !== "pass");
758	    chk.evidence.push(`${sc.id} ${sc.status.toUpperCase()} (${(sc.steps || []).filter((s) => s.status === "pass").length}/${(sc.steps || []).length} steps, ${sc.ms} ms)${bad ? ` at step ${bad.i + 1} ${bad.kind}: ${clip(bad.evidence.join("; "), 220)}` : ""}${sc.logHits ? ` server log: ${sc.logHits[0]}` : ""}`);
759	  }
760	  if (outside.length) chk.evidence.push(...outside.slice(0, 4).map((h) => `server log during the playtest (no scenario): L${h.line} [${h.matcher}] ${clip(h.text, 200)}`));
761	  for (const n of (result.notes || []).slice(0, 6)) notes.push(`playtest: ${clip(n, 300)}`);
762	  // Bound the stored result: evidence lines are already clipped by the bot; cap counts.
763	  for (const sc of result.scenarios || []) for (const st of sc.steps || []) st.evidence = (st.evidence || []).slice(0, 4);
764	  out.playtest = result;
765	}
