767	/**
768	 * STRESS (tf-lite-5). Baseline samples, then for `seconds`: RCON summons of passive mobs (tagged nxstress), forced
769	 * chunk loads on a spiral, the mod's commands once, and (verified bot versions only) the stress bot placing/breaking
770	 * blocks and teleporting. A second RCON connection carries the load so the sampler is never queued behind it. Every
771	 * sample: real TPS = delta `time query gametime` / delta wall clock (a reply slower than stallSec = a stall), Paper MSPT,
772	 * entity count, RSS. Afterwards the load is removed (kill non-players, forceload remove all) before the clean stop.
773	 */
774	async function stageStress({ ctx, spec, C, out, lines, up, pid, port, rconPort, rconPassword, rcon, exitedNow, notes, matchers, ignores }) {
775	  const chk = C.stress;
776	  const S = SL.resolveStress(spec.stress);
777	  const thr = S.thresholds;
778	  const res = { schema: 1, plan: { seconds: S.seconds, baselineSec: S.baselineSec, sampleMs: S.sampleMs, summon: S.summon, chunks: S.chunks, bot: S.bot, commands: S.commands }, samples: [], load: { summoned: 0, chunks: 0, commands: [], bot: null, botRan: false }, log: { cantKeepUp: 0, watchdogPaused: null, errors: [] } };
779	  const done = (j, extra = []) => {
780	    res.verdict = j.verdict; res.reasons = j.reasons; res.numbers = j.numbers; res.thresholds = j.thresholds;
781	    chk.status = SL.checkStatusOf(j.verdict);
782	    chk.evidence.push(`stress ${j.verdict.toUpperCase()}: ${j.reasons.join("; ")}`.slice(0, 400), ...extra);
783	    out.stress = res;
784	  };
785	  if (!up || !rcon) { done({ verdict: "not_run", reasons: [up ? "RCON unavailable" : "server not up"], numbers: {}, thresholds: thr }); return; }
786	  let load = null;
787	  try { load = await rconConnect(rconPort, rconPassword, 10000); } catch (e) { notes.push(`stress: load RCON unavailable (${e.message}); only the bot loads the server`); }
788	  const rssKb = () => { try { return Number((/VmRSS:\s+(\d+)/.exec(fs.readFileSync(`/proc/${pid}/status`, "utf8")) || [])[1] || 0); } catch { return 0; } };
789	  const stallMs = thr.stallSec * 1000;
790	  const start = now();
791	  let anchor = null, lastAt = null;
792	  const take = async (phase) => {
793	    let gt = null;
794	    try { gt = SL.parseGametime((await rcon.command("time query gametime", stallMs)).text); } catch { gt = null; }
795	    const at = now();
796	    let mspt = null, ent = null;
797	    if (gt != null) {
798	      try { mspt = SL.parseMspt((await rcon.command("mspt", 3000)).text); } catch { /* not Paper / slow */ }
799	      try { ent = SL.parseEntityCount((await rcon.command("execute if entity @e", 3000)).text); } catch { /* slow */ }
800	    }
801	    if (anchor && lastAt != null) {
802	      const tps = gt != null && at > anchor.at ? Math.min(20, (gt - anchor.gt) / ((at - anchor.at) / 1000)) : null;
803	      res.samples.push({ phase, t: at - start, dtMs: at - lastAt, tps: tps == null ? null : Math.round(tps * 100) / 100, mspt, entities: ent, rssKb: rssKb() });
804	    }
805	    if (gt != null) anchor = { gt, at };
806	    lastAt = at;
807	  };
808	  const tick = async (from, ms) => { const wait = from + ms - now(); if (wait > 0) await sleep(wait); };
809	  await take("anchor");
810	  while (now() - start < S.baselineSec * 1000 && !exitedNow()) { const t0 = now(); await tick(t0, S.sampleMs); await take("baseline"); }
811	  // ---- load
812	  const fromLine = lines.length;
813	  const loadStart = now();
814	  let stop = false;
815	  const spiral = SL.spiralChunks(S.chunks ? S.chunks.max : 0);
816	  const loadLoop = (async () => {
817	    if (!load) return;
818	    let sentCommands = false;
819	    while (!stop && !exitedNow()) {
820	      const t0 = now();
821	      try {
822	        if (S.summon) for (let i = 0; i < S.summon.perSecond && res.load.summoned < S.summon.max && !stop; i++) {
823	          const x = Math.floor(Math.random() * 48) - 24, z = Math.floor(Math.random() * 48) - 24;
824	          await load.command(`summon ${S.summon.entity} ${x} -60 ${z} {Tags:["nxstress"]}`, stallMs);
825	          res.load.summoned++;
826	        }
827	        if (S.chunks) for (let i = 0; i < S.chunks.perSecond && res.load.chunks < spiral.length && !stop; i++) {
828	          const [cx, cz] = spiral[res.load.chunks];
829	          await load.command(`forceload add ${cx * 16} ${cz * 16}`, stallMs);
830	          res.load.chunks++;
831	        }
832	        if (!sentCommands && now() - loadStart > (S.seconds * 1000) / 3) {
833	          sentCommands = true;
834	          for (const c of S.commands) {
835	            try { const r = await load.command(c, stallMs); res.load.commands.push({ command: c, reply: clip(L.stripColors(r.text).replace(/\n/g, " | "), 160) }); }
836	            catch (e) { res.load.commands.push({ command: c, error: clip(e.message, 120) }); }
837	          }
838	        }
839	      } catch (e) { if (res.log.errors.length < 4) res.log.errors.push(`load: ${clip(e.message, 160)}`); }
840	      await tick(t0, 1000);
841	    }
842	  })();
843	  // the stress bot (verified versions only)
844	  let botP = Promise.resolve(null);
845	  if (S.bot) {
846	    if (!PT.BOT_VERSIONS.includes(spec.version)) res.load.bot = { ran: false, reason: `no verified bot for Minecraft ${spec.version} (verified: ${PT.BOT_VERSIONS.join(", ")}): block place/break not exercised` };
847	    else if (ctx.botError || !ctx.bot) res.load.bot = { ran: false, reason: `bot unavailable: ${ctx.botError || "not installed"}` };
848	    else botP = runStressBot(ctx, spec, { port, rconPort, rconPassword, seconds: S.seconds });
849	  }
850	  while (now() - loadStart < S.seconds * 1000 && !exitedNow()) { const t0 = now(); await tick(t0, S.sampleMs); await take("load"); }
851	  stop = true;
852	  await Promise.race([loadLoop, sleep(stallMs + 5000)]);
853	  const br = await Promise.race([botP, sleep(20000).then(() => ({ ran: true, reason: "bot result late" }))]);
854	  if (br) { res.load.bot = br; res.load.botRan = !!(br.joined && (br.placed || br.broken)); }
855	  // server log while loaded: lag warnings, the watchdog's own pause line, errors
856	  for (let i = fromLine; i < lines.length; i++) {
857	    const l = lines[i];
858	    if (/Can't keep up!/.test(l)) res.log.cantKeepUp++;
859	    if (!res.log.watchdogPaused && /\[NxPerf\] PAUSED/.test(l)) res.log.watchdogPaused = { atSec: null, line: clip(l, 300) };
860	  }
861	  const { hits } = L.matchLogDetailed(lines, matchers, ignores, fromLine, lines.length);
862	  for (const h of hits.slice(0, 4)) res.log.errors.push(`L${h.line} [${h.matcher}] ${clip(h.text, 200)}`);
863	  // cleanup before the clean stop
864	  if (!exitedNow()) {
865	    const c = load || rcon;
866	    for (const cmd of ["kill @e[type=!player]", "forceload remove all"]) { try { await c.command(cmd, 30000); } catch (e) { notes.push(`stress cleanup '${cmd}': ${e.message}`); } }
867	  }
868	  if (load) load.close();
869	  const crashed = !!exitedNow();
870	  const j = SL.judgeStress(res.samples, thr, { crashed, crashDetail: crashed ? `exit code ${exitedNow().code}, signal ${exitedNow().sig}` : null });
871	  const n = j.numbers;
872	  done(j, [
873	    `load: ${res.load.summoned} ${S.summon ? S.summon.entity : "-"} summoned, ${res.load.chunks} chunks force-loaded, ${res.load.commands.length} mod command(s), bot ${res.load.bot ? (res.load.bot.ran === false ? "not run (" + res.load.bot.reason + ")" : `placed ${res.load.bot.placed || 0} / broke ${res.load.bot.broken || 0} / teleported ${res.load.bot.teleports || 0}`) : "off"}`.slice(0, 400),
874	    `numbers: baseline ${n.baselineTps} TPS, load median ${n.tpsMedian} min ${n.tpsMin}, under ${thr.tpsFail} for ${n.lowSec} s, stall ${n.stallSec} s, MSPT max ${n.msptMax}, entities max ${n.entitiesMax}, RSS peak ${n.rssPeakMb} MB (+${n.rssGrowthMb})`,
875	    `log while loaded: ${res.log.cantKeepUp} "Can't keep up" line(s)${res.log.watchdogPaused ? `, watchdog: ${res.log.watchdogPaused.line}` : ""}${res.log.errors.length ? `, ${res.log.errors.length} error line(s)` : ""}`.slice(0, 400),
876	  ]);
877	  res.samples = res.samples.slice(0, 120);
878	}
