880	/** The stress bot as uid 65534 inside this netns (heap cap, nice, hard timeout, exact-PID kill). Resolves its result or a reason. */
881	async function runStressBot(ctx, spec, o) {
882	  const scriptPath = path.join(ctx.runDir, "tmp", "stress.json");
883	  fs.writeFileSync(scriptPath, JSON.stringify({ port: o.port, rconPort: o.rconPort, rconPassword: o.rconPassword, version: spec.version, seconds: o.seconds, modulesDir: ctx.bot.modulesDir }), { mode: 0o600 });
884	  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, scriptPath]);
885	  let result = null, partial = "", stderr = "";
886	  const child = spawn("nice", ["-n", "10", "setpriv", `--reuid=${RUN_UID}`, `--regid=${RUN_UID}`, "--clear-groups", "--no-new-privs", "--",
887	    process.execPath, "--max-old-space-size=256", path.join(__dirname, "stress-bot.js"), scriptPath, ctx.marker],
888	    { cwd: path.join(ctx.runDir, "tmp"), stdio: ["ignore", "pipe", "pipe"], env: { PATH: "/usr/bin:/bin", HOME: path.join(ctx.runDir, "tmp"), LANG: "C.UTF-8" } });
889	  const pid = child.pid;
890	  child.stdout.on("data", (d) => {
891	    const parts = (partial + d.toString("utf8")).split("\n");
892	    partial = parts.pop();
893	    for (const p of parts) { if (!p.startsWith("@@ST ")) continue; try { const ev = JSON.parse(p.slice(5)); if (ev.ev === "result") result = ev.result; } catch { /* partial */ } }
894	  });
895	  child.stderr.on("data", (d) => { if (stderr.length < 2000) stderr += d.toString("utf8"); });
896	  const exitP = new Promise((r) => child.on("exit", (code, sig) => r({ code, sig })));
897	  const limitMs = (o.seconds + 45) * 1000;
898	  const ex = await Promise.race([exitP, sleep(limitMs).then(() => null)]);
899	  if (!ex) { killExact(pid, ctx.marker); await Promise.race([exitP, sleep(3000)]); }
900	  if (!result) return { ran: false, reason: `the stress bot produced no result (exit ${ex ? ex.code : "killed"})${stderr ? ": " + clip(stderr, 200) : ""}` };
901	  return { ran: true, ...result };
902	}
903	
904	// ------------------------------------------------------------------ main ----
905	(async () => {
906	  const [cmd, arg] = process.argv.slice(2);
907	  try {
908	    if (cmd === "run" && arg) process.exitCode = stageRun(arg);
909	    else if (cmd === "locked" && arg) process.exitCode = await stageLocked(arg);
910	    // Exit explicitly: a pending race timer (stop timeout) must not keep the inner stage alive.
911	    else if (cmd === "inner" && arg) process.exit(await stageInner(arg));
912	    else if (cmd === "setup" && arg) { const j = await ensureJdk(Number(arg)); process.stdout.write(JSON.stringify({ home: j.home, release: j.release, sha256: j.sha256, fetched: j.fetched, version: jdkVersion(j.home) }) + "\n"); }
913	    else { process.stderr.write("usage: runner.js run <spec.json> | setup <21|25>\n"); process.exitCode = 2; }
914	  } catch (e) {
915	    log(`fatal: ${e.stack || e.message}`);
916	    process.exitCode = 1;
917	  }
918	})();
