304	/** Fails closed: unknown version, blocked version, or no generated vanilla ids for it (ids are needed to check the design). */
305	export function designFeatures(version: string): FeaturesResult {
306	  const row = getVersion(version);
307	  if (!row) return { ok: false, error: `Minecraft ${version} is not in the version registry` };
308	  if (row.status === "blocked") return { ok: false, error: `Minecraft ${version} is blocked in the version registry` };
309	  if (!vanillaIds("item", version).size) return { ok: false, error: `Cyrus has no vanilla id list for Minecraft ${version} yet (needs a pinned server jar on the build host)` };
310	  return { ok: true, features: { version, itemModel: row.capabilities.includes("itemModelDefinitions"), attributeNames: compareMc(version, "1.21.3") >= 0 ? "plain" : "generic-prefix", javaRelease: row.javaRelease, scheduling: "paper" } };
311	}
