333	export const DESIGN_CHECKS = ["schema", "namespace", "vanilla_ids", "references", "context", "budget", "version_features", "limits"] as const;
334	const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");
