336	/** Which triggers give the activation a target entity (possibly absent at runtime) / a point other than the player. */
337	export const TRIGGER_HAS_TARGET: Record<TriggerType, "always" | "maybe" | "never"> = {
338	  right_click: "maybe", sneak_right_click: "maybe", charge_release: "maybe", left_click_hit_entity: "always", kill_entity: "always", projectile_hit: "maybe",
339	  held_interval: "never", join: "never", death: "never", item_consume: "never",
340	};
341	const isBlockItem = (id: string, v: string) => vanillaIds("block", v).has(id);
