343	/** Static worst case of one action list (multiplicity = how many times the list runs per activation). */
344	export function budgetOf(list: Action[], mult = 1, depth = 1): { actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number } {
345	  const t = { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0, nodes: 0, depth };
346	  for (const a of list) {
347	    t.actions += mult; t.nodes += 1;
348	    const add = (b: ReturnType<typeof budgetOf>) => { t.actions += b.actions; t.entities += b.entities; t.tasks += b.tasks; t.particles += b.particles; t.projectiles += b.projectiles; t.nodes += b.nodes; t.depth = Math.max(t.depth, b.depth); };
349	    switch (a.type) {
350	      case "damage": case "heal": case "potion_effect": case "knockback": case "pull_to": case "push_from": case "apply_mark": t.entities += mult; break;
351	      case "spawn_particles": t.particles += a.count * mult; break;
352	      case "launch_projectile": t.projectiles += mult; t.tasks += mult; break; // the lifetime task
353	      case "query_marked": case "query_nearby": add(budgetOf(a.actions, mult * a.max, depth + 1)); break;
354	      case "delayed": t.tasks += mult; add(budgetOf(a.actions, mult, depth + 1)); break;
355	      case "branch": { const th = budgetOf(a.then, mult, depth + 1), el = a.else ? budgetOf(a.else, mult, depth + 1) : null; t.nodes += th.nodes + (el?.nodes ?? 0) + a.if.length;
356	        // worst case = the heavier branch for each counter
357	        for (const k of ["actions", "entities", "tasks", "particles", "projectiles"] as const) t[k] += Math.max(th[k], el?.[k] ?? 0);
358	        t.depth = Math.max(t.depth, th.depth, el?.depth ?? 0); break; }
359	      default: break;
360	    }
361	  }
362	  return t;
363	}
364	
365	/** Walk every action (pre-order) with its path ("a0", "a1.n0", "a2.then0", "a2.else1"). */
366	export function walkActions(list: Action[], fn: (a: Action, path: string, inLoop: boolean) => void, prefix = "", inLoop = false): void {
367	  list.forEach((a, i) => {
368	    const here = prefix ? `${prefix}${i}` : `a${i}`;
369	    fn(a, here, inLoop);
370	    if (a.type === "query_marked" || a.type === "query_nearby") walkActions(a.actions, fn, `${here}.n`, true);
371	    else if (a.type === "delayed") walkActions(a.actions, fn, `${here}.n`, inLoop);
372	    else if (a.type === "branch") { walkActions(a.then, fn, `${here}.then`, inLoop); if (a.else) walkActions(a.else, fn, `${here}.else`, inLoop); }
373	  });
374	}
375	/** Every condition of an ability with its path ("c0", "a2.if0"). */
376	export function walkConditions(ab: Ability, fn: (c: Condition, path: string, inLoop: boolean) => void): void {
377	  (ab.conditions ?? []).forEach((c, i) => fn(c, `c${i}`, false));
378	  walkActions(ab.actions, (a, p, inLoop) => { if (a.type === "branch") a.if.forEach((c, i) => fn(c, `${p}.if${i}`, inLoop)); });
379	}
