381	export function validateDesign(input: unknown, ctx: DesignContext): DesignValidation {
382	  const errors: DzIssue[] = [];
383	  const warnings: DzIssue[] = [];
384	  const bucket = new Map<string, string[]>(DESIGN_CHECKS.map((c) => [c, []]));
385	  const failed = new Set<string>();
386	  const ran = new Set<string>(["schema"]);
387	  const fail = (check: string, path: string, code: string, message: string) => { errors.push({ path, code, message }); failed.add(check); bucket.get(check)!.push(`${path}: ${message}`); };
388	  const warn = (check: string, path: string, code: string, message: string) => { warnings.push({ path, code, message }); bucket.get(check)!.push(`warn ${path}: ${message}`); };
389	  const budgets: AbilityBudget[] = [];
390	  const checksOf = (): DzCheck[] => DESIGN_CHECKS.map((id) => {
391	    const items = bucket.get(id)!;
392	    return { id, status: !ran.has(id) ? "not_run" : failed.has(id) ? "fail" : items.length ? "warn" : "pass", items: items.slice(0, 20) };
393	  });
394	  const bad = (): DesignValidation => ({ ok: false, errors, warnings, checks: checksOf(), budgets });
395	
396	  ran.add("namespace");
397	  if (!NAMESPACE_RE.test(ctx.namespace)) { fail("namespace", "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); return bad(); }
398	  ran.add("version_features");
399	  const fe = designFeatures(ctx.version);
400	  if (!fe.ok) { fail("version_features", "version", "unsupported_version", fe.error); return bad(); }
401	  const v = ctx.version;
402	  if (input && typeof input === "object" && !Array.isArray(input) && (input as { schemaVersion?: unknown }).schemaVersion !== undefined && (input as { schemaVersion?: unknown }).schemaVersion !== DESIGN_SPEC_VERSION) {
403	    fail("schema", "schemaVersion", "schema_version", `schemaVersion must be ${DESIGN_SPEC_VERSION}`); return bad();
404	  }
405	  const bytes = (() => { try { return new TextEncoder().encode(JSON.stringify(input)).length; } catch { return Infinity; } })();
406	  ran.add("limits");
407	  if (bytes > DESIGN_LIMITS.maxSpecBytes) { fail("limits", "(root)", "spec_size", `the design is ${bytes} bytes; the limit is ${DESIGN_LIMITS.maxSpecBytes}`); return bad(); }
408	  const parsed = ItemDesignSchema.safeParse(input);
409	  if (!parsed.success) {
410	    for (const i of parsed.error.issues.slice(0, 30)) fail("schema", issuePath(i.path) || "(root)", "schema", i.message);
411	    return bad();
412	  }
413	  const d = parsed.data;
414	  for (const c of ["vanilla_ids", "references", "context", "budget"]) ran.add(c);
415	  const ns = ctx.namespace;
416	  const id = buildIdentifier(ns, "item", d.id);
417	  if (!id.ok) fail("namespace", "id", "bad_id", id.error);
418	
419	  // base item
420	  const base = d.base.slice("minecraft:".length);
421	  if (!isVanilla("item", d.base, v)) fail("vanilla_ids", "base", "unknown_vanilla_id", missingIdReason("item", d.base, v));
422	  if (BANNED_BASES.test(base)) fail("context", "base", "banned_base", `${d.base} cannot be a design item's base (operator item, or its own right-click teleports/places/spawns)`);
423	  const clicks = d.abilities.some((a) => ["right_click", "sneak_right_click", "charge_release"].includes(a.trigger.type));
424	  if (clicks && isBlockItem(base, v)) fail("context", "base", "block_base", `${d.base} is a block: right-clicking would place it. Pick a non-block base item for click abilities`);
425	  const consume = d.abilities.some((a) => a.trigger.type === "item_consume");
426	  if (consume && !(CONSUMABLE_BASES as readonly string[]).includes(base)) fail("context", "base", "not_consumable", `item_consume needs an edible/drinkable base item (${CONSUMABLE_BASES.slice(0, 8).join(", ")}, ...); ${d.base} is not one`);
427	  if (d.stats && (d.stats.damage !== undefined) !== (d.stats.attackSpeed !== undefined)) fail("context", "stats", "stats_pair", "set damage and attackSpeed together: a custom attack modifier replaces the base item's default damage AND speed");
428	  if (d.stats?.durability !== undefined && d.stats.unbreakable) warn("context", "stats.durability", "unbreakable", "durability has no effect on an unbreakable item");
429	
430	  // assets
431	  if (d.assets?.model) {
432	    if (!d.assets.model.startsWith(`${ns}:`)) fail("namespace", "assets.model", "foreign_namespace", `the item model must be in this mod's namespace ${ns}`);
433	    else if (ctx.assets?.models && !ctx.assets.models.includes(d.assets.model)) warn("references", "assets.model", "asset_unresolved", `${d.assets.model}: this mod has no such item model (no custom texture for it, or your plan does not include custom textures), so the item keeps the ${d.base} look`);
434	    if (!fe.features.itemModel) warn("version_features", "assets.model", "item_model_unsupported", `custom item models need Minecraft 1.21.4 or newer; on ${v} the item keeps the ${d.base} look (a legacy custom_model_data emitter is not built)`);
435	  }
436	  const declaredSounds = new Set(d.assets?.sounds ?? []);
437	  const soundRef = (at: string, key: string) => {
438	    const kns = key.split(":")[0];
439	    if (kns === "minecraft") { warn("references", at, "vanilla_sound_unchecked", `${key}: vanilla sound keys are not checked against the game (a wrong key plays nothing)`); return; }
440	    if (kns !== ns) { fail("namespace", at, "foreign_namespace", `${key} uses the namespace ${kns}; sounds must be minecraft: or this mod's ${ns}`); return; }
441	    if (ctx.assets?.sounds && !ctx.assets.sounds.includes(key)) warn("references", at, "asset_unresolved", `${key}: this mod has no such custom sound (no sound set for it, or your plan does not include custom sounds), so it plays nothing`);
442	    else if (!ctx.assets?.sounds && declaredSounds.size && !declaredSounds.has(key)) warn("references", at, "sound_undeclared", `${key} is not listed in assets.sounds`);
443	  };
444	  (d.assets?.sounds ?? []).forEach((s, i) => { if (!s.startsWith(`${ns}:`) && !s.startsWith("minecraft:")) fail("namespace", `assets.sounds[${i}]`, "foreign_namespace", `${s} must be minecraft: or ${ns}:`); });
445	
