606	/** Validate a whole mod (all its design files): each file + cross-file duplicates. */
607	export function validateDesigns(inputs: unknown[], ctx: Omit<DesignContext, "items">): { ok: boolean; results: DesignValidation[]; errors: DzIssue[] } {
608	  const keys = inputs.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : "")).filter(Boolean);
609	  const errors: DzIssue[] = [];
610	  const maxItems = ctx.limits?.maxItems ?? DESIGN_LIMITS.maxItems;
611	  if (inputs.length > maxItems) errors.push({ path: "(mod)", code: "too_many_items", message: `${inputs.length} design items; the limit is ${maxItems}` });
612	  const dup = keys.find((k, i) => keys.indexOf(k) !== i);
613	  if (dup) errors.push({ path: "(mod)", code: "duplicate_item", message: `design item ${dup} is defined twice` });
614	  const results = inputs.slice(0, maxItems).map((x) => validateDesign(x, { ...ctx, items: keys }));
615	  return { ok: !errors.length && results.every((r) => r.ok), results, errors };
