67	export const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");
68	export const camel = (s: string) => s.split("_").filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("");
69	/** AC-3: user text inside a generated Java comment. Drops `\\` `*` `/`: javac decodes unicode escapes (\\u002a\\u002f = "*" "/")
70	 *  BEFORE lexing, and stripping only "*\/" lets "**\/\/" re-form it; either one closes the comment and the rest is code. */
71	export const javadocText = (s: string) => s.replace(/[\\*/]/g, "");
72	export const jstr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
73	export const ystr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
74	export const fmtNum = (v: number, kind: ParamKind) => (kind === "num" ? (Number.isInteger(v) ? v.toFixed(1) : String(v)) : String(Math.round(v)));
75	export const jnum = (v: number) => (Number.isInteger(v) ? `${v}.0` : String(v));
76	const fieldOf = (rel: string) => "p_" + rel.replace(/[.]/g, "_");
77	const COLOR_NAMES: Record<string, string> = { black: "BLACK", dark_blue: "DARK_BLUE", dark_green: "DARK_GREEN", dark_aqua: "DARK_AQUA", dark_red: "DARK_RED", dark_purple: "DARK_PURPLE", gold: "GOLD", gray: "GRAY", dark_gray: "DARK_GRAY", blue: "BLUE", green: "GREEN", aqua: "AQUA", red: "RED", light_purple: "LIGHT_PURPLE", yellow: "YELLOW", white: "WHITE" };
78	export const colorExpr = (c?: string) => (!c ? "null" : c.startsWith("#") ? `TextColor.color(0x${c.slice(1).toUpperCase()})` : `NamedTextColor.${COLOR_NAMES[c]}`);
79	const KIND_BITS: Record<string, number> = { player: 1, hostile: 2, animal: 4, living: 8 };
80	export const maskOf = (k?: string[]) => (k ?? []).reduce((m, x) => m | (KIND_BITS[x] ?? 0), 0);
81	export const bare = (id: string) => id.replace(/^minecraft:/, "");
82	export const MATERIAL = (id: string) => `Material.${bare(id).toUpperCase()}`;
