91	export type ParamSink = { params: Param[]; base: string; item: string; ability?: string; abilityName?: string };
92	export function addParam(s: ParamSink, rel: string, kind: ParamKind, cap: CapName | [number, number], value: number | string, label: string, role: string): Param {
93	  const [min, max] = Array.isArray(cap) ? cap : CAPS[cap as CapName];
94	  const p: Param = { path: s.base + rel, field: fieldOf(rel), kind, min, max, value, label: s.abilityName ? `${s.abilityName}: ${label}` : label, item: s.item, ...(s.ability ? { ability: s.ability } : {}), role };
95	  s.params.push(p);
96	  return p;
97	}
