100	export function abilityParams(item: ItemDesign, ab: Ability): Param[] {
101	  const s: ParamSink = { params: [], base: `items.${item.id}.abilities.${ab.id}.`, item: item.id, ability: ab.id, abilityName: ab.name };
102	  if (ab.cooldownTicks !== undefined) addParam(s, "cooldown_ticks", "ticks", "cooldownTicks", ab.cooldownTicks, "cooldown (ticks, 20 = 1 s)", "cooldown");
103	  if (ab.charges) { addParam(s, "charges.max", "int", "chargesMax", ab.charges.max, "charges", "charges"); addParam(s, "charges.regen_ticks", "ticks", "chargeRegenTicks", ab.charges.regenTicks, "ticks per charge regained", "cooldown"); }
104	  const t = ab.trigger;
105	  if ("targetRange" in t && t.targetRange !== undefined) addParam(s, "trigger.target_range", "num", "targetRange", t.targetRange, "target range (blocks)", "range");
106	  if (t.type === "held_interval") addParam(s, "trigger.period_ticks", "ticks", "periodTicks", t.periodTicks, "interval (ticks)", "cooldown");
107	  if (t.type === "charge_release") { addParam(s, "trigger.min_charge_ticks", "ticks", "minChargeTicks", t.minChargeTicks, "minimum charge (ticks)", "duration"); addParam(s, "trigger.max_charge_ticks", "ticks", "maxChargeTicks", t.maxChargeTicks, "full charge (ticks)", "duration"); }
108	  const cond = (c: Condition, rel: string) => {
109	    switch (c.type) {
110	      case "health_below": case "health_above": addParam(s, `${rel}.fraction`, "num", "healthFraction", c.fraction, `${c.type.replace("_", " ")} (fraction of max health)`, "other"); break;
111	      case "random_chance": addParam(s, `${rel}.chance`, "num", "chance", c.chance, "chance (0-1)", "chance"); break;
112	      case "time_of_day": addParam(s, `${rel}.from`, "int", "timeOfDay", c.from, "time window start (ticks)", "other"); addParam(s, `${rel}.to`, "int", "timeOfDay", c.to, "time window end (ticks)", "other"); break;
113	      case "charges_available": addParam(s, `${rel}.amount`, "int", "chargeCost", c.amount, "charges needed", "count"); break;
114	      default: break;
115	    }
116	  };
117	  (ab.conditions ?? []).forEach((c, i) => cond(c, `c${i}`));
118	  walkActions(ab.actions, (a, p) => {
119	    switch (a.type) {
120	      case "damage": addParam(s, `${p}.amount`, "num", "damage", a.amount, "damage (health points)", "damage"); break;
121	      case "heal": addParam(s, `${p}.amount`, "num", "heal", a.amount, "heal (health points)", "heal"); break;
122	      case "potion_effect": addParam(s, `${p}.duration_ticks`, "ticks", "potionTicks", a.durationTicks, `${a.effect} duration (ticks)`, "duration"); addParam(s, `${p}.amplifier`, "int", "amplifier", a.amplifier ?? DEFAULTS.amplifier, `${a.effect} level - 1`, "level"); break;
123	      case "knockback": case "pull_to": case "push_from": {
124	        const dv = a.type === "knockback" ? DEFAULTS.knockbackVertical : a.type === "pull_to" ? DEFAULTS.pullVertical : DEFAULTS.pushVertical;
125	        addParam(s, `${p}.strength`, "num", "strength", a.strength, `${a.type.replace("_", " ")} strength`, "strength"); addParam(s, `${p}.vertical`, "num", "vertical", a.vertical ?? dv, `${a.type.replace("_", " ")} lift`, "lift"); break;
126	      }
127	      case "teleport_short": addParam(s, `${p}.range`, "num", "teleportRange", a.range, "teleport range (blocks)", "range"); break;
128	      case "launch_projectile": addParam(s, `${p}.speed`, "num", "projectileSpeed", a.speed, `${a.kind} speed`, "speed"); addParam(s, `${p}.lifetime_ticks`, "ticks", "projectileLifetime", a.lifetimeTicks ?? DEFAULTS.lifetimeTicks, `${a.kind} lifetime (ticks)`, "duration"); break;
129	      case "spawn_particles": addParam(s, `${p}.count`, "int", "particleCount", a.count, `${a.particle} particles`, "count"); addParam(s, `${p}.spread`, "num", "particleSpread", a.spread ?? DEFAULTS.spread, `${a.particle} spread`, "other"); addParam(s, `${p}.speed`, "num", "particleSpeed", a.speed ?? DEFAULTS.particleSpeed, `${a.particle} speed`, "other"); break;
130	      case "play_sound": addParam(s, `${p}.sound`, "sound", [0, 100], a.sound, "sound key", "sound"); addParam(s, `${p}.volume`, "num", "volume", a.volume ?? DEFAULTS.volume, "sound volume", "other"); addParam(s, `${p}.pitch`, "num", "pitch", a.pitch ?? DEFAULTS.pitch, "sound pitch", "other"); break;
131	      case "send_message": case "actionbar": addParam(s, `${p}.text`, "text", [0, RUNTIME_CAPS.textChars], a.text, a.type === "actionbar" ? "actionbar text" : "message text", "text"); break;
132	      case "title":
133	        addParam(s, `${p}.title`, "text", [0, RUNTIME_CAPS.titleChars], a.title, "title text", "text");
134	        if (a.subtitle !== undefined) addParam(s, `${p}.subtitle`, "text", [0, RUNTIME_CAPS.subtitleChars], a.subtitle, "subtitle text", "text");
135	        addParam(s, `${p}.fade_in_ticks`, "ticks", "titleFadeTicks", a.fadeInTicks ?? DEFAULTS.fadeInTicks, "title fade in", "duration");
136	        addParam(s, `${p}.stay_ticks`, "ticks", "titleStayTicks", a.stayTicks ?? DEFAULTS.stayTicks, "title stay", "duration");
137	        addParam(s, `${p}.fade_out_ticks`, "ticks", "titleFadeTicks", a.fadeOutTicks ?? DEFAULTS.fadeOutTicks, "title fade out", "duration");
138	        break;
139	      case "give_item": addParam(s, `${p}.count`, "int", "giveCount", a.count ?? DEFAULTS.giveCount, `${a.item} count`, "count"); break;
140	      case "set_cooldown": {
141	        const ref = item.abilities.find((x) => x.id === (a.ability ?? ab.id));
142	        addParam(s, `${p}.ticks`, "ticks", "cooldownTicks", a.ticks ?? ref?.cooldownTicks ?? 0, `cooldown set on ${a.ability ?? ab.id} (ticks)`, "cooldown"); break;
143	      }
144	      case "consume_charge": addParam(s, `${p}.amount`, "int", "chargeCost", a.amount ?? DEFAULTS.chargeCost, "charges spent", "count"); break;
145	      case "query_marked": addParam(s, `${p}.radius`, "num", "queryMarkedRadius", a.radius, `marked "${a.mark}" search radius`, "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
146	      case "query_nearby": addParam(s, `${p}.radius`, "num", "queryNearbyRadius", a.radius, "nearby search radius", "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
147	      case "delayed": addParam(s, `${p}.delay_ticks`, "ticks", "delayTicks", a.delayTicks, "delay (ticks)", "duration"); break;
148	      case "branch": a.if.forEach((c, i) => cond(c, `${p}.if${i}`)); break;
149	      default: break;
150	    }
151	  });
152	  return s.params;
153	}
