169	class Out {
170	  lines: string[] = [];
171	  push(ind: number, s: string) { this.lines.push("    ".repeat(ind) + s); }
172	}
173	export const JTYPE: Record<ParamKind, string> = { num: "double", ticks: "long", int: "int", text: "String", sound: "String" };
174	export function loadLine(p: Param, rel: string): string {
175	  switch (p.kind) {
176	    case "num": return `${p.field} = c.num(B + ${jstr(rel)}, ${jnum(p.min)}, ${jnum(p.max)});`;
177	    case "ticks": return `${p.field} = c.ticks(B + ${jstr(rel)}, ${p.min}L, ${p.max}L);`;
178	    case "int": return `${p.field} = c.integer(B + ${jstr(rel)}, ${p.min}, ${p.max});`;
179	    case "text": return `${p.field} = c.text(B + ${jstr(rel)}, ${p.max});`;
180	    case "sound": return `${p.field} = c.soundKey(B + ${jstr(rel)});`;
181	  }
182	}
183	
184	type AbGen = { item: ItemDesign; ab: Ability; params: Map<string, Param>; statics: string[]; ns: string; loopN: number };
185	const P = (g: AbGen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
186	
187	function condExpr(g: AbGen, c: Condition, rel: string, A: string): string {
188	  const neg = (e: string) => (c.negate ? `!(${e})` : e);
189	  const own = (ref?: string) => !ref || ref === g.ab.id;
190	  const other = (ref: string) => `d.ability(${jstr(g.item.id)}, ${jstr(ref)})`;
191	  switch (c.type) {
192	    case "cooldown_ready": return neg(own(c.ability) ? `cooldownReady(${A}.player())` : `(${other(c.ability!)} == null || ${other(c.ability!)}.cooldownReady(${A}.player()))`);
193	    case "has_permission": return neg(`${A}.player().hasPermission(${jstr(`${g.ns}.${c.node}`)})`);
194	    case "target_is": {
195	      const set = c.types?.length ? `T_${rel.replace(/\./g, "_")}` : "null";
196	      if (c.types?.length) g.statics.push(`private static final Set<String> ${set} = Set.of(${c.types.map((t) => jstr(bare(t))).join(", ")});`);
197	      const e = `Checks.targetIs(${A}.target(), ${maskOf(c.kinds)}, ${set})`;
198	      return c.negate ? `(${A}.target() != null && ${A}.target().isValid() && !${e})` : e;
199	    }
200	    case "world_in": {
201	      const set = `W_${rel.replace(/\./g, "_")}`;
202	      g.statics.push(`private static final Set<String> ${set} = Set.of(${c.worlds.map(jstr).join(", ")});`);
203	      return neg(`${set}.contains(${A}.player().getWorld().getName())`);
204	    }
205	    case "health_below": case "health_above":
206	      return `Checks.health(${c.subject === "self" ? `${A}.player()` : `${A}.livingTarget()`}, ${P(g, `${rel}.fraction`)}, ${c.type === "health_below"}, ${!!c.negate})`;
207	    case "item_identity": return neg(`d.identity().is(${A}.player().getInventory().${c.slot === "main_hand" ? "getItemInMainHand" : "getItemInOffHand"}(), ${jstr(c.item)})`);
