558	export function yamlTree(params: Param[]): string[] {
559	  type Node = { children: Map<string, Node>; param?: Param };
560	  const root: Node = { children: new Map() };
561	  for (const p of params) {
562	    let n = root;
563	    for (const seg of p.path.split(".")) { if (!n.children.has(seg)) n.children.set(seg, { children: new Map() }); n = n.children.get(seg)!; }
564	    n.param = p;
565	  }
566	  const out: string[] = [];
567	  const walk = (n: Node, ind: number) => {
568	    for (const [k, c] of n.children) {
569	      const pad = "  ".repeat(ind);
570	      if (c.param) {
571	        const p = c.param;
572	        const range = p.kind === "text" ? `text, max ${p.max} characters` : p.kind === "sound" ? "namespaced sound key" : `${fmtNum(p.min, p.kind)} to ${fmtNum(p.max, p.kind)}`;
573	        out.push(`${pad}# ${p.label} (${range})`);
574	        out.push(`${pad}${k}: ${p.kind === "text" || p.kind === "sound" ? ystr(String(p.value)) : fmtNum(Number(p.value), p.kind)}`);
575	      } else { out.push(`${pad}${k}:`); walk(c, ind + 1); }
576	    }
577	  };
578	  walk(root, 0);
579	  return out;
580	}
