582	/** Hash of the designer values (the defaults Cyrus manages): config_version moves when it changes. */
583	export const designerValuesHash = (params: Param[]) => sha256(params.map((p) => `${p.path}=${p.kind === "text" || p.kind === "sound" ? String(p.value) : fmtNum(Number(p.value), p.kind)}`).join("\n")).slice(0, 16);
