585	export function nextConfigVersion(previous: string | undefined, valuesHash: string): number {
586	  if (!previous) return 1;
587	  const v = /^config_version:\s*(\d+)\s*$/m.exec(previous);
588	  const h = /^# designer-values: ([0-9a-f]{16})\s*$/m.exec(previous);
589	  const prev = v ? Math.max(1, Math.min(1_000_000, Number(v[1]))) : 1;
590	  return h && h[1] === valuesHash ? prev : prev + 1;
591	}
