652	    if (d.lore?.length) lines.push(``, ...d.lore.map((l) => `> ${l.text}`));
653	    if (d.stats?.damage !== undefined) lines.push(``, `Attack damage ${d.stats.damage}, attack speed ${d.stats.attackSpeed}.`);
654	    if (d.stats?.durability !== undefined && !d.stats.unbreakable) lines.push(`Durability ${d.stats.durability}.`);
