667	      lines.push(``, r.kind === "shaped" ? `Recipe (crafting table): ${r.pattern.map((row) => `\`${row.replace(/ /g, "·")}\``).join(" / ")} with ${Object.keys(r.key).sort().map((k) => `${k} = ${show(r.key[k])}`).join(", ")}.` : `Recipe (shapeless): ${r.ingredients.map(show).join(" + ")}.`);
668	    }
