674	  for (const p of params) lines.push(`- \`${p.path}\` = ${p.kind === "text" || p.kind === "sound" ? `"${p.value}"` : fmtNum(Number(p.value), p.kind)}: ${p.label}${p.kind === "text" || p.kind === "sound" ? "" : ` (${fmtNum(p.min, p.kind)}-${fmtNum(p.max, p.kind)})`}`);
