683	export function compileDesigns(inputs: unknown[], ctx: CompileContext): CompileResult {
684	  const warnings: DzIssue[] = [];
685	  if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(ctx.pluginName)) return { ok: false, errors: [{ path: "pluginName", code: "bad_name", message: "the plugin name must be 2-40 letters, digits or _ starting with a letter" }], warnings };
686	  if (!inputs.length) return { ok: false, errors: [{ path: "(mod)", code: "no_designs", message: "no design items" }], warnings };
687	  const v = validateDesigns(inputs, { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets, ...(ctx.limits ? { limits: { maxItems: ctx.limits.maxItems } } : {}) });
688	  const errors: DzIssue[] = [...v.errors];
689	  v.results.forEach((r, i) => {
690	    const id = (inputs[i] as { id?: string })?.id ?? `#${i}`;
691	    for (const e of r.errors) errors.push({ ...e, path: `${id}: ${e.path}` });
692	    for (const w of r.warnings) warnings.push({ ...w, path: `${id}: ${w.path}` });
693	  });
694	  if (!v.ok || errors.length) return { ok: false, errors, warnings };
695	  const designs = v.results.map((r) => (r as Extract<typeof r, { ok: true }>).design).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
696	  const fe = (v.results[0] as Extract<(typeof v.results)[number], { ok: true }>).features;
697	  const lower = ctx.pluginName.toLowerCase().replace(/_/g, "");
698	  const pkg = `dev.nxeon.plugins.${/^[a-z]/.test(lower) ? lower : `p${lower}`}`;
699	  const main = camel(ctx.pluginName.replace(/^[a-z]/, (c) => c.toUpperCase())) || "DesignerMod";
700	  const mainCls = /^[A-Z]/.test(main) ? main : `M${main}`;
701	  const command = ctx.pluginName.toLowerCase().slice(0, 32);
702	  // a vanilla command root would be shadowed (or shadow vanilla): refuse (the exact version's command tree)
703	  if (vanillaIds("command", ctx.version).has(command)) return { ok: false, errors: [{ path: "pluginName", code: "command_clash", message: `/${command} is a vanilla command in Minecraft ${ctx.version}; pick another plugin name` }], warnings };
704	  const classes = new Map<string, string>();
705	  const claim = (cls: string, what: string): string | null => { if (classes.has(cls)) return classes.get(cls)!; classes.set(cls, what); return null; };
706	  const files: CompiledFile[] = [];
707	  const dir = `src/main/java/${pkg.replace(/\./g, "/")}`;
708	  const add = (path: string, content: string, role: CompiledFile["role"]) => files.push({ path, content, sha256: sha256(content), role });
709	  for (const c of COMPONENTS) add(`${dir}/${c.file}`, renderComponent(c.source, pkg), "component");
710	  add(`${dir}/${COMPAT_META.file}`, renderComponent(compatSource(fe), pkg), "compat");
711	  const itemClasses: string[] = [];
712	  const params: Param[] = [];
713	  const modelsApplied: string[] = [];
714	  for (const d of designs) {
715	    const icls = `${camel(d.id)}Item`;
716	    const clash = claim(icls, d.id);
717	    if (clash) return { ok: false, errors: [{ path: d.id, code: "class_clash", message: `items ${clash} and ${d.id} map to the same Java class ${icls}; rename one` }], warnings };
718	    const abCls: string[] = [];
719	    for (const ab of d.abilities) {
720	      const acls = `${camel(d.id)}${camel(ab.id)}`;
721	      const c2 = claim(acls, `${d.id}.${ab.id}`);
722	      if (c2) return { ok: false, errors: [{ path: `${d.id}.${ab.id}`, code: "class_clash", message: `${c2} and ${d.id}.${ab.id} map to the same Java class ${acls}; rename one` }], warnings };
723	      const g = abilityClass(pkg, d, ab, acls, ctx.namespace);
724	      add(`${dir}/abilities/${acls}.java`, g.source, "generated");
725	      abCls.push(acls);
726	      params.push(...g.params);
727	    }
728	    const modelOk = !!d.assets?.model && (!ctx.assets?.models || ctx.assets.models.includes(d.assets.model));
729	    if (modelOk) modelsApplied.push(d.assets!.model!);
730	    const it = itemClass(pkg, d, icls, abCls, ctx.namespace, fe, modelOk, designs.some((x) => x.abilities.length > 0));
731	    add(`${dir}/items/${icls}.java`, it.source, "generated");
732	    itemClasses.push(icls);
733	    params.push(...it.params);
734	  }
735	  // config order = designParams order (item params first, then abilities), independent of the class emission order
736	  const ordered = designParams(designs);
737	  const ms = modelStatesOf(designs, fe, ctx);
738	  if (ms) add(`${dir}/designer/ModelStates.java`, renderComponent(MODEL_STATES_JAVA, pkg), "component");
739	  add(`${dir}/${mainCls}.java`, mainClass(pkg, mainCls, ctx.namespace, command, itemClasses, designs.map((d) => d.id), !!ctx.customHooks, ms), "generated");
740	  const notes: string[] = [];
741	  for (const d of designs) if (d.assets?.model && fe.itemModel && !modelsApplied.includes(d.assets.model)) notes.push(`${d.name.text} keeps the ${bare(d.base).replace(/_/g, " ")} look: this mod has no custom model "${d.assets.model}".`);
742	  if (!fe.itemModel && designs.some((d) => d.assets?.model)) notes.push(`Custom item models need Minecraft 1.21.4 or newer: on ${fe.version} the items keep their base look.`);
743	  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "charge_release")) notes.push(`${d.name.text}: charge by holding sneak with it in your main hand, then ${d.abilities.find((a) => a.trigger.type === "charge_release" && a.trigger.release === "unsneak") ? "let go of sneak" : "right-click while still sneaking"}.`);
744	  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "item_consume") && !(CONSUMABLE_BASES as readonly string[]).includes(bare(d.base))) notes.push(`${d.name.text} must be eaten to work.`);
745	  notes.push(...stateNotes(designs, fe));
746	  notes.push("Gameplay effects run on the server: protection plugins and PvP settings can block damage and teleports.");
747	  const valuesHash = designerValuesHash(ordered);
748	  const configVersion = ctx.configVersion !== undefined ? Math.max(1, Math.min(1_000_000, Math.round(ctx.configVersion))) : nextConfigVersion(ctx.previousConfig, valuesHash);
749	  const seed = randomSeedFor(ctx.namespace);
750	  add(`src/main/resources/config.yml`, configYml(ctx.pluginName, command, ordered, configVersion, valuesHash, seed), "resource");
751	  add(`src/main/resources/plugin.yml`, pluginYml(ctx.pluginName, `${pkg}.${mainCls}`, ctx.pluginVersion ?? "1.0.0", ctx.version, (ctx.description ?? `Custom items: ${designs.map((d) => d.name.text).join(", ")}`).slice(0, 200), command, ctx.namespace, designs), "resource");
752	  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
753	  const rd = readme(ctx.pluginName, command, ctx.namespace, designs, ordered, fe, notes);
754	  const hash = sha256(files.map((f) => `${f.path}\n${f.sha256}`).join("\n") + `\nREADME\n${sha256(rd)}`);
755	  return {
756	    ok: true, files, readme: rd, readmeSha256: sha256(rd), hash, params: ordered, warnings, notes, pkg, modelsApplied, mainClass: `${pkg}.${mainCls}`, command, configVersion, designerValuesHash: valuesHash,
757	    features: fe, javacVerified: (JAVAC_VERIFIED_VERSIONS as readonly string[]).includes(ctx.version), compiler: COMPILER_VERSION, library: COMPONENT_LIBRARY_VERSION, libraryHash: libraryHash(), designs,
758	  };
759	}
