762	const DURING_JAVA: Record<string, string> = { cooldown: "COOLDOWN", no_charges: "NO_CHARGES", charging: "CHARGING" };
763	const duringText = (d: string) => (d === "cooldown" ? "cools down" : d === "no_charges" ? "has no charges" : "is charging");
764	/** The ModelStates wiring of a mod, or null when no design has states (or the version has no item models). */
765	export function modelStatesOf(designs: ItemDesign[], fe: DesignFeatures, ctx: Pick<CompileContext, "assets">): MainStates | null {
766	  if (!fe.itemModel) return null;
767	  const rules: string[] = [], flagCounts: [string, number][] = [], aims: string[] = [];
768	  for (const d of designs) {
769	    const st = d.states;
770	    if (!st) continue;
771	    const im = d.assets?.model ? ctx.assets?.itemModels?.[d.assets.model] : undefined;
772	    for (const m of st.modes ?? []) rules.push(`new ModelStates.Rule(${jstr(d.id)}, ${jstr(m.ability)}, ModelStates.During.${DURING_JAVA[m.during]}, ${jstr(m.value)}, -1)`);
773	    let n = im ? im.flags.length : 0;
774	    (st.flags ?? []).forEach((f, i) => { const k = im ? im.flags.indexOf(f.name) : i; if (k < 0) return; n = Math.max(n, k + 1); rules.push(`new ModelStates.Rule(${jstr(d.id)}, ${jstr(f.ability)}, ModelStates.During.${DURING_JAVA[f.during]}, null, ${k})`); });
775	    if (st.modes?.length || st.flags?.length) flagCounts.push([d.id, n]);
776	    if (st.aim) aims.push(d.id);
777	  }
778	  return rules.length || aims.length ? { rules, flagCounts, aims } : null;
779	}
