import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.entity.Projectile;
import org.bukkit.entity.SmallFireball;
import org.bukkit.entity.Snowball;
import org.bukkit.entity.WindCharge;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.util.RayTraceResult;
import org.bukkit.util.Vector;

/**
 * Component designer-effects v1: every action of the ability graph. Each one checks the activation budget, skips a
 * missing / dead / unloaded subject, and clamps velocities. Damage goes through Bukkit's damage events with the player
 * as the source, so PvP settings and protection plugins can cancel it; teleports fire PlayerTeleportEvent.
 */
public final class Effects {
    private static final double MAX_SPEED = 4.0;
    private static final Set<Material> UNSAFE = EnumSet.of(Material.FIRE, Material.SOUL_FIRE, Material.LAVA, Material.POWDER_SNOW, Material.SWEET_BERRY_BUSH, Material.WITHER_ROSE, Material.COBWEB, Material.NETHER_PORTAL, Material.END_PORTAL, Material.END_GATEWAY, Material.CACTUS, Material.MAGMA_BLOCK, Material.CAMPFIRE, Material.SOUL_CAMPFIRE);
    private final Designer d;

    Effects(Designer d) { this.d = d; }

    private static boolean alive(LivingEntity t) { return t != null && t.isValid() && !t.isDead(); }

    public Location self(Activation a) { return a.player().getLocation().add(0, 1.0, 0); }
    public Location target(Activation a) { Entity t = a.target(); return t == null || !t.isValid() ? null : t.getLocation().add(0, t.getHeight() / 2.0, 0); }
    public Location point(Activation a) { return a.point(); }

    public void damage(Activation a, LivingEntity t, double amount) {
        if (!alive(t) || amount <= 0 || !a.budget().entity()) return;
        if (t == a.player()) t.damage(amount); else t.damage(amount, a.player());
    }

    public void heal(Activation a, LivingEntity t, double amount) {
        if (!alive(t) || amount <= 0 || !a.budget().entity()) return;
        AttributeInstance max = t.getAttribute(Compat.MAX_HEALTH);
        t.setHealth(Math.min(max == null ? 20.0 : max.getValue(), t.getHealth() + amount));
    }

    public void potion(Activation a, LivingEntity t, PotionEffectType type, int ticks, int amplifier) {
        if (!alive(t) || type == null || !a.budget().entity()) return;
        t.addPotionEffect(new PotionEffect(type, ticks, amplifier));
    }

    private void push(Activation a, LivingEntity t, Vector dir, double strength, double vertical) {
        if (!alive(t) || !a.budget().entity()) return;
        Vector h = dir.clone().setY(0);
        Vector v = h.lengthSquared() < 1.0E-4 ? new Vector(0, 0, 0) : h.normalize().multiply(strength);
        v.setY(vertical);
        if (v.length() > MAX_SPEED) v.normalize().multiply(MAX_SPEED);
        t.setVelocity(v);
    }

    /** Away from the player. */
    public void knockback(Activation a, LivingEntity t, double strength, double vertical) {
        if (t == null || t == a.player()) return;
        push(a, t, t.getLocation().toVector().subtract(a.player().getLocation().toVector()), strength, vertical);
    }

    /** Toward a location (no effect closer than one block). */
    public void pullTo(Activation a, LivingEntity t, Location to, double strength, double vertical) {
        if (t == null || to == null || to.getWorld() == null || !to.getWorld().equals(t.getWorld())) return;
        Vector dir = to.toVector().subtract(t.getLocation().toVector());
        if (dir.length() < 1.0) return;
        push(a, t, dir, strength, vertical);
    }

    /** Away from a location. */
    public void pushFrom(Activation a, LivingEntity t, Location from, double strength, double vertical) {
        if (t == null || from == null || from.getWorld() == null || !from.getWorld().equals(t.getWorld())) return;
        push(a, t, t.getLocation().toVector().subtract(from.toVector()), strength, vertical);
    }

    /** The player only: the farthest SAFE spot along the look direction within range (feet + head free, solid ground, loaded chunk, no fire/lava/portals). */
    public boolean teleportShort(Activation a, double range) {
        Player p = a.player();
        Location eye = p.getEyeLocation();
        Vector dir = eye.getDirection().normalize();
        RayTraceResult hit = p.getWorld().rayTraceBlocks(eye, dir, range, FluidCollisionMode.ALWAYS, true);
        double max = hit == null ? range : Math.max(0, hit.getHitPosition().distance(eye.toVector()) - 0.7);
        Location feet = p.getLocation();
        for (double dist = max; dist >= 1.0; dist -= 0.5) {
            Location safe = safeAt(feet.clone().add(dir.clone().multiply(dist)));
            if (safe != null) { safe.setYaw(feet.getYaw()); safe.setPitch(feet.getPitch()); return p.teleport(safe); }
        }
        return false;
    }

    static Location safeAt(Location l) {
        World w = l.getWorld();
        if (w == null) return null;
        int x = l.getBlockX();
        int z = l.getBlockZ();
        if (!w.isChunkLoaded(x >> 4, z >> 4)) return null;
        for (int dy : new int[] {0, 1, -1}) {
            int y = l.getBlockY() + dy;
            if (y - 1 < w.getMinHeight() || y + 1 >= w.getMaxHeight()) continue;
            Block feet = w.getBlockAt(x, y, z);
            Block head = w.getBlockAt(x, y + 1, z);
            Block ground = w.getBlockAt(x, y - 1, z);
            if (feet.isPassable() && !feet.isLiquid() && !UNSAFE.contains(feet.getType()) && head.isPassable() && !head.isLiquid() && !UNSAFE.contains(head.getType())
                && ground.getType().isSolid() && !UNSAFE.contains(ground.getType())) return new Location(w, x + 0.5, y, z + 0.5);
        }
        return null;
    }

    /** One projectile along the look direction, tagged with item|tag for projectile_hit, removed after lifetime ticks. */
    public void launch(Activation a, String kind, double speed, String tag, long lifetime) {
        if (!a.budget().projectile()) return;
        Player p = a.player();
        Vector vel = p.getEyeLocation().getDirection().normalize().multiply(speed);
        Projectile pr;
        if ("arrow".equals(kind)) { Arrow ar = p.launchProjectile(Arrow.class, vel); ar.setPickupStatus(AbstractArrow.PickupStatus.DISALLOWED); pr = ar; }
        else if ("small_fireball".equals(kind)) { SmallFireball f = p.launchProjectile(SmallFireball.class, vel); f.setIsIncendiary(false); f.setYield(0f); pr = f; }
        else if ("wind_charge".equals(kind)) pr = p.launchProjectile(WindCharge.class, vel);
        else pr = p.launchProjectile(Snowball.class, vel);
        pr.getPersistentDataContainer().set(d.projectileKey(), PersistentDataType.STRING, a.ability().itemId() + "|" + (tag == null ? "" : tag));
        final Projectile launched = pr;
        if (a.budget().task()) d.tasks().later(lifetime, () -> { if (launched.isValid()) launched.remove(); });
    }

    public void particles(Activation a, Location at, Particle type, int count, double spread, double speed) {
        if (at == null || at.getWorld() == null) return;
        int n = a.budget().particles(count);
        if (n > 0) at.getWorld().spawnParticle(type, at, n, spread, spread, spread, speed);
    }

    /** Namespaced key only (a custom sound from this mod's pack or a vanilla key). */
    public void sound(Activation a, Location at, String key, float volume, float pitch) {
        if (at == null || at.getWorld() == null || key == null || key.isEmpty()) return;
        at.getWorld().playSound(at, key, SoundCategory.PLAYERS, volume, pitch);
    }

    private static String fill(Activation a, String s) {
        Entity t = a.target();
        return s.replace("{player}", a.player().getName()).replace("{target}", t == null ? "" : t.getName());
    }

    public void message(Activation a, Entity to, String text, TextColor color) {
        if (to instanceof Player pl && pl.isOnline()) pl.sendMessage(Component.text(fill(a, text), color));
    }

    public void actionbar(Activation a, Entity to, String text, TextColor color) {
        if (to instanceof Player pl && pl.isOnline()) pl.sendActionBar(Component.text(fill(a, text), color));
    }

    public void title(Activation a, Entity to, String title, String subtitle, TextColor color, long in, long stay, long out) {
        if (!(to instanceof Player pl) || !pl.isOnline()) return;
        pl.showTitle(Title.title(Component.text(fill(a, title), color), Component.text(subtitle == null ? "" : fill(a, subtitle)),
            Title.Times.times(Duration.ofMillis(in * 50L), Duration.ofMillis(stay * 50L), Duration.ofMillis(out * 50L))));
    }

    public void give(Activation a, ItemStack stack, int count) {
        if (stack == null) return;
        Player p = a.player();
        for (int i = 0; i < count; i++) {
            for (ItemStack left : p.getInventory().addItem(stack.clone()).values()) p.getWorld().dropItemNaturally(p.getLocation(), left);
        }
    }
}
`;

