  featuresPerBiome: 24,
  spawnsPerBiome: 16,
  /** structure template: each side <= 48 blocks (max volume 48 x 48 x 48), non-void blocks <= 32768, palette <= 32 */
  templateSide: 48, templateBlocks: 32768, paletteSize: 32, lootBlocksPerTemplate: 16,
  /** feature placement attempts per chunk (count x patch tries) per placed feature / per biome */
