  z.strictObject({ kind: z.literal("count"), count: z.union([Int(1, 64), z.strictObject({ min: Int(0, 64), max: Int(1, 64) })]) }),
  /** Only in 1 of `chance` chunks. */
  z.strictObject({ kind: z.literal("rarity"), chance: Int(1, 1024) }),
  /** Random x/z inside the chunk. */
  z.strictObject({ kind: z.literal("in_square") }),
  /** Only where the biome at the position lists this feature (vanilla puts it last). */
  z.strictObject({ kind: z.literal("biome") }),
  z.strictObject({ kind: z.literal("heightmap"), heightmap: z.enum(HEIGHTMAPS) }),
  z.strictObject({ kind: z.literal("height_range"), shape: z.enum(["uniform", "trapezoid"]), min: Anchor, max: Anchor }),
  z.strictObject({ kind: z.literal("surface_water_depth"), maxDepth: Int(0, 8) }),
  /** Only where this block would survive (trees: their sapling). */
  z.strictObject({ kind: z.literal("would_survive"), block: StateOrId }),
]);
