// Cyrus Test Flight (R0) types: the typed spec a caller writes, the resolved spec the node-2 runner receives,
// and the report it returns. The runner is services/modbuilder/tools/testflight/runner.js (plain Node on node-2).
// A check passes only if it actually ran; a skipped required check means the flight is NOT a success.
import type { PlaytestPlan } from "../playtest/plan";
import type { StressSpec } from "./stress";

export const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "playtest", "stress", "clean_stop", "no_leaks"] as const;
export type CheckId = (typeof CHECK_IDS)[number];
export type CheckStatus = "pass" | "fail" | "not_run";

/** A regex matched against each log line (JS syntax; flags limited to i/m/s/u). */
export type LogMatcher = { id: string; pattern: string; flags?: string };

/** A small text file in the server directory (e.g. a plugin's config). Path relative to the server root, under plugins/ only. */
export type ServerFile = { path: string; content: string };

export type SeedRef = { from: string; to: string };

export type RconCheck = {
  id?: string;
  /** Written (created or replaced) in the server dir right before this command is sent, e.g. to test a config reload. */
  writeFile?: ServerFile;
  /** Wait this long (ms, max 30000) before sending the command (after writeFile), e.g. for a file watcher. */
  waitMs?: number;
  /** One console command without the leading slash. stop/restart/op/deop/reload are reserved for the runner. */
  command: string;
  /** Every substring must appear in the reply (colour codes stripped). Empty = the command only has to answer. */
  expect?: string[];
  /** None of these may appear. */
  expectNot?: string[];
  /** Default true. An optional check is reported but does not fail the stage. */
  required?: boolean;
};

/** An artifact either on the caller's disk (uploaded by the invoker) or already on node-2 under the Test Flight root. */
export type ArtifactRef = { localPath: string; remotePath?: never; sha256?: string } | { remotePath: string; localPath?: never; sha256?: string };

export type TestFlightSpec = {
  /** Exact registry id, e.g. "26.2" or "1.21.11". The registry supplies the JDK and the pinned Paper server jar. */
  version: string;
  plugins?: ArtifactRef[];
  /** Datapacks go into world/datapacks before first boot; each one adds an automatic `datapack list enabled` check. */
  datapacks?: (ArtifactRef & { name: string })[];
  /** Written to server.properties only. No client connects, so the pack itself is NOT exercised (reported as such). */
  resourcePack?: { url: string; sha1?: string; id?: string; required?: boolean };
  /** Small text files placed before the first boot (max 16, 64 KB each, under plugins/). */
  files?: ServerFile[];
  /**
   * Read-only directories prepared on node-2 under `<root>/seeds/<from>` copied into the server dir before boot
   * (`to` = "libraries" or a path under plugins/). The flight has no internet, so a managed plugin's pinned runtime
   * libraries are seeded this way (runner tf-lite-2).
   */
  seeds?: SeedRef[];
  /** Server-dir files copied out after the stop to `<root>/collect/<runId>/` (a path ending in "/" = a listing). */
  collect?: string[];
  rcon?: RconCheck[];
  /** Replace the runner's default startup-log matchers (omit to use the defaults). */
  logMatchers?: LogMatcher[];
  /** Extra ignore patterns, added to the runner's sandbox ignores. */
  logIgnore?: LogMatcher[];
  timeouts?: { bootSec?: number; rconSec?: number; stopSec?: number; totalSec?: number };
  /** xmxMb max 1024 (node-2 rule). rssCapMb is a watchdog: above it the server is killed and the run fails. */
  memory?: { xmxMb?: number; rssCapMb?: number };
  /** Extra stages to treat as required even if the spec would not make them required. */
  requireStages?: CheckId[];
  /** Keep the server dir on node-2 for debugging (default false). */
  keepDir?: boolean;
  /** World options (runner tf-lite-3): generateStructures turns structure generation on (default off: a tiny flat world). */
  world?: { generateStructures?: boolean };
  /** Playtest (runner tf-lite-4): a scripted Mineflayer player runs these scenarios after the RCON checks. Makes `playtest` required. */
  playtest?: PlaytestPlan;
  /** Stress (runner tf-lite-5, perf safety): scripted load after the boot checks while the real TPS is sampled. Makes `stress` required. */
  stress?: StressSpec;
};

/** What the runner receives: registry pins resolved, artifact paths on node-2. */
export type ResolvedSpec = {
  schema: 1;
  runId: string;
  version: string;
  javaRelease: 21 | 25;
  paper: { build: number; sha256: string };
  plugins: { path: string; sha256?: string }[];
  datapacks: { path: string; name: string }[];
  resourcePack?: TestFlightSpec["resourcePack"];
  files?: ServerFile[];
  seeds?: SeedRef[];
  collect?: string[];
  rcon: RconCheck[];
  logMatchers?: LogMatcher[];
  logIgnore?: LogMatcher[];
  timeouts: { bootSec: number; rconSec: number; stopSec: number; totalSec: number };
  memory: { xmxMb: number; rssCapMb: number };
  keepDir: boolean;
  world?: { generateStructures?: boolean };
  playtest?: PlaytestPlan;
  stress?: StressSpec;
};

export type CheckResult = { id: CheckId; status: CheckStatus; required: boolean; evidence: string[]; durationMs: number };

export type ReportArtifact =
  | { kind: "plugin"; file: string; sha256: string; pluginName: string | null; apiVersion: string | null; descriptor: string | null }
  | { kind: "datapack"; name: string; sha256: string | null; directory: boolean }
  | { kind: "resourcePack"; url: string; sha1: string | null; exercised: false }
  | { kind: "seed"; from: string; to: string; files: number; bytes: number; sha256: string };

/** A collected server file (runner tf-lite-2) or a directory listing. */
export type CollectedItem = { path: string; kind?: "file" | "listing"; bytes?: number; sha256?: string; dest?: string; entries?: number; listing?: string[]; error?: string };

export type EngineMeta = {
  runner: string;
  runnerSha256: string;
  node: string;
  host: string;
  kernel: string;
  jdk: { release: number; version: string | null; dist: string; sha256: string };
  paper: { version: string; build: number; sha256: string; channel: string | null };
  isolation: { netns: string; uid: number; noNewPrivs: boolean; nice: number; activeProcessorCount: number };
  /** Runner tf-lite-4, flights with a playtest: the pinned bot lockfile and the versions it was verified on. */
  bot?: { lockSha256: string; versions: string[] };
};

/** Raw runner output. `status` says whether the runner itself completed; `overall` is its own verdict (recomputed by summarize). */
export type TestFlightReport = {
  schema: 1;
  runId: string | null;
  status: "completed" | "busy" | "error";
  version: string | null;
  javaRelease: number | null;
  startedAt: string;
  finishedAt: string | null;
  checks: CheckResult[];
  timings: Record<string, number>;
  bootMs: number | null;
  doneReportedSec: number | null;
  peakRssKb: number | null;
  artifacts: ReportArtifact[];
  engine: EngineMeta | null;
  notes: string[];
  overall: "passed" | "failed" | "incomplete";
  collected?: CollectedItem[];
  /** Runner tf-lite-4: the playtest bot's result (lib/cyrus/playtest/verdict.ts PlaytestRunResult). */
  playtest?: unknown;
  /** Runner tf-lite-5: the stress phase's samples + verdict (./stress.ts StressResult). */
  stress?: unknown;
};

export type Overall = "passed" | "failed" | "incomplete" | "busy" | "error";

export type TestFlightSummary = {
  version: string;
  overall: Overall;
  /** true only when overall === "passed". */
  success: boolean;
  passed: CheckId[];
  failed: CheckId[];
  /** Required checks that did not run (or "passed" without evidence): any entry here blocks success. */
  skippedRequired: CheckId[];
  notRunOptional: CheckId[];
  reasons: string[];
  bootMs: number | null;
  peakRssKb: number | null;
  runId: string | null;
};

export type MatrixSummary = { overall: Overall; success: boolean; versions: TestFlightSummary[] };
// Test Flight spec validation + resolution against the version registry. Pure (no I/O): fails closed on anything
// the registry cannot vouch for (unknown version, no pinned Paper server jar).
import { getVersion, type VersionRow } from "../versions/registry";
import type { CheckId, ResolvedSpec, TestFlightSpec, LogMatcher, ServerFile } from "./types";
import { CHECK_IDS } from "./types";
import { cyrusConfig } from "../config";
import { validatePlaytestPlan, playtestVersion } from "../playtest/plan";
import { validateStress } from "./stress";

export const TF_DEFAULT_ROOT = cyrusConfig().testFlightRoot;
export const DEFAULT_TIMEOUTS = { bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 } as const;
export const DEFAULT_MEMORY = { xmxMb: 1024, rssCapMb: 1800 } as const;
const RESERVED_COMMANDS = /^\/?(stop|restart|op|deop|reload)\b/i;
const SHA256 = /^[0-9a-f]{64}$/;
/** Same rule as lib.js SERVER_FILE_RE: relative, under plugins/, plain segments only. */
export const SERVER_FILE_RE = /^plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}){0,3}$/;
export const MAX_SERVER_FILES = 16;
export const MAX_SERVER_FILE_BYTES = 64 * 1024;
/** Same rules as lib.js (runner tf-lite-2). */
export const SEED_NAME_RE = /^[a-z0-9][a-z0-9._-]{0,63}$/;
export const SEED_TO_RE = /^(libraries|plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,4})$/;
export const COLLECT_RE = /^[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/(?!\.\.?(\/|$))[A-Za-z0-9_.-]{1,64}){0,7}\/?$/;
export const MAX_SEEDS = 8;
export const MAX_COLLECT = 12;

function checkFile(f: ServerFile | undefined, key: string, errs: string[]) {
  if (!f || typeof f.path !== "string" || !SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) errs.push(`${key}.path must be a relative path under plugins/ (plain segments)`);
  if (!f || typeof f.content !== "string" || Buffer.byteLength(f.content, "utf8") > MAX_SERVER_FILE_BYTES) errs.push(`${key}.content must be text of at most ${MAX_SERVER_FILE_BYTES} bytes`);
}

function checkMatchers(list: LogMatcher[] | undefined, key: string, errs: string[]) {
  for (const [i, m] of (list ?? []).entries()) {
    if (!m || typeof m.pattern !== "string" || !m.pattern) { errs.push(`${key}[${i}]: pattern is required`); continue; }
    if (m.pattern.length > 400) errs.push(`${key}[${i}]: pattern longer than 400 chars`);
    try { new RegExp(m.pattern, (m.flags ?? "").replace(/[^imsu]/g, "")); } catch (e) { errs.push(`${key}[${i}]: ${(e as Error).message}`); }
  }
}

export type PinnedRow = VersionRow & { paperBuild: number; paperServerSha256: string };
export type SpecCheck = { ok: true; row: PinnedRow } | { ok: false; errors: string[] };

/** Validate a caller spec. `lookup` is injectable for tests; defaults to the real registry. */
export function validateSpec(spec: TestFlightSpec, lookup: (id: string) => VersionRow | null = getVersion): SpecCheck {
  const errs: string[] = [];
  const row = lookup(String(spec?.version ?? ""));
  if (!row) errs.push(`Minecraft ${spec?.version} is not in the version registry`);
  else {
    if (!row.paperBuild || !Number.isInteger(row.paperBuild)) errs.push(`${row.id} has no pinned Paper server build, so it cannot be test-flown`);
    if (!SHA256.test(String(row.paperServerSha256 ?? ""))) errs.push(`${row.id} has no pinned Paper server sha256`);
  }
  const arts = [...(spec.plugins ?? []).map((a, i) => ["plugins", i, a] as const), ...(spec.datapacks ?? []).map((a, i) => ["datapacks", i, a] as const)];
  for (const [k, i, a] of arts) {
    const hasLocal = typeof a?.localPath === "string" && a.localPath.length > 0;
    const hasRemote = typeof a?.remotePath === "string" && a.remotePath.length > 0;
    if (hasLocal === hasRemote) errs.push(`${k}[${i}]: give exactly one of localPath or remotePath`);
    if (a?.sha256 != null && !SHA256.test(a.sha256)) errs.push(`${k}[${i}]: sha256 must be 64 lowercase hex chars`);
    if (k === "plugins" && !/\.jar$/.test(String(a?.localPath ?? a?.remotePath ?? ""))) errs.push(`plugins[${i}]: must be a .jar`);
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) if (!/^[a-z0-9_.-]{1,64}$/.test(String(d?.name ?? ""))) errs.push(`datapacks[${i}].name must be 1-64 chars of a-z 0-9 _ . -`);
  const pluginNames = new Set<string>();
  for (const p of spec.plugins ?? []) {
    const b = String(p.localPath ?? p.remotePath ?? "").split("/").pop()!;
    if (pluginNames.has(b)) errs.push(`two plugins share the file name ${b}`);
    pluginNames.add(b);
  }
  for (const [i, c] of (spec.rcon ?? []).entries()) {
    const cmd = String(c?.command ?? "");
    if (!cmd.trim() || cmd.length > 200 || /[\r\n]/.test(cmd)) errs.push(`rcon[${i}].command must be one line of 1-200 chars`);
    if (RESERVED_COMMANDS.test(cmd.trim())) errs.push(`rcon[${i}]: '${cmd}' is reserved for the runner`);
    if (c.expect != null && !Array.isArray(c.expect)) errs.push(`rcon[${i}].expect must be an array of strings`);
    if (c.writeFile != null) checkFile(c.writeFile, `rcon[${i}].writeFile`, errs);
    if (c.waitMs != null && !(Number.isInteger(c.waitMs) && c.waitMs >= 0 && c.waitMs <= 30000)) errs.push(`rcon[${i}].waitMs must be 0-30000`);
  }
  if ((spec.files ?? []).length > MAX_SERVER_FILES) errs.push(`files: at most ${MAX_SERVER_FILES}`);
  for (const [i, f] of (spec.files ?? []).entries()) checkFile(f, `files[${i}]`, errs);
  if ((spec.seeds ?? []).length > MAX_SEEDS) errs.push(`seeds: at most ${MAX_SEEDS}`);
  for (const [i, sd] of (spec.seeds ?? []).entries()) {
    if (!SEED_NAME_RE.test(String(sd?.from ?? ""))) errs.push(`seeds[${i}].from must be a seed name under <root>/seeds`);
    if (!SEED_TO_RE.test(String(sd?.to ?? "")) || String(sd?.to).split("/").includes("..")) errs.push(`seeds[${i}].to must be libraries or a path under plugins/`);
  }
  if ((spec.collect ?? []).length > MAX_COLLECT) errs.push(`collect: at most ${MAX_COLLECT}`);
  for (const [i, c] of (spec.collect ?? []).entries()) {
    if (typeof c !== "string" || !COLLECT_RE.test(c) || c.split("/").includes("..")) errs.push(`collect[${i}] must be a relative path of plain segments`);
  }
  checkMatchers(spec.logMatchers, "logMatchers", errs);
  checkMatchers(spec.logIgnore, "logIgnore", errs);
  if (spec.logMatchers && spec.logMatchers.length === 0) errs.push("logMatchers: an empty list would make the log check vacuous; omit it to use the defaults");
  const t = spec.timeouts ?? {};
  for (const [k, max] of [["bootSec", 600], ["rconSec", 60], ["stopSec", 120], ["totalSec", 900]] as const) {
    const v = t[k];
    if (v != null && !(Number.isFinite(v) && v > 0 && v <= max)) errs.push(`timeouts.${k} must be 1-${max}`);
  }
  const m = spec.memory ?? {};
  if (m.xmxMb != null && !(Number.isInteger(m.xmxMb) && m.xmxMb >= 256 && m.xmxMb <= 1024)) errs.push("memory.xmxMb must be 256-1024 (node-2 allows at most -Xmx1g)");
  if (m.rssCapMb != null && !(Number.isInteger(m.rssCapMb) && m.rssCapMb >= 512 && m.rssCapMb <= 2048)) errs.push("memory.rssCapMb must be 512-2048");
  for (const s of spec.requireStages ?? []) if (!(CHECK_IDS as readonly string[]).includes(s)) errs.push(`requireStages: unknown stage ${s}`);
  if (spec.world != null && (Object.keys(spec.world).some((k) => k !== "generateStructures") || (spec.world.generateStructures != null && typeof spec.world.generateStructures !== "boolean"))) errs.push("world may only hold generateStructures (boolean)");
  if (spec.playtest != null) {
    errs.push(...validatePlaytestPlan(spec.playtest));
    const pv = playtestVersion(String(spec.version));
    if (!pv.ok) errs.push(pv.reason);
  }
  if (spec.stress != null) errs.push(...validateStress(spec.stress));
  if (errs.length || !row) return { ok: false, errors: errs };
  return { ok: true, row: row as PinnedRow };
}

/** Required stages for a spec. The summary uses THIS (what we asked for), not the runner's own flags. */
export function requiredStages(spec: TestFlightSpec): Set<CheckId> {
  const req = new Set<CheckId>(["boot_done", "startup_log_clean", "clean_stop", "no_leaks"]);
  if ((spec.plugins ?? []).length) req.add("plugins_enabled");
  if ((spec.rcon ?? []).length || (spec.datapacks ?? []).length) req.add("rcon_checks");
  if (spec.playtest) req.add("playtest");
  if (spec.stress) req.add("stress");
  for (const s of spec.requireStages ?? []) req.add(s);
  return req;
}

const base = (p: string) => p.split("/").pop()!;

/** Resolve a validated spec for the runner. Local artifacts are mapped to `<root>/inbox/<runId>/<file>`. */
export function resolveSpec(spec: TestFlightSpec, opts: { runId: string; root?: string; lookup?: (id: string) => VersionRow | null }): ResolvedSpec {
  const v = validateSpec(spec, opts.lookup);
  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
  if (!/^[a-z0-9][a-z0-9-]{5,63}$/.test(opts.runId)) throw new Error("runId must be 6-64 chars of a-z, 0-9, -");
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const inbox = `${root}/inbox/${opts.runId}`;
  return {
    schema: 1,
    runId: opts.runId,
    version: v.row.id,
    javaRelease: v.row.javaRelease,
    paper: { build: v.row.paperBuild, sha256: v.row.paperServerSha256 },
    plugins: (spec.plugins ?? []).map((p) => ({ path: p.remotePath ?? `${inbox}/${base(p.localPath!)}`, ...(p.sha256 ? { sha256: p.sha256 } : {}) })),
    datapacks: (spec.datapacks ?? []).map((d) => ({ name: d.name, path: d.remotePath ?? `${inbox}/dp-${d.name}` })),
    ...(spec.resourcePack ? { resourcePack: spec.resourcePack } : {}),
    ...(spec.files?.length ? { files: spec.files } : {}),
    ...(spec.seeds?.length ? { seeds: spec.seeds } : {}),
    ...(spec.collect?.length ? { collect: spec.collect } : {}),
    rcon: spec.rcon ?? [],
    ...(spec.logMatchers ? { logMatchers: spec.logMatchers } : {}),
    ...(spec.logIgnore ? { logIgnore: spec.logIgnore } : {}),
    timeouts: { ...DEFAULT_TIMEOUTS, ...(spec.timeouts ?? {}) },
    memory: { ...DEFAULT_MEMORY, ...(spec.memory ?? {}) },
    keepDir: !!spec.keepDir,
    ...(spec.playtest ? { playtest: spec.playtest } : {}),
    ...(spec.stress ? { stress: spec.stress } : {}),
    ...(spec.world ? { world: { ...(spec.world.generateStructures != null ? { generateStructures: spec.world.generateStructures } : {}) } } : {}),
  };
}
// Pure Test Flight verdicts. Rules (never relaxed):
// - a check counts as passed only if its status is "pass" AND it carries evidence (a pass with no evidence = not run);
// - required stages come from the spec we sent (requiredStages), not from the runner's own flags;
// - any required stage failed -> "failed"; any required stage missing / not_run -> "incomplete"; neither is success;
// - a busy or errored runner is never success, whatever its checks say.
import type { CheckId, CheckResult, MatrixSummary, Overall, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";
import { CHECK_IDS } from "./types";
import { requiredStages } from "./spec";

const STATUSES = new Set(["pass", "fail", "not_run"]);

/** Normalise one check: unknown status or a pass without evidence becomes not_run. */
function effective(c: CheckResult | undefined): "pass" | "fail" | "not_run" {
  if (!c || !STATUSES.has(c.status)) return "not_run";
  if (c.status === "pass" && !(Array.isArray(c.evidence) && c.evidence.some((e) => String(e).trim()))) return "not_run";
  return c.status;
}

export function summarize(spec: TestFlightSpec, report: TestFlightReport): TestFlightSummary {
  const req = requiredStages(spec);
  const byId = new Map<CheckId, CheckResult>();
  for (const c of report.checks ?? []) if ((CHECK_IDS as readonly string[]).includes(c.id) && !byId.has(c.id)) byId.set(c.id, c);
  const passed: CheckId[] = [], failed: CheckId[] = [], skippedRequired: CheckId[] = [], notRunOptional: CheckId[] = [];
  const reasons: string[] = [];
  for (const id of CHECK_IDS) {
    const c = byId.get(id);
    const st = effective(c);
    if (st === "pass") passed.push(id);
    else if (st === "fail") { failed.push(id); if (req.has(id)) reasons.push(`${id} failed${c?.evidence?.[0] ? `: ${c.evidence[0]}` : ""}`); }
    else if (req.has(id)) {
      skippedRequired.push(id);
      reasons.push(!c ? `${id} missing from the report` : c.status === "pass" ? `${id} claimed pass without evidence` : `${id} did not run`);
    } else notRunOptional.push(id);
  }
  if (report.version && spec.version && report.version !== spec.version) reasons.push(`report is for ${report.version}, spec asked for ${spec.version}`);
  let overall: Overall;
  if (report.status === "busy") { overall = "busy"; reasons.unshift("another Test Flight was running; nothing ran"); }
  else if (report.status !== "completed") { overall = "error"; reasons.unshift(`runner did not complete: ${report.notes?.slice(-1)[0] ?? "no detail"}`); }
  else if (report.version !== spec.version) overall = "error";
  else if (failed.some((id) => req.has(id))) overall = "failed";
  else if (skippedRequired.length) overall = "incomplete";
  else overall = "passed";
  return {
    version: spec.version, overall, success: overall === "passed", passed, failed, skippedRequired, notRunOptional, reasons,
    bootMs: report.bootMs ?? null, peakRssKb: report.peakRssKb ?? null, runId: report.runId ?? null,
  };
}

/** One verdict over several versions: success only if every version passed. Worst status wins. */
export function mergeSummaries(list: TestFlightSummary[]): MatrixSummary {
  const rank: Overall[] = ["error", "failed", "busy", "incomplete", "passed"];
  const overall = list.length ? rank.find((r) => list.some((s) => s.overall === r))! : "incomplete";
  return { overall, success: overall === "passed", versions: list };
}

/** Short human line per version, e.g. for a build log or a badge tooltip. Never says "passed" unless it did. */
export function describe(s: TestFlightSummary): string {
  const t = s.bootMs != null ? `, boot ${(s.bootMs / 1000).toFixed(1)}s` : "";
  const r = s.peakRssKb != null ? `, peak RSS ${Math.round(s.peakRssKb / 1024)} MB` : "";
  if (s.success) return `Test Flight passed on Paper ${s.version} (${s.passed.length} checks${t}${r})`;
  return `Test Flight ${s.overall} on Paper ${s.version}: ${s.reasons.slice(0, 3).join("; ") || "no detail"}`;
}

