        continue;
      }
      const stone = bot.inventory.items().find((i) => i.name === "stone");
      if (stone && (!bot.heldItem || bot.heldItem.name !== "stone")) await within(bot.equip(stone, "hand"), 3000);
      const [dx, dz] = offs[k++ % offs.length];
      const base = bot.entity.position.floored();
      const target = base.offset(dx, 0, dz);
      const ground = bot.blockAt(target.offset(0, -1, 0));
      const at = bot.blockAt(target);
      if (ground && at && at.name === "air" && ground.name !== "air") {
