//   4. the teleport-to-ground and mob-goal failure rules.
// Pure: no network, no server. Real flights of the same mutants: test/cyrus-mc-mutants-real.ts on node-2.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { botModeInputsFromCyrus, storedStress, stressBotModeFor, stressCoverage, stressSpecFor, testsAreCombat, validateStress, type StressResult } from "../lib/cyrus/testflight/stress";
import { flyOne, type GateDeps } from "../lib/cyrus/testflight/gate-worker";
import type { GateBuild, StoredFlight } from "../lib/cyrus/testflight/gate";
import { summarize } from "../lib/cyrus/testflight/summary";
import type { CheckResult, TestFlightReport, TestFlightSpec } from "../lib/cyrus/testflight/types";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const SL = require("../services/modbuilder/tools/testflight/stress-lib.js");

const NOW = new Date("2026-10-12T10:00:00Z");
const H = (s: string) => s.padEnd(64, "0").slice(0, 64).replace(/[^0-9a-f]/g, "a");

describe("stress bot modes (finding 1: creative players are ignored by mob AI)", () => {
  it("both validators accept build/combat and refuse anything else; the default stays build", () => {
    for (const v of [validateStress, SL.validateStress]) {
      assert.deepEqual(v({ botMode: "combat" }), []);
      assert.deepEqual(v({ botMode: "build" }), []);
      assert.match(v({ botMode: "creative" }).join(" "), /botMode must be one of build, combat/);
    }
    assert.equal(SL.resolveStress({}).botMode, "build");
    assert.equal(SL.resolveStress({ botMode: "combat" }).botMode, "combat");
  });
  it("the mode comes from the build's lanes: creature / boss -> combat, everything else -> build", () => {
    assert.equal(stressBotModeFor({ lanes: ["creature", "texture"] }).mode, "combat");
    assert.match(stressBotModeFor({ lanes: ["designBoss"] }).why, /designBoss/);
    assert.equal(stressBotModeFor({ lanes: ["texture", "designItem", "datapack"] }).mode, "build");
    assert.equal(stressBotModeFor({ bosses: true }).mode, "combat");
    assert.equal(stressBotModeFor({ combatTests: true }).mode, "combat");
    assert.equal(stressBotModeFor({}).mode, "build");
    assert.deepEqual(botModeInputsFromCyrus({ assets: { planned: { lanes: ["creature", 7] }, designer: { bosses: true } } }), { lanes: ["creature"], bosses: true });
    assert.deepEqual(botModeInputsFromCyrus(null), { lanes: [], bosses: false });
    assert.deepEqual(botModeInputsFromCyrus("x"), { lanes: [], bosses: false });
    assert.ok(testsAreCombat([{ title: "the golem attacks a nearby player" }]));
    assert.ok(!testsAreCombat([{ title: "the shop opens a menu" }]));
  });
  it("stressSpecFor only carries botMode when it is combat (build specs stay byte-identical)", () => {
    const env = {};
    assert.equal("botMode" in stressSpecFor({ version: "1.21.11", env }), false);
    assert.equal("botMode" in stressSpecFor({ version: "1.21.11", botMode: "build", env }), false);
    assert.equal(stressSpecFor({ version: "1.21.11", botMode: "combat", env }).botMode, "combat");
  });
  it("the combat setup is survival, off peaceful, with gear; never creative", () => {
    const c: string[] = SL.combatSetup("NxStress");
    assert.equal(c[0], "gamemode survival NxStress");
    assert.ok(c.includes("difficulty easy"));
    assert.ok(c.some((x) => /^give NxStress minecraft:iron_sword 1$/.test(x)));
    assert.ok(c.some((x) => /^effect give NxStress minecraft:resistance 600 2 true$/.test(x)));
    assert.ok(!c.some((x) => /creative|spectator/.test(x)));
  });
  it("waves are capped, tagged for the cleanup, and only daylight-safe hostiles", () => {
    const w: string[] = SL.combatWave({ x: 0, y: -60, z: 0 }, 0, 12);
    assert.equal(w.length, SL.COMBAT.perWave);
    for (const x of w) assert.match(x, /^summon minecraft:(husk|spider) -?\d+(\.\d)? -60 -?\d+(\.\d)? \{Tags:\["nxstress"\]\}$/);
    assert.equal(SL.combatWave({ x: 0, y: -60, z: 0 }, 3, 1).length, 1, "room left caps the wave");
    assert.equal(SL.combatWave({ x: 0, y: -60, z: 0 }, 3, 0).length, 0);
  });
  it("the bot fights the nearest foe and never a passive mob or a player", () => {
    const self = { x: 0, y: 0, z: 0 };
    const e = (id: number, name: string, x: number, type = "hostile") => ({ id, name, type, position: { x, y: 0, z: 0 } });
    assert.equal(SL.pickFoe([e(1, "pig", 1, "animal"), e(2, "husk", 5), e(3, "spider", 3), e(4, "player", 1, "player")], self).id, 3);
    assert.equal(SL.pickFoe([e(1, "pig", 1, "mob"), e(2, "armor_stand", 1, "mob")], self), null);
    assert.equal(SL.pickFoe([e(5, "husk", 40)], self), null, "out of range");
    assert.equal(SL.pickFoe([e(6, "nx_golem", 4, "mob")], self).id, 6, "a mod's own mob counts");
  });
  it("a bot only counts as having exercised the mod when it did its mode's work", () => {
    assert.ok(SL.botExercised({ joined: true, mode: "build", placed: 3 }));
    assert.ok(!SL.botExercised({ joined: true, mode: "combat", placed: 3 }));
    assert.ok(SL.botExercised({ joined: true, mode: "combat", attacks: 2 }));
    assert.ok(SL.botExercised({ joined: true, mode: "combat", hurt: 1 }));
    assert.ok(!SL.botExercised({ joined: false, mode: "combat", attacks: 2 }));
  });
  const res = (bot: StressResult["load"]["bot"], botRan: boolean, botMode?: "build" | "combat"): StressResult => ({
    schema: 1, samples: [...[20, 20, 20].map((tps, i) => ({ phase: "baseline" as const, t: i, dtMs: 2000, tps, mspt: 3, entities: 10, rssKb: 900000 })), ...Array(10).fill(0).map((_, i) => ({ phase: "load" as const, t: 10 + i, dtMs: 2000, tps: 19.9, mspt: 4, entities: 40, rssKb: 900000 }))],
    load: { summoned: 0, chunks: 0, commands: [], bot, botRan, ...(botMode ? { botMode } : {}) }, log: { cantKeepUp: 0, watchdogPaused: null, errors: [] },
  });
  it("coverage: a fight fires the combat events; a creative build bot never counts as combat", () => {
    const fought = res({ ran: true, joined: true, mode: "combat", gamemode: "survival", attacks: 9, hurt: 3, kills: 2, deaths: 0, summoned: 6 }, true, "combat");
    const c = stressCoverage(["org.bukkit.event.entity.EntityDamageByEntityEvent", "org.bukkit.event.entity.EntityTargetLivingEntityEvent", "org.bukkit.event.block.BlockPlaceEvent"], fought)!;
    assert.deepEqual(c.exercised, ["EntityDamageByEntityEvent", "EntityTargetLivingEntityEvent"]);
    assert.deepEqual(c.notExercised, ["BlockPlaceEvent"]);
    const built = res({ ran: true, joined: true, mode: "build", placed: 4, broken: 4 }, true);
    assert.deepEqual(stressCoverage(["EntityDamageByEntityEvent"], built)!.exercised, []);
    // a combat mod stressed by the creative bot: its only events were not exercised -> not_run, never a pass
    assert.equal(storedStress(built, { events: ["EntityDamageByEntityEvent"] }).verdict, "not_run");
    const st = storedStress(fought, { events: ["EntityDamageByEntityEvent"] });
    assert.equal(st.verdict, "pass");
    assert.match(st.label, /a survival player fighting/);
    assert.match(st.load.bot, /combat in survival: 9 hits, hurt 3 times, 2 kills, 0 deaths/);
    const unconfirmed = storedStress(res({ ran: true, joined: true, mode: "combat", gamemode: "unexpected reply: x", attacks: 1 }, true, "combat"));
    assert.match(unconfirmed.load.bot, /unconfirmed game mode/);
  });
  it("the gate flies a creature build with the combat bot and records why", async () => {
    const chk = (id: CheckResult["id"]): CheckResult => ({ id, status: "pass", required: true, evidence: ["ok"], durationMs: 1 });
    const report: TestFlightReport = { schema: 1, runId: "tf-x", status: "completed", version: "1.21.11", javaRelease: 21, startedAt: NOW.toISOString(), finishedAt: NOW.toISOString(), checks: (["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "stress", "clean_stop", "no_leaks"] as const).map(chk), timings: {}, bootMs: 1, doneReportedSec: 1, peakRssKb: 1, artifacts: [], engine: null, notes: [], overall: "passed", stress: res({ ran: true, joined: true, mode: "combat", gamemode: "survival", attacks: 5, hurt: 1 }, true, "combat") };
    const sent: TestFlightSpec[] = [];
    const store = new Map<string, StoredFlight>();
    const B: GateBuild & { cyrus: unknown } = { id: "b9", mcVersion: "1.21.11", pluginName: "NxGolem", jarSha256: H("jar"), result: { commands: [{ usage: "/golem" }], safety: { verdict: "pass" } }, cyrus: { assets: { planned: { lanes: ["creature", "texture"] } } } };
    const deps: GateDeps = {
      env: { CYRUS_TESTFLIGHT_GATE: "1" }, now: () => NOW,
      async candidates() { return []; },
      async artifacts() { return { jarPath: "/tmp/golem.jar", datapacks: [] }; },
      async run(spec) { sent.push(spec); return { report, summary: summarize(spec, report), resolved: {} as never, stderr: "" }; },
      async store(id, f) { store.set(id, JSON.parse(JSON.stringify(f))); },
    };
    assert.equal(await flyOne(B, null, deps, () => NOW), "ran");
    assert.equal(sent[0].stress?.botMode, "combat");
    assert.equal(store.get("b9")!.stress?.botMode?.mode, "combat");
    assert.match(store.get("b9")!.stress!.botMode!.why, /creature/);
    sent.length = 0;
    await flyOne({ ...B, id: "b10", cyrus: { assets: { planned: { lanes: ["texture"] } } } }, null, deps, () => NOW);
    assert.equal(sent[0].stress?.botMode, undefined, "block stress keeps the creative bot");
  });
});

