cd /tank/dev-worktrees/cyrus-mc-weapons && python3 - <<'EOF'
p='services/modbuilder/tools/testflight/lib.js'
s=open(p).read()
s=s.replace('''const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "playtest", "stress", "clean_stop", "no_leaks"];''','''const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "worldgen", "playtest", "stress", "clean_stop", "no_leaks"];''')
s=s.replace('''/** Same rule as lib/cyrus/testflight/summary.ts: success only if every required check ran and passed. */''','''// ---- worldgen density probes (runner tf-lite-6; TypeScript twin lib/cyrus/testflight/worldgen.ts, parity-tested) ----
// A probe counts blocks of one feature in a box of chunk columns with `execute in <dim> run fill <box> minecraft:air
// replace <block>` (the count is the "Successfully filled N block(s)" reply; "No blocks were filled" = 0). The box is
// filled in slices of at most 64 blocks high (16 x 64 x 16 = 16384, under the vanilla 32768 fill limit), the chunks are
// force-loaded first (3 x 3 around the probe so neighbour features are placed too) and unloaded after. DESTRUCTIVE in
// the throwaway Test Flight world only (the counted blocks become air); never sent to a real server.
// Reply strings verified in the en_us.json of Paper 1.21.8 / 1.21.11 / 26.2 (commands.fill.success / .failed,
// argument.pos.unloaded, commands.fill.toobig) on 2026-10-12.
const PROBE_LIMITS = Object.freeze({ probes: 8, blocks: 4, chunks: 4, chunkCoord: 64, minY: -2032, maxY: 2031, height: 384, slice: 64, waitSec: 60, count: 10000000 });
const DIM_RE = /^[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const BLOCK_RE = /^[a-z0-9_.-]+:[a-z0-9_/]+$/;
const PROBE_ID_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;
const isInt = (v, lo, hi) => Number.isInteger(v) && v >= lo && v <= hi;

function validateWorldgen(w) {
  const e = [];
  if (!w || typeof w !== "object" || Array.isArray(w)) return ["worldgen must be an object"];
  const ps = w.probes;
  if (!Array.isArray(ps) || !ps.length || ps.length > PROBE_LIMITS.probes) return [`worldgen.probes must hold 1-${PROBE_LIMITS.probes} probes`];
  const seen = new Set();
  ps.forEach((p, i) => {
    const k = `worldgen.probes[${i}]`;
    if (!p || typeof p !== "object") { e.push(`${k} must be an object`); return; }
    if (!PROBE_ID_RE.test(String(p.id || ""))) e.push(`${k}.id must be 1-64 chars of a-z 0-9 _ . -`);
    else if (seen.has(p.id)) e.push(`${k}.id ${p.id} is used twice`); else seen.add(p.id);
    if (typeof p.feature !== "string" || !p.feature || p.feature.length > 120 || /[\\r\\n]/.test(p.feature)) e.push(`${k}.feature must be a one-line name (1-120 chars)`);
    if (!DIM_RE.test(String(p.dimension || ""))) e.push(`${k}.dimension must be a namespaced dimension id`);
