// Cyrus Test Flight WORLDGEN DENSITY PROBES (2026-10-12, universal-modder finding 2), pure half. "The dimension loads" is
// not the same as "the ore generates": the runner (services/modbuilder/tools/testflight/runner.js tf-lite-6, lib.js
// probeCommands / parseFill / judgeProbe, parity-tested with this file) force-loads chunks in the pack's own dimension
// and counts a feature's blocks with `execute in <dim> run fill <16 x h x 16 box> minecraft:air replace <block>`; this
// module derives each probe's EXPECTED RANGE from the data pack spec (placed ore features), validates probe specs, and
// turns the runner's result into a stored record.
//
// The range is deliberately coarse and stated as such (vanilla ore blobs are random):
//   max = attemptsMax x 8 x size x chunks x 2   (a blob is a capsule of spheres along a line of size/4 blocks with
//         radius <= size/16 + 0.5, so it stays under 8 x size blocks; x2 for blobs spilling in from neighbour chunks);
//   min = 1 only when the spec PROMISES ore in the probed box: a fixed count >= 1 (no rarity), the feature listed in every
//         biome of the dimension, at least 4 expected attempts in the probed height, no air-exposure discard. Else 0,
//         with the reason in the probe's `why` (the probe then only catches "far too much").
// So it catches "nothing generated" (placed in air, wrong step / biome list, a broken pack) and "an order of magnitude too
// dense" (count 64 instead of 4), not small tuning differences.
// Switch: CYRUS_TESTFLIGHT_WORLDGEN=1 adds the probes to gate flights (default OFF); the record never blocks Install.
import type { DataPackSpec } from "../datapack/spec";

export const WORLDGEN_PROBE_FLAG = "CYRUS_TESTFLIGHT_WORLDGEN";
export const PROBE_LIMITS = { probes: 8, blocks: 4, chunks: 4, chunkCoord: 64, minY: -2032, maxY: 2031, height: 384, slice: 64, waitSec: 60, count: 10_000_000 } as const;

export type WorldgenProbe = {
  id: string;
  /** What is being measured, for the failure message (e.g. "nx_ab12cd34:amethyst_ore"). */
  feature: string;
  dimension: string;
  /** Blocks counted (summed): an ore feature's target blocks. */
  blocks: string[];
  /** Sampled chunk columns [cx, cz]; each is force-loaded with its 8 neighbours. */
  chunks: [number, number][];
  yMin: number;
  height: number;
  expect: { min: number; max: number };
  /** Why the range is what it is (shown on a failure). */
  why?: string;
};
export type WorldgenSpec = { probes: WorldgenProbe[]; waitSec?: number };
export type FillReply = { kind: "count"; count: number } | { kind: "unloaded" | "toobig" | "outofworld" | "error"; text: string };
export type ProbeResult = { id: string; status: "pass" | "fail" | "not_run"; measured: number | null; expected: { min: number; max: number }; perChunk: Record<string, number>; line: string };

export function worldgenProbesEnabled(env: Record<string, string | undefined> = process.env): boolean {
  return env[WORLDGEN_PROBE_FLAG] === "1";
}

const DIM_RE = /^[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const BLOCK_RE = /^[a-z0-9_.-]+:[a-z0-9_/]+$/;
const PROBE_ID_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;
const isInt = (v: unknown, lo: number, hi: number) => Number.isInteger(v) && (v as number) >= lo && (v as number) <= hi;

/** Same rules as lib.js validateWorldgen. */
export function validateWorldgen(w: WorldgenSpec): string[] {
  const e: string[] = [];
  if (!w || typeof w !== "object" || Array.isArray(w)) return ["worldgen must be an object"];
  const ps = w.probes;
  if (!Array.isArray(ps) || !ps.length || ps.length > PROBE_LIMITS.probes) return [`worldgen.probes must hold 1-${PROBE_LIMITS.probes} probes`];
  const seen = new Set<string>();
  ps.forEach((p, i) => {
    const k = `worldgen.probes[${i}]`;
    if (!p || typeof p !== "object") { e.push(`${k} must be an object`); return; }
    if (!PROBE_ID_RE.test(String(p.id ?? ""))) e.push(`${k}.id must be 1-64 chars of a-z 0-9 _ . -`);
    else if (seen.has(p.id)) e.push(`${k}.id ${p.id} is used twice`); else seen.add(p.id);
    if (typeof p.feature !== "string" || !p.feature || p.feature.length > 120 || /[\r\n]/.test(p.feature)) e.push(`${k}.feature must be a one-line name (1-120 chars)`);
    if (!DIM_RE.test(String(p.dimension ?? ""))) e.push(`${k}.dimension must be a namespaced dimension id`);
    if (!Array.isArray(p.blocks) || !p.blocks.length || p.blocks.length > PROBE_LIMITS.blocks || p.blocks.some((b) => !BLOCK_RE.test(String(b)))) e.push(`${k}.blocks must be 1-${PROBE_LIMITS.blocks} block ids`);
    if (!Array.isArray(p.chunks) || !p.chunks.length || p.chunks.length > PROBE_LIMITS.chunks || p.chunks.some((c) => !Array.isArray(c) || c.length !== 2 || !c.every((x) => isInt(x, -PROBE_LIMITS.chunkCoord, PROBE_LIMITS.chunkCoord)))) e.push(`${k}.chunks must be 1-${PROBE_LIMITS.chunks} [cx, cz] pairs within +-${PROBE_LIMITS.chunkCoord}`);
    if (!isInt(p.yMin, PROBE_LIMITS.minY, PROBE_LIMITS.maxY)) e.push(`${k}.yMin must be a whole number ${PROBE_LIMITS.minY}..${PROBE_LIMITS.maxY}`);
    if (!isInt(p.height, 1, PROBE_LIMITS.height)) e.push(`${k}.height must be 1-${PROBE_LIMITS.height}`);
    const x = p.expect;
    if (!x || !isInt(x.min, 0, PROBE_LIMITS.count) || !isInt(x.max, 0, PROBE_LIMITS.count) || x.min > x.max) e.push(`${k}.expect must be { min, max } whole numbers with min <= max`);
    if (p.why != null && (typeof p.why !== "string" || p.why.length > 300)) e.push(`${k}.why must be text of at most 300 chars`);
  });
  if (w.waitSec != null && !isInt(w.waitSec, 1, PROBE_LIMITS.waitSec)) e.push(`worldgen.waitSec must be 1-${PROBE_LIMITS.waitSec}`);
  return e;
}

const strip = (s: string) => String(s ?? "").replace(/§[0-9a-fk-orx]/gi, "");
/** Twin of lib.js parseFill. */
export function parseFill(text: string): FillReply {
  const t = strip(text).trim();
  const m = /Successfully filled ([\d,]+) block/i.exec(t);
  if (m) return { kind: "count", count: Number(m[1].replace(/,/g, "")) };
  if (/No blocks were filled/i.test(t)) return { kind: "count", count: 0 };
  if (/position is not loaded/i.test(t)) return { kind: "unloaded", text: t.slice(0, 200) };
  if (/Too many blocks/i.test(t)) return { kind: "toobig", text: t.slice(0, 200) };
  if (/out of this world|outside the allowed/i.test(t)) return { kind: "outofworld", text: t.slice(0, 200) };
  return { kind: "error", text: t.slice(0, 200) };
}

/** Twin of lib.js judgeProbe. */
export function judgeProbe(p: WorldgenProbe, slices: { chunk: [number, number]; block: string; reply: FillReply | null }[]): ProbeResult {
  const bad = slices.find((s) => !s.reply || s.reply.kind !== "count");
  const total = slices.reduce((a, s) => a + (s.reply && s.reply.kind === "count" ? s.reply.count : 0), 0);
  const per: Record<string, number> = {};
  for (const s of slices) if (s.reply && s.reply.kind === "count") { const k = s.chunk.join(","); per[k] = (per[k] ?? 0) + s.reply.count; }
  const where = `${p.chunks.length} chunk column${p.chunks.length > 1 ? "s" : ""} of ${p.dimension} (y ${p.yMin}..${p.yMin + p.height - 1})`;
  const blocks = p.blocks.map((b) => b.replace(/^minecraft:/, "")).join(" + ");
  if (!slices.length || bad) {
    const r = bad?.reply;
    return { id: p.id, status: "not_run", measured: null, expected: p.expect, perChunk: per, line: `${p.id}: ${p.feature}: not measured (${bad ? `${r ? r.kind : "no reply"}: ${r && r.kind !== "count" && r.text ? r.text : "the fill command did not answer"}` : "no fill commands"})` };
  }
  const ok = total >= p.expect.min && total <= p.expect.max;
  const line = ok
    ? `${p.id}: ${p.feature}: ${total} ${blocks} in ${where}, expected ${p.expect.min}-${p.expect.max}: ok`
    : `${p.id}: ${p.feature} ${total < p.expect.min ? "generated too little" : "generated too much"}: measured ${total} ${blocks} in ${where}, expected ${p.expect.min}-${p.expect.max}${p.why ? ` (${p.why})` : ""}`;
  return { id: p.id, status: ok ? "pass" : "fail", measured: total, expected: p.expect, perChunk: per, line: line.slice(0, 400) };
}

// ------------------------------------------------------------------ expectations from the data pack spec ----
type Res = DataPackSpec["resources"][number];
const PRESET_Y: Record<string, { minY: number; height: number }> = { overworld: { minY: -64, height: 384 }, nether: { minY: 0, height: 256 }, end: { minY: 0, height: 256 } };
/** Terrain presets where a stone ore target is under the surface everywhere (floating_islands / end: mostly air). */
const SOLID_TERRAIN = new Set(["overworld", "large_biomes", "amplified", "caves", "nether"]);
const SAMPLE_CHUNKS: [number, number][] = [[2, 2], [-3, 2], [2, -3], [-3, -3]];

type Anchor = { absolute: number } | { aboveBottom: number } | { belowTop: number };
const anchorY = (a: Anchor, minY: number, height: number) => ("absolute" in a ? a.absolute : "aboveBottom" in a ? minY + a.aboveBottom : minY + height - 1 - a.belowTop);

/**
 * Probes for every OWN placed ore feature that one of the pack's own dimensions' biomes lists. Pure; never throws.
 * `notes` say why a feature got no probe (vanilla feature: its density is not modelled here; not in any own dimension).
 */
export function worldgenProbesFor(spec: unknown, namespace: string): { probes: WorldgenProbe[]; notes: string[] } {
  const notes: string[] = [];
  const res = (spec && typeof spec === "object" && Array.isArray((spec as DataPackSpec).resources) ? (spec as DataPackSpec).resources : []) as Res[];
  const by = <T extends Res["type"]>(t: T) => res.filter((r): r is Extract<Res, { type: T }> => r.type === t);
  const own = (id: string) => (id.includes(":") ? id : `${namespace}:${id}`);
  const configured = new Map(by("configured_feature").map((r) => [own(r.id), r.feature]));
  const placed = new Map(by("placed_feature").map((r) => [own(r.id), r.placed]));
  const types = new Map(by("dimension_type").map((r) => [own(r.id), r.dimensionType]));
  const biomes = new Map(by("biome").map((r) => [own(r.id), r.biome]));
  const probes: WorldgenProbe[] = [];
  for (const d of by("dimension")) {
    const dimId = own(d.id);
    const g = d.dimension.generator;
    const dimBiomes = g.kind === "flat" ? [g.biome] : g.biomes.kind === "fixed" ? [g.biomes.biome] : g.biomes.kind === "checkerboard" ? g.biomes.biomes : g.biomes.biomes.map((b) => b.biome);
    const dt = types.get(d.dimension.dimensionType);
    const base = dt ? PRESET_Y[dt.preset] : d.dimension.dimensionType === "minecraft:the_nether" ? PRESET_Y.nether : d.dimension.dimensionType === "minecraft:the_end" ? PRESET_Y.end : PRESET_Y.overworld;
    const minY = dt?.minY ?? base.minY, height = dt?.height ?? base.height;
    const listed = new Map<string, number>(); // placed feature -> number of the dimension's biomes listing it
    for (const b of dimBiomes) for (const f of biomes.get(b)?.features ?? []) listed.set(f.feature, (listed.get(f.feature) ?? 0) + 1);
    for (const [pf, nBiomes] of listed) {
      if (!pf.startsWith(`${namespace}:`)) { if (/ore/.test(pf)) notes.push(`${dimId}: ${pf} is a vanilla feature; its density is not probed`); continue; }
      const p = placed.get(pf);
      const cf = p ? configured.get(p.feature) : undefined;
      if (!p || !cf || cf.kind !== "ore") continue;
      let cMin = 1, cMax = 1, rarity = false, lo = minY, hi = minY + height - 1;
      for (const m of p.placement) {
        if (m.kind === "count") { if (typeof m.count === "number") { cMin = m.count; cMax = m.count; } else { cMin = m.count.min; cMax = m.count.max; } }
        else if (m.kind === "rarity") rarity = true;
        else if (m.kind === "height_range") { lo = anchorY(m.min, minY, height); hi = anchorY(m.max, minY, height); }
      }
      const yMin = Math.max(minY, Math.min(lo, hi));
      const yMax = Math.min(minY + height - 1, Math.max(lo, hi));
      if (yMax < yMin) { notes.push(`${pf}: its height range is outside ${dimId}; not probed`); continue; }
      const h = Math.min(PROBE_LIMITS.height, yMax - yMin + 1);
      const chunks = SAMPLE_CHUNKS;
      const overlap = h / Math.max(1, Math.abs(hi - lo) + 1);
      const max = Math.min(PROBE_LIMITS.count, Math.ceil(cMax * 8 * cf.size * chunks.length * 2));
      const why: string[] = [];
      if (rarity) why.push("rarity: not every chunk gets it");
      if (cMin < 1) why.push("count can be 0");
      if (nBiomes < dimBiomes.length) why.push(`listed in ${nBiomes} of ${dimBiomes.length} biomes`);
      if (cf.discardOnAirExposure && cf.discardOnAirExposure > 0) why.push("discarded next to air");
      if (cMin * chunks.length * overlap < 4) why.push("fewer than 4 expected attempts in the box");
      if (g.kind === "noise" && !SOLID_TERRAIN.has(g.terrain)) why.push(`${g.terrain} terrain is mostly air`);
      const min = why.length ? 0 : 1;
      probes.push({
        id: `${pf.split(":")[1].replace(/[^a-z0-9_.-]/g, "_")}-${d.id.replace(/[^a-z0-9_.-]/g, "_")}`.slice(0, 64),
        feature: pf, dimension: dimId,
        blocks: [...new Set(cf.targets.map((t) => (typeof t.block === "string" ? t.block : t.block.block)))].slice(0, PROBE_LIMITS.blocks),
        chunks, yMin, height: h, expect: { min, max },
        why: min ? `count ${cMin === cMax ? cMin : `${cMin}-${cMax}`} x size ${cf.size} per chunk in y ${lo}..${hi}: at least one block expected, at most ${max}` : `lower bound not checked (${why.join("; ")}); at most ${max}`,
      });
      if (probes.length >= PROBE_LIMITS.probes) return { probes, notes };
    }
  }
  return { probes, notes };
}

// ------------------------------------------------------------------ stored record ----
export type StoredWorldgen = { schema: 1; verdict: "pass" | "fail" | "not_run"; label: string; probes: { id: string; feature: string; status: string; measured: number | null; expected: { min: number; max: number } }[] };

/** The record kept on the build (StoredFlight.worldgen). Informational: it never changes the boot verdict or blocks Install. */
export function storedWorldgen(raw: unknown, sent: WorldgenProbe[]): StoredWorldgen {
  const r = raw as { probes?: (ProbeResult & { feature?: string })[] } | null;
  const got = Array.isArray(r?.probes) ? r!.probes : [];
  const probes = sent.map((p) => {
    const x = got.find((g) => g && g.id === p.id);
    return { id: p.id, feature: p.feature, status: x && ["pass", "fail", "not_run"].includes(x.status) ? x.status : "not_run", measured: x && typeof x.measured === "number" ? x.measured : null, expected: p.expect, line: x?.line };
  });
  const fail = probes.find((p) => p.status === "fail");
  const verdict = fail ? "fail" : probes.length && probes.every((p) => p.status === "pass") ? "pass" : "not_run";
  const label = verdict === "pass" ? `World generation measured: ${probes.length} feature${probes.length > 1 ? "s" : ""} inside the expected density.`
    : verdict === "fail" ? `World generation check FAILED: ${(fail!.line ?? `${fail!.feature}: measured ${fail!.measured}, expected ${fail!.expected.min}-${fail!.expected.max}`).replace(/^[^:]+: /, "")}`
    : `World generation not measured${probes.find((p) => p.status === "not_run")?.line ? `: ${probes.find((p) => p.status === "not_run")!.line!.replace(/^[^:]+: /, "")}` : ""}.`;
  return { schema: 1, verdict, label: label.slice(0, 400), probes: probes.map(({ line: _l, ...p }) => p) };
}

