describe("worldgen probes in the gate (CYRUS_TESTFLIGHT_WORLDGEN=1)", () => {
  it("probes ride in the flight, the record is stored apart and the boot verdict ignores it", async () => {
    const sent: TestFlightSpec[] = [];
    const store = new Map<string, StoredFlight>();
    const chk = (id: CheckResult["id"], status: CheckResult["status"] = "pass"): CheckResult => ({ id, status, required: true, evidence: ["x"], durationMs: 1 });
    const B: GateBuild = { id: "w1", mcVersion: "1.21.11", pluginName: "NxRealm", jarSha256: H("jar"), result: { commands: [], safety: { verdict: "pass" } } };
    const mk = (env: Record<string, string>): GateDeps => ({
      env, now: () => NOW,
      async candidates() { return []; },
      async artifacts() { return { jarPath: "/tmp/realm.jar", datapacks: [{ name: "nxeon-nx_worldg01-crystal_realm", localPath: "/tmp/dp.zip", spec: SHOWCASE, namespace: NS }] }; },
      async run(spec) {
        sent.push(spec);
        const probes = (spec.worldgen?.probes ?? []).map((p) => LIB.judgeProbe(p, LIB.probeCommands(p).fills.map((f: { chunk: [number, number]; block: string }) => ({ ...f, reply: { kind: "count", count: 0 } }))));
        const r: TestFlightReport = { schema: 1, runId: "tf-w", status: "completed", version: "1.21.11", javaRelease: 21, startedAt: NOW.toISOString(), finishedAt: NOW.toISOString(), checks: [chk("boot_done"), chk("plugins_enabled"), chk("startup_log_clean"), chk("rcon_checks"), chk("worldgen", probes.length ? "fail" : "not_run"), chk("clean_stop"), chk("no_leaks")], timings: {}, bootMs: 1, doneReportedSec: 1, peakRssKb: 1, artifacts: [], engine: null, notes: [], overall: "failed", worldgen: { schema: 1, probes } };
        return { report: r, summary: summarize(spec, r), resolved: {} as never, stderr: "" };
      },
      async store(id, f) { store.set(id, JSON.parse(JSON.stringify(f))); },
    });
    await flyOne(B, null, mk({ CYRUS_TESTFLIGHT_GATE: "1", CYRUS_TESTFLIGHT_STRESS: "0" }), () => NOW);
    assert.equal(sent[0].worldgen, undefined, "off by default");
    assert.equal(store.get("w1")!.worldgen, undefined);
    await flyOne({ ...B, id: "w2" }, null, mk({ CYRUS_TESTFLIGHT_GATE: "1", CYRUS_TESTFLIGHT_STRESS: "0", CYRUS_TESTFLIGHT_WORLDGEN: "1" }), () => NOW);
    assert.ok(sent[1].worldgen!.probes.length >= 1);
    const f = store.get("w2")!;
    assert.equal(f.worldgen!.verdict, "fail");
    assert.match(f.worldgen!.label, /amethyst_ore generated too little: measured 0/);
    assert.equal(f.verdict, "passed", "the boot verdict is judged on the boot spec alone");
  });
});
EOF
