// Cyrus R4 worldgen: what differs per Minecraft version for world generation files, plus the block state tables,
// world DataVersions and vanilla noise ranges derived from each pinned jar (data/worldgen-data.json, see
// scripts/cyrus/datapack-derive.py `worldgen`). Every difference below was VERIFIED on the real jars (2026-10-10,
// node-2): the vanilla data generator's own worldgen files were compared across 1.21.1 .. 26.2 and cross-checked with
// vanilla-mcdoc (docs "Cyrus worldgen (R4)"), then the emitted packs were booted with Test Flight.
import data from "../data/worldgen-data.json";
import { atLeast, DATAPACK_VERSIONS } from "../versions";

type WgData = { versions: string[]; dataVersion: Record<string, number>; noise: Record<string, Record<string, { minY: number; height: number }>>; blockStates: Record<string, Record<string, string[]>> };
const WG = data as unknown as WgData;
export const WORLDGEN_DATA_SOURCE = (data as unknown as { source: unknown }).source;

export type WorldgenFeatures = {
  version: string;
  /** World DataVersion written into structure NBT (the jar's version.json world_version). */
  dataVersion: number;
  /** <1.21.2: biome carvers are a map {"air": [...]}; >=1.21.2: a list. */
  carvers: "map" | "list";
  /**
   * <1.21.11: sky / fog / water fog colours, sounds, music and particles live in biome `effects` (colours as ints);
   * >=1.21.11: they are ENVIRONMENT ATTRIBUTES (`attributes`: minecraft:visual/sky_color, audio/background_music, ...),
   * `effects` keeps only water / grass / foliage colours, and colours are "#rrggbb" strings.
   */
  biome: "effects" | "attributes";
  /** <1.21.4: effects.music is one object; 1.21.4 .. 1.21.10: a weighted list [{data, weight}]. (Attributes: background_music.default.) */
  music: "single" | "weighted";
  /** effects.dry_foliage_color exists from 1.21.5. */
  dryFoliage: boolean;
  /**
   * <1.21.11: dimension_type has ultrawarm / natural / piglin_safe / bed_works / respawn_anchor_works / has_raids /
   * fixed_time / effects; >=1.21.11: those are environment attributes + has_fixed_time / skybox / cardinal_light /
   * timelines. >=26.1 adds default_clock and the REQUIRED has_ender_dragon_fight.
   */
  dimensionType: "classic" | "attributes";
  worldClock: boolean;
  /** <26.1: patches are the random_patch feature; >=26.1 random_patch / flower are gone (registry) and vanilla
   *  expresses a patch as a simple_block feature placed with count + random_offset + a block filter. */
  patch: "random_patch" | "placement";
  /** <26.1: tree dirt_provider + force_dirt; >=26.1: below_trunk_provider (required from 26.2). */
  treeDirt: "dirt_provider" | "below_trunk_provider";
