// Cyrus Test Flight PROVE-THE-HARNESS-CAN-FAIL (2026-10-12, universal-modder finding 3), pure half. A green Test Flight
// only means something if the same harness turns RED on a known-bad mod, and says WHY in words that name the cause
// ("empty log" or "not run" is not a rejection). Each mutant is a one-defect variant of a good control; the self-check
// requires: the targeted check FAILED, the flight's overall verdict is not a success, and the evidence names the cause.
// Real flights of these mutants + their controls: test/cyrus-mc-mutants-real.ts (node-2). The pure suite
// (test/cyrus-mc-testing.test.ts) runs the same judge over the runner's evidence shapes.
// Test-only: the fixtures are under services/modbuilder/tools/testflight/fixtures; nothing here touches a network.
import { requiredStages } from "./spec";
import { summarize } from "./summary";
import type { CheckId, TestFlightReport, TestFlightSpec } from "./types";

export type Mutant = {
  id: string;
  /** The defect, in plain words. */
  what: string;
  /** The Test Flight check that must catch it. */
  check: Extract<CheckId, "plugins_enabled" | "stress" | "worldgen">;
  /** The evidence must match this (it names the cause). */
  cause: RegExp;
  /** The good control flown the same way: it must PASS, or the mutant proves nothing. */
  control: string;
};

export const MUTANTS: readonly Mutant[] = [
  { id: "throws-on-enable", what: "a plugin that throws an exception in onEnable", check: "plugins_enabled", cause: /TfBroken: NOT enabled .*enableError=true/, control: "the TfHello plugin enables" },
  { id: "main-thread-spam", what: "a plugin that busy-waits on the main thread every tick", check: "stress", cause: /(TPS stayed under \d+(\.\d+)? for|the mod keeps the main thread busy every tick)/, control: "TfHello holds 20 TPS under the same load" },
  { id: "ore-in-air", what: "a worldgen pack whose ore is placed above the terrain (nothing to replace)", check: "worldgen", cause: /amethyst_ore generated too little: measured 0 /, control: "the showcase pack's amethyst ore is found in its range" },
];

export type MutantVerdict = { id: string; rejected: boolean; message: string };

/**
 * Was the mutant REJECTED for the right reason? Not rejected when the targeted check passed (the harness accepted a
 * broken mod), did not run (proves nothing), failed without naming the cause, or the flight still counts as a success.
 */
export function judgeMutant(m: Mutant, spec: TestFlightSpec, report: TestFlightReport): MutantVerdict {
  const c = (report.checks ?? []).find((x) => x.id === m.check);
  const s = summarize(spec, report);
  const ev = (c?.evidence ?? []).join(" | ");
  if (!requiredStages(spec).has(m.check)) return { id: m.id, rejected: false, message: `${m.id}: the spec does not require ${m.check}, so it cannot reject the mutant` };
  if (!c || c.status === "not_run") return { id: m.id, rejected: false, message: `${m.id}: ${m.check} did not run (${ev.slice(0, 200) || "no evidence"}): that proves nothing` };
  if (c.status === "pass") return { id: m.id, rejected: false, message: `${m.id}: the harness ACCEPTED ${m.what} (${m.check} passed: ${ev.slice(0, 200)})` };
  if (s.success) return { id: m.id, rejected: false, message: `${m.id}: ${m.check} failed but the flight still counts as a success` };
  if (!m.cause.test(ev)) return { id: m.id, rejected: false, message: `${m.id}: ${m.check} failed without naming the cause (wanted ${m.cause}, got: ${ev.slice(0, 240) || "no evidence"})` };
  return { id: m.id, rejected: true, message: `${m.id}: rejected by ${m.check}: ${(ev.match(m.cause)?.[0] ?? "").slice(0, 160)}` };
}

/** The control must pass the same check (else a "rejection" could just be a broken harness). */
export function judgeControl(m: Mutant, spec: TestFlightSpec, report: TestFlightReport): MutantVerdict {
  const c = (report.checks ?? []).find((x) => x.id === m.check);
  const ok = !!c && c.status === "pass" && c.evidence.some((e) => String(e).trim());
  return { id: `${m.id}:control`, rejected: !ok, message: ok ? `${m.id} control: ${m.control}: ${m.check} passed` : `${m.id} control FAILED (${m.check} ${c?.status ?? "missing"}: ${(c?.evidence ?? []).join(" | ").slice(0, 200)}): the mutant result proves nothing` };
}

// ------------------------------------------------------------------ the worldgen mutant ----
/** The showcase-style pack with every own ore placement moved to y 200..250 (air above the terrain). Pure; deep copy. */
export function oreInAir<T>(spec: T): T {
  const s = JSON.parse(JSON.stringify(spec)) as { resources?: { type: string; placed?: { placement: { kind: string; min?: unknown; max?: unknown }[] } }[] };
  for (const r of s.resources ?? []) {
    if (r.type !== "placed_feature" || !r.placed) continue;
    for (const m of r.placed.placement) if (m.kind === "height_range") { m.min = { absolute: 200 }; m.max = { absolute: 250 }; }
  }
  return s as T;
}

