// REAL Test Flight runs ON node-2 for the 2026-10-12 Minecraft testing upgrades (not part of the unit suite: real javac,
// real JVM, real Paper boots, the pinned Mineflayer bot). Branch feature/cyrus-mc-testing-weapons.
//   scripts/devhost run --lock --max 1500 -- npx tsx test/cyrus-mc-mutants-real.ts [--out <json>] [--only <name>]
// Flights on Paper 1.21.11 (the version with a verified bot):
//   control-combat     TfHello + stress with the SURVIVAL combat bot      -> stress pass, bot in survival, hits > 0
//   mutant-broken      TfBroken (throws in onEnable)                       -> plugins_enabled REJECTS, names TfBroken
//   mutant-spam        TfSpam (spins the main thread 90 ms per tick)       -> stress REJECTS (busy main thread)
//   control-worldgen   the worldgen showcase pack + its density probes     -> worldgen pass (ore found in range)
//   mutant-ore-in-air  the same pack with the ore moved to y 200..250      -> worldgen REJECTS, names the feature
// No AI model, no real Minecraft client, no network beyond loopback. One flight at a time (node-2 lock), every server
// torn down by the runner; the fill probes only ever run in the throwaway flight world.
import { execFileSync, spawn } from "node:child_process";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { MUTANTS, judgeControl, judgeMutant, oreInAir, type MutantVerdict } from "../lib/cyrus/testflight/mutants";
import { stressSpecFor } from "../lib/cyrus/testflight/stress";
import { worldgenProbesFor } from "../lib/cyrus/testflight/worldgen";
import { buildDataPack } from "../lib/cyrus/datapack/emit";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const JDK = `${TF}/jdk/21`;
const RUN = `${T}/cyrus-mc-mutants/run-${Date.now().toString(36)}`;
const V = "1.21.11";
