      assert.ok(r.source.some((s: string) => /javap/.test(s)), `${id} cites javap`);
      assert.ok(r.source.some((s: string) => /second hand/.test(s)), `${id} marks the field note as second hand`);
      for (const v of ["1.21.1", "1.21.4", "1.21.8", "1.21.11"]) assert.ok(rulesFor(v).some((x: { id: string }) => x.id === id));
    }
    assert.equal(RULES.version, "rules-2026-10-12.1");
    const t = RULES.rules.find((x: { id: string }) => x.id === "teleport-ground-load-chunk-first");
    for (const api of ["getChunkAtAsync", "HeightMap.MOTION_BLOCKING_NO_LEAVES", "isPassable()", "hasCeiling()"]) assert.ok(t.rule.includes(api), api);
    assert.equal(t.pattern, undefined, "prompt-only: a regex cannot tell a loaded chunk from a far one");
    assert.match(RULES.rules.find((x: { id: string }) => x.id === "mob-move-pathfinder").rule, /getPathfinder\(\)\.moveTo\(target, speed\)/);
  });
  it("the rules reach the build prompt for every buildable version", () => {
    for (const v of ["1.21.1", "1.21.11"]) {
      const s: string = P.systemPrompt(v);
      assert.match(s, /world\.getChunkAtAsync\(x >> 4, z >> 4\)/);
      assert.match(s, /EntityTargetLivingEntityEvent/);
      assert.match(s, /getTicksLived\(\) >= 10/);
    }
    assert.match(P.WORLDGEN_SECTION, /getChunkAtAsync\(x >> 4, z >> 4\)/, "the worldgen teleport example loads the chunk first");
    assert.doesNotMatch(P.WORLDGEN_SECTION, /p\.teleport\(new Location\(w, x, w\.getHighestBlockYAt\(x, z\) \+ 1, z\)\)\./);
  });
  it("precheck: setTarget(null) without a target gate is a build problem; with the gate it is not", () => {
    const bad = src("Calm.java", "class Calm { void calm(org.bukkit.entity.Mob m) { m.setTarget(null); } }");
    const hits = precheck([bad], "1.21.11").filter((h: { rule: string }) => h.rule === "mob-flee-gate-target");
    assert.equal(hits.length, 1); assert.match(hits[0].message, /EntityTargetLivingEntityEvent/);
    const ok = src("Calm2.java", "import org.bukkit.event.entity.EntityTargetLivingEntityEvent;\nclass Calm2 { void calm(org.bukkit.entity.Mob m) { m.setTarget(null); } void on(EntityTargetLivingEntityEvent e) { e.setCancelled(true); } }");
    assert.equal(precheck([ok], "1.21.11").filter((h: { rule: string }) => h.rule === "mob-flee-gate-target").length, 0);
    const tp = src("Rtp.java", "class Rtp { int y(org.bukkit.World w) { return w.getHighestBlockYAt(1, 2); } }");
    assert.equal(precheck([tp], "1.21.11").filter((h: { rule: string }) => h.rule.startsWith("teleport")).length, 0, "prompt-only rule: no precheck hit");
  });
});
