62	  constructor(readonly designs: ItemDesign[], readonly opts: SimOptions) {
63	    this.params = new Map(designParams(designs).map((p) => [p.path, p]));
64	    this.config = opts.config ?? {};
65	    this.worldTime = opts.worldTime ?? 6000;
66	    this.random = new JavaRandom(opts.seed ?? randomSeedFor(opts.namespace));
67	    for (const item of designs) for (const ab of item.abilities) {
68	      const base = `items.${item.id}.abilities.${ab.id}.`;
69	      const p = (rel: string) => this.value(base + rel);
70	      const t = ab.trigger;
71	      this.abilities.push({
72	        item, ab, key: `${item.id}.${ab.id}`, p,
73	        cooldown: ab.cooldownTicks !== undefined ? Number(p("cooldown_ticks")) : 0,
74	        maxCharges: ab.charges ? Number(p("charges.max")) : 0,
75	        regen: ab.charges ? Number(p("charges.regen_ticks")) : 20,
76	        range: "targetRange" in t && t.targetRange !== undefined ? Number(p("trigger.target_range")) : 0,
77	        minCharge: t.type === "charge_release" ? Number(p("trigger.min_charge_ticks")) : 0,
78	        maxCharge: t.type === "charge_release" ? Math.max(Number(p("trigger.min_charge_ticks")), Number(p("trigger.max_charge_ticks"))) : 1,
79	      });
80	    }
81	  }
