83	  /** A parameter value as DesignConfig would load it: the override (config) clamped to the caps, else the design default. */
84	  value(path: string): number | string {
85	    const p = this.params.get(path);
86	    if (!p) throw new Error(`no parameter ${path}`);
87	    const raw = this.config[path];
88	    if (p.kind === "text") { const s = String(raw ?? p.value).replace(/[\u0000-\u001f§]/g, ""); return s.slice(0, p.max); }
89	    if (p.kind === "sound") { const s = String(raw ?? ""); return /^[a-z0-9_.-]+:[a-z0-9_./-]+$/.test(s) && s.length <= 100 ? s : String(p.value); }
90	    let v = typeof raw === "number" && Number.isFinite(raw) ? raw : Number(p.value);
91	    if (v < p.min || v > p.max) { const c = Math.max(p.min, Math.min(p.max, v)); this.notes.push(`clamped ${path} ${v} -> ${c}`); v = c; }
92	    return p.kind === "num" ? v : Math.round(v);
93	  }
