95	  add(e: SimEntity): SimEntity { this.entities.set(e.id, { online: true, height: 1.8, ...e }); return this.entities.get(e.id)!; }
96	  private ent(id?: string | null) { return id ? this.entities.get(id) ?? null : null; }
97	  private say(ab: SimAbility | null, kind: string, subject?: string, detail?: Record<string, unknown>) { this.log.push({ tick: this.tick, ability: ab?.key ?? "-", kind, ...(subject ? { subject } : {}), ...(detail ? { detail } : {}) }); }
98	  private item(id: string) { return this.designs.find((d) => d.id === id) ?? null; }
99	  private abilitiesOf(itemId: string | null | undefined, trigger: string) { return this.abilities.filter((a) => a.item.id === itemId && a.ab.trigger.type === trigger); }
