101	  // ------------------------------------------------------------------------------------------ components (twins)
102	  private cdReady(player: string, key: string) { const t = this.cooldowns.get(player)?.get(key); return t === undefined || t <= this.tick; }
103	  private cdRemaining(player: string, key: string) { const t = this.cooldowns.get(player)?.get(key); return t === undefined ? 0 : Math.max(0, t - this.tick); }
104	  private cdSet(player: string, key: string, ticks: number) { if (ticks > 0) { if (!this.cooldowns.has(player)) this.cooldowns.set(player, new Map()); this.cooldowns.get(player)!.set(key, this.tick + ticks); } }
105	  private chState(player: string, key: string, max: number) {
106	    if (!this.charges.has(player)) this.charges.set(player, new Map());
107	    const m = this.charges.get(player)!;
108	    if (!m.has(key)) m.set(key, { count: max, last: this.tick });
109	    return m.get(key)!;
110	  }
111	  private chRegen(s: { count: number; last: number }, max: number, period: number) {
112	    if (s.count >= max) { s.count = max; s.last = this.tick; return; }
113	    const gained = period <= 0 ? 0 : Math.floor((this.tick - s.last) / period);
114	    if (gained > 0) { s.count = Math.min(max, s.count + gained); s.last = s.count >= max ? this.tick : s.last + gained * period; }
115	  }
116	  chargesLeft(player: string, a: SimAbility) { if (a.maxCharges <= 0) return 0; const s = this.chState(player, a.key, a.maxCharges); this.chRegen(s, a.maxCharges, a.regen); return s.count; }
117	  private spend(player: string, a: SimAbility, n: number) { if (a.maxCharges <= 0) return false; const s = this.chState(player, a.key, a.maxCharges); this.chRegen(s, a.maxCharges, a.regen); if (s.count < n) return false; s.count -= n; return true; }
118	  private markApply(owner: string, target: string, mark: string, duration: number, maxPerOwner: number) {
119	    const k = `${owner}|${mark}`;
120	    if (!this.marks.has(k)) this.marks.set(k, new Map());
121	    const m = this.marks.get(k)!;
122	    this.prune(m);
123	    if (m.delete(target)) this.marksTotal--;
124	    while (m.size >= Math.max(1, maxPerOwner)) { const first = m.keys().next().value as string; m.delete(first); this.marksTotal--; }
125	    if (this.marksTotal >= RUNTIME_CAPS.marksTotal) return false;
126	    m.set(target, this.tick + duration); this.marksTotal++;
127	    return true;
128	  }
129	  private prune(m: Map<string, number>) { for (const [t, u] of [...m]) if (u <= this.tick) { m.delete(t); this.marksTotal--; } }
130	  marked(owner: string, mark: string, center: Vec, radius: number, max: number): SimEntity[] {
131	    const m = this.marks.get(`${owner}|${mark}`);
132	    if (!m) return [];
133	    this.prune(m);
134	    const out = [...m.keys()].map((id) => this.ent(id)).filter((e): e is SimEntity => !!e && e.alive && dist2(e.pos, center) <= radius * radius);
135	    out.sort((a, b) => dist2(a.pos, center) - dist2(b.pos, center) || (a.id < b.id ? -1 : 1));
136	    return out.slice(0, max);
137	  }
138	  hasMark(owner: string, mark: string, target: string) { const u = this.marks.get(`${owner}|${mark}`)?.get(target); return u !== undefined && u > this.tick; }
139	  private forget(id: string) { this.cooldowns.delete(id); this.charges.delete(id); for (const k of [...this.marks.keys()]) if (k.startsWith(`${id}|`)) { this.marksTotal -= this.marks.get(k)!.size; this.marks.delete(k); } this.chargeStart.delete(id); this.lastClick.delete(id); this.active.delete(id); }
140	  private removeTarget(id: string) { for (const m of this.marks.values()) if (m.delete(id)) this.marksTotal--; }
141	  private budget(): Budget { return { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0, exhausted: false }; }
142	  private take(b: Budget, k: "actions" | "entities" | "tasks" | "projectiles") { if (b[k] >= BUDGET[k]) { b.exhausted = true; return false; } b[k]++; return true; }
143	
144	  // ------------------------------------------------------------------------------------------------- protocol
145	  private activation(ab: SimAbility, player: SimEntity, target: SimEntity | null, point: Vec | null, charge: number): Act {
146	    return { ab, player, target, point: point ?? [...player.pos], charge: Math.max(0, Math.min(1, charge)), budget: this.budget() };
147	  }
148	  /** Ability.fire */
149	  fire(a: Act): boolean {
150	    const p = a.player, ab = a.ab;
151	    if (!p.online || (!p.alive && ab.ab.trigger.type !== "death") || this.active.has(p.id)) return false;
152	    this.active.add(p.id);
153	    try {
154	      if (!ab.ab.manualCooldown && ab.cooldown > 0 && !this.cdReady(p.id, ab.key)) { if (ab.ab.feedback) this.say(ab, "feedback", p.id, { text: `${ab.ab.name}: ${(this.cdRemaining(p.id, ab.key) / 20).toFixed(1)}s` }); this.say(ab, "blocked", p.id, { by: "cooldown" }); return false; }
155	      if (!ab.ab.manualCharges && ab.maxCharges > 0 && this.chargesLeft(p.id, ab) < 1) { if (ab.ab.feedback) this.say(ab, "feedback", p.id, { text: `${ab.ab.name}: no charges` }); this.say(ab, "blocked", p.id, { by: "charges" }); return false; }
156	      for (const [i, c] of (ab.ab.conditions ?? []).entries()) if (!this.cond(a, c, `c${i}`)) { this.say(ab, "blocked", p.id, { by: `condition ${c.type}` }); return false; }
157	      if (!ab.ab.manualCooldown && ab.cooldown > 0) this.cdSet(p.id, ab.key, ab.cooldown);
158	      if (!ab.ab.manualCharges && ab.maxCharges > 0) this.spend(p.id, ab, 1);
159	      this.say(ab, "fired", p.id, { target: a.target?.id ?? null, charge: a.charge });
160	      this.run(a, ab.ab.actions, "");
161	      return true;
162	    } finally { this.active.delete(p.id); }
163	  }
