165	  private other(a: Act, id?: string) { return !id || id === a.ab.ab.id ? a.ab : this.abilities.find((x) => x.item.id === a.ab.item.id && x.ab.id === id) ?? null; }
166	  private targetIs(e: SimEntity | null, kinds: string[] | undefined, types: string[] | undefined) {
167	    if (!e || !e.alive) return false;
168	    const living = e.kind !== "other" && e.kind !== "armor_stand";
169	    if (kinds?.length && living && (kinds.includes("living") || kinds.includes(e.kind))) return true;
170	    return !!types?.length && types.map((t) => t.replace(/^minecraft:/, "")).includes(e.type);
171	  }
172	
173	  private cond(a: Act, c: Condition, rel: string): boolean {
174	    const P = (k: string) => Number(a.ab.p(`${rel}.${k}`));
175	    const neg = (x: boolean) => (c.negate ? !x : x);
176	    switch (c.type) {
177	      case "cooldown_ready": { const o = this.other(a, c.ability); return neg(!o || this.cdReady(a.player.id, o.key)); }
178	      case "has_permission": return neg((a.player.permissions ?? []).includes(`${this.opts.namespace}.${c.node}`));
179	      case "target_is": { const t = a.target && a.target.alive ? a.target : null; if (!t) return false; const r = this.targetIs(t, c.kinds, c.types); return c.negate ? !r : r; }
180	      case "world_in": return neg(c.worlds.includes(a.player.world));
181	      case "health_below": case "health_above": {
182	        const s = c.subject === "self" ? a.player : a.target && a.target.alive ? a.target : null;
183	        if (!s) return false;
184	        const f = s.maxHealth <= 0 ? 0 : s.health / s.maxHealth;
185	        return neg(c.type === "health_below" ? f < P("fraction") : f > P("fraction"));
186	      }
187	      case "item_identity": return neg((c.slot === "main_hand" ? a.player.mainHand : a.player.offHand) === c.item);
188	      case "sneaking": return neg(!!a.player.sneaking);
189	      case "charges_available": { const o = this.other(a, c.ability); return neg(!!o && this.chargesLeft(a.player.id, o) >= P("amount")); }
190	      case "random_chance": return neg(this.random.nextDouble() < P("chance"));
191	      case "time_of_day": { const t = ((this.worldTime % 24000) + 24000) % 24000, f = P("from"), to = P("to"); return neg(f <= to ? t >= f && t <= to : t >= f || t <= to); }
192	    }
193	  }
194	
195	  private run(a: Act, list: Action[], prefix: string): boolean {
196	    for (const [i, x] of list.entries()) {
197	      const rel = prefix ? `${prefix}${i}` : `a${i}`;
198	      if (!this.take(a.budget, "actions")) { this.say(a.ab, "budget_exhausted", a.player.id, { at: rel }); return false; }
199	      if (!this.act(a, x, rel)) return false;
200	    }
201	    return true;
202	  }
203	
204	  private act(a: Act, x: Action, rel: string): boolean {
205	    const P = (k: string) => a.ab.p(`${rel}.${k}`);
206	    const N = (k: string) => Number(P(k));
207	    const subj = (t: string | undefined, dflt: "self" | "target") => ((t ?? dflt) === "self" ? a.player : a.target && a.target.alive ? a.target : null);
208	    const where = (w?: string): Vec | null => (w === "target" ? (a.target && a.target.alive ? [a.target.pos[0], a.target.pos[1] + (a.target.height ?? 1.8) / 2, a.target.pos[2]] : null) : w === "point" ? a.point : [a.player.pos[0], a.player.pos[1] + 1, a.player.pos[2]]);
209	    const scale = (b?: boolean) => (b ? a.charge : 1);
210	    const ent = (e: SimEntity | null) => !!e && e.alive && this.take(a.budget, "entities");
211	    switch (x.type) {
212	      case "damage": { const t = subj(x.target, "target"); const amt = N("amount") * scale(x.scaleWithCharge); if (!t || !t.alive || amt <= 0 || !ent(t)) break; t.health -= amt; this.say(a.ab, "damage", t.id, { amount: amt }); if (t.health <= 0) { t.health = 0; t.alive = false; this.say(a.ab, "died", t.id); this.deathEvent(t, t === a.player ? null : a.player); } break; }
213	      case "heal": { const t = subj(x.target, "self"); const amt = N("amount") * scale(x.scaleWithCharge); if (!t || amt <= 0 || !ent(t)) break; t.health = Math.min(t.maxHealth, t.health + amt); this.say(a.ab, "heal", t.id, { amount: amt }); break; }
214	      case "potion_effect": { const t = subj(x.target, "self"); if (!t || !ent(t)) break; this.say(a.ab, "potion", t.id, { effect: x.effect, ticks: N("duration_ticks"), amplifier: N("amplifier") }); break; }
215	      case "knockback": case "pull_to": case "push_from": {
216	        const t = subj(x.target, "target");
217	        if (!t || !t.alive) break;
218	        let dir: Vec;
219	        if (x.type === "knockback") { if (t === a.player) break; dir = [t.pos[0] - a.player.pos[0], 0, t.pos[2] - a.player.pos[2]]; }
220	        else if (x.type === "pull_to") { const to = x.to === "self" ? a.player.pos : a.point; if (Math.sqrt(dist2(to, t.pos)) < 1) break; dir = [to[0] - t.pos[0], 0, to[2] - t.pos[2]]; }
221	        else { const from = x.from === "self" ? a.player.pos : a.point; dir = [t.pos[0] - from[0], 0, t.pos[2] - from[2]]; }
222	        if (!this.take(a.budget, "entities")) break;
223	        const len = Math.hypot(dir[0], dir[2]); const s = N("strength") * scale(x.scaleWithCharge);
224	        let v: Vec = len < 1e-2 ? [0, N("vertical"), 0] : [dir[0] / len * s, N("vertical"), dir[2] / len * s];
225	        const vl = Math.hypot(...v); if (vl > 4) v = v.map((c) => (c / vl) * 4) as Vec;
226	        this.say(a.ab, x.type, t.id, { velocity: v.map((c) => +c.toFixed(4)) });
227	        break;
228	      }
229	      case "teleport_short": this.say(a.ab, "teleport", a.player.id, { range: N("range") }); break;
230	      case "launch_projectile": { if (!this.take(a.budget, "projectiles")) break; this.projectiles.push({ owner: a.player.id, item: a.ab.item.id, tag: x.tag ?? "" }); this.say(a.ab, "launch", a.player.id, { kind: x.kind, speed: N("speed"), tag: x.tag ?? "" }); if (this.take(a.budget, "tasks")) this.schedule(N("lifetime_ticks"), () => {}); break; }
231	      case "spawn_particles": { const at = where(x.at); if (!at) break; const want = N("count"); const n = Math.max(0, Math.min(want, BUDGET.particles - a.budget.particles)); a.budget.particles += n; if (n < want) a.budget.exhausted = true; if (n > 0) this.say(a.ab, "particles", undefined, { particle: x.particle, count: n }); break; }
232	      case "play_sound": { const at = where(x.at); if (!at) break; this.say(a.ab, "sound", undefined, { key: P("sound"), volume: N("volume"), pitch: N("pitch") }); break; }
233	      case "send_message": case "actionbar": case "title": {
234	        const to = (x.to ?? "self") === "self" ? a.player : a.target;
235	        if (!to || to.kind !== "player" || !to.online) break;
236	        const fill = (s: string) => s.replace(/\{player\}/g, a.player.id).replace(/\{target\}/g, a.target?.id ?? "");
237	        this.say(a.ab, x.type, to.id, { text: fill(String(P(x.type === "title" ? "title" : "text"))) });
238	        break;
239	      }
240	      case "give_item": this.say(a.ab, "give", a.player.id, { item: x.item, count: N("count") }); break;
241	      case "set_cooldown": { const o = this.other(a, x.ability); if (o) this.cdSet(a.player.id, o.key, N("ticks")); break; }
242	      case "consume_charge": { const o = this.other(a, x.ability); if (o) this.spend(a.player.id, o, N("amount")); break; }
243	      case "apply_mark": {
244	        const t = a.target && a.target.alive ? a.target : null;
245	        const def = (a.ab.item.marks ?? []).find((m) => m.name === x.mark)!;
246	        const base = `items.${a.ab.item.id}.marks.${def.name}.`;
247	        if (!t || t === a.player || !this.take(a.budget, "entities")) break;
248	        if (this.markApply(a.player.id, t.id, `${a.ab.item.id}.${x.mark}`, Number(this.value(base + "duration_ticks")), Number(this.value(base + "max_per_owner")))) this.say(a.ab, "mark", t.id, { mark: x.mark });
249	        break;
250	      }
251	      case "query_marked": case "query_nearby": {
252	        const center = x.around === "point" ? a.point : a.player.pos;
253	        const r = N("radius"), max = N("max");
254	        let list: SimEntity[];
255	        if (x.type === "query_marked") list = this.marked(a.player.id, `${a.ab.item.id}.${x.mark}`, center, r, max);
256	        else {
257	          list = [...this.entities.values()].filter((e) => e !== a.player && e.alive && e.kind !== "other" && e.kind !== "armor_stand" && (e.kind !== "player" || !!x.includePlayers)
258	            && (!(x.kinds?.length || x.types?.length) || this.targetIs(e, x.kinds, x.types)) && dist2(e.pos, center) <= r * r);
259	          list.sort((p, q) => dist2(p.pos, center) - dist2(q.pos, center) || (p.id < q.id ? -1 : 1));
260	          list = list.slice(0, max);
261	        }
262	        this.say(a.ab, x.type, undefined, { found: list.map((e) => e.id) });
263	        for (const e of list) if (!this.run({ ...a, target: e }, x.actions, `${rel}.n`)) return false;
264	        break;
265	      }
266	      case "delayed": {
267	        if (!this.take(a.budget, "tasks")) break;
268	        this.schedule(N("delay_ticks"), () => {
269	          if (!a.player.online || !a.player.alive || this.active.has(a.player.id)) return;
270	          this.active.add(a.player.id);
271	          try { this.say(a.ab, "delayed_run", a.player.id); this.run(a, x.actions, `${rel}.n`); } finally { this.active.delete(a.player.id); }
272	        });
273	        break;
274	      }
275	      case "branch": {
276	        const ok = x.if.every((c, j) => this.cond(a, c, `${rel}.if${j}`));
277	        this.say(a.ab, "branch", undefined, { taken: ok ? "then" : x.else ? "else" : "none" });
278	        if (ok) return this.run(a, x.then, `${rel}.then`);
279	        if (x.else) return this.run(a, x.else, `${rel}.else`);
280	        break;
281	      }
282	    }
283	    return true;
284	  }
