286	  /** DesignListener.onDeath twin: kill trigger (skipped while the killer's activation runs = the re-entry guard), mark cleanup, player death. */
287	  private deathEvent(dead: SimEntity, killer: SimEntity | null) {
288	    if (killer && killer !== dead) {
289	      const list = this.abilitiesOf(killer.mainHand, "kill_entity");
290	      if (this.active.has(killer.id)) { if (list.length) this.say(null, "kill_trigger_suppressed", killer.id, { dead: dead.id }); }
291	      else for (const a of list) this.fire(this.activation(a, killer, dead, dead.pos, 0));
292	    }
293	    this.removeTarget(dead.id);
294	    if (dead.kind === "player") {
295	      for (const d of this.designs) if ((dead.inventory ?? []).includes(d.id) || dead.mainHand === d.id) for (const a of this.abilitiesOf(d.id, "death")) this.fire(this.activation(a, dead, null, null, 0));
296	      this.forget(dead.id);
297	    }
298	  }
