300	  private schedule(delay: number, run: () => void) { if (this.tasks.length < RUNTIME_CAPS.liveTasks) this.tasks.push({ at: this.tick + Math.max(1, delay), run }); }
301	
302	  /** Advance time: run due tasks and held_interval timers (first run after one period, like runTaskTimer(p, p)). */
303	  advanceTo(tick: number) {
304	    while (this.tick < tick) {
305	      this.tick++;
306	      this.worldTime = (this.worldTime + 1) % 24000;
307	      for (const t of this.tasks.filter((x) => x.at === this.tick)) { this.tasks.splice(this.tasks.indexOf(t), 1); t.run(); }
308	      for (const a of this.abilities) if (a.ab.trigger.type === "held_interval") {
309	        const period = Math.max(10, Number(a.p("trigger.period_ticks")));
310	        if (this.tick % period !== 0) continue;
311	        for (const p of this.entities.values()) if (p.kind === "player" && p.online && p.alive) {
312	          const has = a.ab.trigger.slot === "inventory" ? (p.inventory ?? []).includes(a.item.id) || p.mainHand === a.item.id || p.offHand === a.item.id : p.mainHand === a.item.id;
313	          if (has) this.fire(this.activation(a, p, null, null, 0));
314	        }
315	      }
316	    }
317	  }
318	
319	  private aim(a: SimAbility, p: SimEntity, clicked: SimEntity | null, look: { target?: string; point: Vec } | undefined, charge: number) {
320	    let target: SimEntity | null = null, point: Vec | null = null;
321	    if (a.range > 0) {
322	      if (clicked && clicked.kind !== "other" && Math.sqrt(dist2(clicked.pos, p.pos)) <= a.range + 1) { target = clicked; point = clicked.pos; }
323	      else if (look) { const t = this.ent(look.target); target = t && t.alive && Math.sqrt(dist2(t.pos, p.pos)) <= a.range + 1 ? t : null; point = look.point; }
324	    }
325	    this.fire(this.activation(a, p, target, point, charge));
326	  }
327	  private frac(a: SimAbility, held: number) { return Math.max(0, Math.min(1, held / Math.max(1, a.maxCharge))); }
328	
329	  /** Feed one event (advances time to its tick first). */
330	  event(e: SimEvent) {
331	    this.advanceTo(e.tick);
332	    if (e.type === "advance") return;
