async function stageWorldgen({ spec, C, out, up, rcon, T }) {
  const chk = C.worldgen;
  const waitMs = ((spec.worldgen && spec.worldgen.waitSec) || 30) * 1000;
  const res = { schema: 1, probes: [] };
  out.worldgen = res;
  if (!up) { chk.evidence.push("server not up; no worldgen probe ran"); return; }
  if (!rcon) { chk.status = "fail"; chk.evidence.push("RCON unavailable: the worldgen probes could not run"); return; }
  let allMeasured = true, anyFail = false;
  // Chunk generation runs on the main thread while RCON waits for it, so worldgen commands get a long timeout. A command
  // that answered "not loaded" or Paper's "Cannot perform command async" did not run and is retried; a TIMED OUT fill is
  // never retried (it may have run: a second fill would count 0 and fake "too little"), the probe is then not measured.
  const rconMs = Math.max(T.rconSec * 1000, 60000);
  const didNotRun = (t) => /Cannot perform command async|position is not loaded/i.test(t);
  for (const p of spec.worldgen.probes) {
    const cmds = L.probeCommands(p);
    const slices = [];
    const notes = [];
    const t0 = now();
    for (const c of cmds.loads) {
      let txt = "";
      for (let k = 0; k < 4; k++) {
        try { txt = L.stripColors((await rcon.command(c, rconMs)).text); } catch (e) { txt = `error: ${e.message}`; }
        if (!/error|exception|Cannot perform/i.test(txt)) break;
        await sleep(2000);
      }
      notes.push(clip(txt, 160));
    }
    // wait (non-destructively) until every sampled chunk is loaded: `execute if loaded` answers Test passed / Test failed
    for (const [cx, cz] of p.chunks) {
      let ok = false;
      while (!ok && now() - t0 < waitMs) {
        try { ok = /Test passed/i.test(L.stripColors((await rcon.command(`execute in ${p.dimension} if loaded ${cx * 16 + 8} ${p.yMin} ${cz * 16 + 8}`, rconMs)).text)); } catch { ok = false; }
        if (!ok) await sleep(1000);
      }
      if (!ok) notes.push(`chunk ${cx},${cz} not loaded after ${Math.round((now() - t0) / 1000)} s`);
    }
    for (const f of cmds.fills) {
      let reply = null;
      for (;;) {
        try { reply = L.parseFill((await rcon.command(f.command, rconMs)).text); }
        catch (e) { reply = { kind: "error", text: `${clip(e.message, 120)} (not retried: the fill may have run)` }; break; }
        if (!(reply.kind === "unloaded" || (reply.kind === "error" && didNotRun(reply.text))) || now() - t0 > waitMs) break;
        await sleep(1000);
      }
      slices.push({ chunk: f.chunk, block: f.block, reply });
      if (reply.kind !== "count") break;
    }
    for (const c of cmds.unloads) { try { await rcon.command(c, rconMs); } catch { /* best effort */ } }
    const j = L.judgeProbe(p, slices);
    if (j.status !== "pass") { if (j.status === "fail") anyFail = true; else allMeasured = false; }
    res.probes.push({ ...j, feature: p.feature, dimension: p.dimension, blocks: p.blocks, chunks: p.chunks, ms: now() - t0, notes: notes.slice(0, 8) });
    chk.evidence.push(j.line);
  }
  chk.status = anyFail ? "fail" : allMeasured ? "pass" : "not_run";
}

