718 components/cyrus/designers/ItemDesigner.tsx

const secs = (t: number) => `${+(t / 20).toFixed(2)} s`;

// ------------------------------------------------------------------------------------------------- vocabulary
const TRIG: Record<string, [string, string]> = {
  right_click: ["Right-click", "Right-click with the item."], left_click_hit_entity: ["On hit", "Left-click hits an entity."], sneak_right_click: ["Sneak + right-click", "Right-click while sneaking."],
  kill_entity: ["On kill", "You kill an entity."], projectile_hit: ["Projectile hit", "This item's projectile hits something."], held_interval: ["While held", "Runs on a timer while held."],
  join: ["On join", "When you join with the item."], death: ["On death", "When you die with the item."], item_consume: ["On consume", "Eat or drink the item."], charge_release: ["Charge and release", "Hold sneak, then right-click."],
};
const ACT: Record<string, { label: string; ic: string; sum: (a: Action) => string }> = {
  damage: { label: "Damage", ic: "sword", sum: (a) => `the ${("target" in a && a.target) || "target"}` },
  heal: { label: "Heal", ic: "heart", sum: (a) => `the ${("target" in a && a.target) || "self"}` },
  potion_effect: { label: "Effect", ic: "flask", sum: (a) => (a.type === "potion_effect" ? `${a.effect} on the ${a.target ?? "self"}` : "") },
  knockback: { label: "Knockback", ic: "target", sum: (a) => `the ${("target" in a && a.target) || "target"}` },
  pull_to: { label: "Pull", ic: "target", sum: (a) => (a.type === "pull_to" ? `to the ${a.to === "point" ? "aim point" : "player"}` : "") },
  push_from: { label: "Push", ic: "target", sum: (a) => (a.type === "push_from" ? `away from the ${a.from === "point" ? "aim point" : "player"}` : "") },
  teleport_short: { label: "Blink", ic: "arrowR", sum: () => "you, along your look" },
  launch_projectile: { label: "Launch", ic: "target", sum: (a) => (a.type === "launch_projectile" ? `a ${a.kind.replace("_", " ")}` : "") },
  spawn_particles: { label: "Particles", ic: "sparkle", sum: (a) => (a.type === "spawn_particles" ? `at the ${a.at === "point" ? "point" : a.at ?? "self"}` : "") },
  play_sound: { label: "Sound", ic: "volume", sum: (a) => (a.type === "play_sound" ? `at the ${a.at === "point" ? "aim point" : a.at ?? "self"}` : "") },
  send_message: { label: "Message", ic: "note", sum: (a) => (a.type === "send_message" ? `“${a.text}”` : "") },
  title: { label: "Title", ic: "note", sum: (a) => (a.type === "title" ? `“${a.title}”` : "") },
  actionbar: { label: "Action bar", ic: "note", sum: (a) => (a.type === "actionbar" ? `“${a.text}”` : "") },
  give_item: { label: "Give", ic: "gift", sum: (a) => (a.type === "give_item" ? bare(a.item) : "") },
  set_cooldown: { label: "Set cooldown", ic: "clock", sum: (a) => (a.type === "set_cooldown" ? `of ${a.ability ?? "this ability"}` : "") },
  consume_charge: { label: "Spend charge", ic: "coin", sum: (a) => (a.type === "consume_charge" ? `of ${a.ability ?? "this ability"}` : "") },
  apply_mark: { label: "Apply mark", ic: "flag", sum: (a) => (a.type === "apply_mark" ? `mark the target "${a.mark}"` : "") },
  query_marked: { label: "For each marked", ic: "loopq", sum: (a) => (a.type === "query_marked" ? `each "${a.mark}" target near ${a.around === "point" ? "the point" : "you"}` : "") },
  query_nearby: { label: "For each nearby", ic: "loopq", sum: (a) => (a.type === "query_nearby" ? `each ${(a.kinds ?? ["living"]).join("/")} near ${a.around === "point" ? "the point" : "you"}` : "") },
  delayed: { label: "Later", ic: "clock", sum: () => "then run" },
  branch: { label: "If", ic: "branch", sum: (a) => (a.type === "branch" ? a.if.map(condText).join(" and ") : "") },
};
function condText(c: Condition): string {
  const n = c.negate ? "not " : "";
  switch (c.type) {
    case "cooldown_ready": return `${n}cooldown of ${c.ability ?? "this"} ready`;
    case "has_permission": return `${n}has permission ${c.node}`;
    case "target_is": return `target is ${n}${[...(c.kinds ?? []), ...(c.types ?? []).map(bare)].join(" or ")}`;
    case "world_in": return `${n}in ${c.worlds.join(", ")}`;
    case "health_below": return `${c.subject} health ${n}below ${Math.round(c.fraction * 100)}%`;
