/** The config path of a graph node's field ("items.void_reaper.abilities.void_pull.a0.n1.count"). */
export const nodeParamPath = (item: string, ability: string, node: string, field: string) =>
  node === "trigger" ? `items.${item}.abilities.${ability}.trigger.${snakeKey(field)}` : node === "ability" ? `items.${item}.abilities.${ability}.${snakeKey(field)}` : `items.${item}.abilities.${ability}.${node}.${snakeKey(field)}`;

// ---------------------------------------------------------------------------------------------- structural edits
/** The children lists a container action has (query/delayed: n, branch: then/else). */
export const childLists = (a: Action): { key: "actions" | "then" | "else"; seg: "n" | "then" | "else"; list: Action[] }[] =>
  a.type === "query_marked" || a.type === "query_nearby" || a.type === "delayed" ? [{ key: "actions", seg: "n", list: a.actions }]
    : a.type === "branch" ? [{ key: "then", seg: "then", list: a.then }, ...(a.else ? [{ key: "else" as const, seg: "else" as const, list: a.else }] : [])] : [];

/** A list inside an ability addressed by a container path ("" = the top list, "a0" = a0's children, "a2.then" / "a2.else"). */
function listAt(ab: Ability, container: string): Action[] | null {
  if (!container) return ab.actions;
  const segs = container.split(".");
  const last = segs[segs.length - 1];
  const which = last === "then" || last === "else" ? last : "n";
  const nodeSegs = which === "n" ? segs : segs.slice(0, -1);
  const node = nodeAt(ab as unknown as Obj, nodeSegs) as unknown as Action | null;
  if (!node) return null;
  if (which === "n") return node.type === "query_marked" || node.type === "query_nearby" || node.type === "delayed" ? node.actions : null;
  if (node.type !== "branch") return null;
  if (which === "then") return node.then;
  node.else ??= [];
  return node.else;
}

