/** Insert an action into an ability's list (container path as in listAt). New file list or an error. */
export function insertAction(files: readonly DesignFile[], item: string, ability: string, container: string, action: Action): { ok: true; files: DesignFile[]; path: string } | { ok: false; error: string } {
  const i = files.findIndex((f) => f.id === item && isItem(f));
  if (i < 0) return { ok: false, error: `no item ${item}` };
  const d = clone(files[i]) as ItemDesign;
  const ab = d.abilities.find((a) => a.id === ability);
  if (!ab) return { ok: false, error: `no ability ${ability}` };
  const list = listAt(ab, container);
  if (!list) return { ok: false, error: `${container} holds no actions` };
  list.push(action);
  const out = [...files]; out[i] = d;
  const idx = list.length - 1;
  const path = !container ? `a${idx}` : container.endsWith(".then") || container.endsWith(".else") ? `${container}${idx}` : `${container}.n${idx}`;
  return { ok: true, files: out, path };

