// simulators do not model physics, ray tracing, protection plugins or the client, and the result says so.
import { DesignSimulator, type SimEntity, type SimEvent, type SimLog, type Vec } from "../simulate";
import { GameplaySimulator, type ProgressEntry } from "../gameplay/simulate";
import { objectiveTarget, questSteps, type MenuDesign, type QuestDesign } from "../gameplay/spec";
import type { ItemDesign, TriggerType } from "../spec";
import { fileKind, type DesignFile } from "./edit";
import { BossFight, type FightEvent } from "../boss/simulate";
import type { BossDesign } from "../boss/spec";

// ------------------------------------------------------------------------------------------------------ items
export type ItemStep =
  | { k: "hit"; who: "hostile" | "animal" } | { k: "kill" } | { k: "click" } | { k: "sneak_click" }
  | { k: "charge"; ticks: number } | { k: "wait"; ticks: number } | { k: "consume" } | { k: "projectile" } | { k: "join" } | { k: "die" };
export type SimButton = { label: string; step: ItemStep; icon: string };
export type TimelineBar = { lane: string; from: number; to: number; tone: "accent" | "warn" };
export type ItemSimResult = { end: number; log: { tick: number; text: string; tone: "fired" | "blocked" | "fx" | "note" }[]; bars: TimelineBar[]; dots: { tick: number; tone: "fired" | "blocked" }[]; lanes: string[]; marks: { tick: number; count: number }[]; markCap: number | null; notes: string[] };

/** The sample world: you at the origin looking +x, four hostiles and a cow at fixed distances (blocks). */
export const SAMPLE_MOBS: { id: string; type: string; kind: SimEntity["kind"]; d: number }[] = [
  { id: "zombie#1", type: "minecraft:zombie", kind: "hostile", d: 6.5 }, { id: "zombie#2", type: "minecraft:zombie", kind: "hostile", d: 9.2 },
  { id: "skeleton#1", type: "minecraft:skeleton", kind: "hostile", d: 12.8 }, { id: "husk#1", type: "minecraft:husk", kind: "hostile", d: 18.4 },
  { id: "cow#1", type: "minecraft:cow", kind: "animal", d: 4 },
];
export const MAX_SIM_STEPS = 40;

/** The buttons the Simulator offers for this item (from its triggers). */
export function itemButtons(d: ItemDesign): SimButton[] {
  const t = new Set<TriggerType>(d.abilities.map((a) => a.trigger.type));
  const out: SimButton[] = [];
  if (t.has("left_click_hit_entity")) out.push({ label: "Hit next mob", step: { k: "hit", who: "hostile" }, icon: "sword" }, { label: "Hit a cow", step: { k: "hit", who: "animal" }, icon: "sword" });
  if (t.has("kill_entity")) out.push({ label: "Kill next mob", step: { k: "kill" }, icon: "sword" });
  if (t.has("right_click")) out.push({ label: "Right-click", step: { k: "click" }, icon: "hand" });
  if (t.has("sneak_right_click")) out.push({ label: "Sneak + right-click", step: { k: "sneak_click" }, icon: "hand" });
  const ch = d.abilities.find((a) => a.trigger.type === "charge_release");
  if (ch && ch.trigger.type === "charge_release") {
    const full = Math.min(400, Math.max(ch.trigger.minChargeTicks, Math.round(ch.trigger.maxChargeTicks * 2 / 3 / 10) * 10 || ch.trigger.minChargeTicks));
    const short = Math.max(1, Math.floor(ch.trigger.minChargeTicks / 2));
    out.push({ label: `Charge ${+(full / 20).toFixed(1)} s + release`, step: { k: "charge", ticks: full }, icon: "bolt" }, { label: `Release at ${+(short / 20).toFixed(2)} s`, step: { k: "charge", ticks: short }, icon: "bolt" });
  }
  if (t.has("projectile_hit")) out.push({ label: "Projectile hits next mob", step: { k: "projectile" }, icon: "target" });
  if (t.has("item_consume")) out.push({ label: "Consume", step: { k: "consume" }, icon: "hand" });
  if (t.has("join")) out.push({ label: "Join", step: { k: "join" }, icon: "user" });
  if (t.has("death")) out.push({ label: "Die", step: { k: "die" }, icon: "heart" });
  out.push({ label: t.has("held_interval") ? "Hold +5 s" : "+2 s", step: { k: "wait", ticks: t.has("held_interval") ? 100 : 40 }, icon: "clock" });
  return out;
}

const fmt = (n: unknown) => (typeof n === "number" ? +n.toFixed(2) : String(n));
function line(l: SimLog, ns: string): { text: string; tone: ItemSimResult["log"][number]["tone"] } | null {
  const ab = l.ability.split(".").pop() ?? l.ability;
  const d = (l.detail ?? {}) as Record<string, unknown>;
  const key = (s: unknown) => String(s ?? "").replace(`${ns}:`, "");
  switch (l.kind) {
    case "fired": return { text: `${ab} fired${d.target ? ` → ${d.target}` : ""}${typeof d.charge === "number" && d.charge > 0 ? ` · charge ${fmt(d.charge)}` : ""}`, tone: "fired" };
    case "blocked": return { text: `${ab} blocked · ${String(d.by ?? "")}${d.held !== undefined ? ` (held ${d.held} ticks)` : ""}`, tone: "blocked" };
    case "feedback": return { text: `feedback “${String(d.text ?? "")}”`, tone: "blocked" };
    case "mark": return { text: `mark ${String(d.mark)} → ${l.subject}`, tone: "fx" };
    case "particles": return { text: `particles ${String(d.particle)} ×${d.count}`, tone: "fx" };
    case "sound": return { text: `sound ${key(d.key)} · vol ${fmt(d.volume)} · pitch ${fmt(d.pitch)}`, tone: "fx" };
    case "pull_to": case "push_from": case "knockback": return { text: `${l.kind} ${l.subject} · velocity ${(d.velocity as number[] | undefined)?.map(fmt).join(", ") ?? ""}`, tone: "fx" };
    case "damage": return { text: `damage ${l.subject} · ${fmt(d.amount)}`, tone: "fx" };
    case "heal": return { text: `heal ${l.subject} · ${fmt(d.amount)}`, tone: "fx" };
    case "potion": return { text: `potion ${String(d.effect)} on ${l.subject} · ${d.ticks} ticks`, tone: "fx" };
    case "actionbar": case "send_message": case "title": return { text: `${l.kind} “${String(d.text ?? "")}”`, tone: "fx" };
    case "query_marked": case "query_nearby": return { text: `${l.kind} found ${((d.found as string[]) ?? []).length ? (d.found as string[]).join(", ") : "nothing"}`, tone: "fx" };
    case "launch": return { text: `launch ${String(d.kind)} · speed ${fmt(d.speed)}`, tone: "fx" };
    case "teleport": return { text: `teleport up to ${fmt(d.range)} blocks`, tone: "fx" };
    case "give": return { text: `give ${String(d.item)} ×${d.count}`, tone: "fx" };
    case "branch": return { text: `branch took ${String(d.taken)}`, tone: "fx" };
    case "budget_exhausted": return { text: `budget exhausted at ${String(d.at ?? "")}: the rest of this activation is skipped`, tone: "blocked" };
    case "died": return { text: `${l.subject} died`, tone: "fx" };
    case "delayed_run": return { text: `delayed step runs`, tone: "fx" };
    default: return { text: `${l.kind}${l.subject ? ` ${l.subject}` : ""}`, tone: "fx" };
  }
}

export function simulateItem(files: readonly DesignFile[], itemId: string, steps: readonly ItemStep[], namespace: string): ItemSimResult {
  const items = files.filter((f) => fileKind(f) === "item") as ItemDesign[];
  const d = items.find((x) => x.id === itemId);
  if (!d) throw new Error(`no item ${itemId}`);
  const s = new DesignSimulator(items, { namespace });
  const perms = (d.permissions ?? []).map((p) => `${namespace}.${p.node}`);
  s.add({ id: "you", type: "minecraft:player", kind: "player", pos: [0, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true, mainHand: d.id, inventory: [d.id], permissions: perms });
  for (const m of SAMPLE_MOBS) s.add({ id: m.id, type: m.type, kind: m.kind, pos: [m.d, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true });
  const markDefs = d.marks ?? [];
  const markCount = () => markDefs.reduce((n, m) => n + s.marked("you", `${d.id}.${m.name}`, [0, 64, 0], 64, 64).length, 0);
  const marks: { tick: number; count: number }[] = [{ tick: 0, count: 0 }];
  const bars: TimelineBar[] = [];
  let t = 0, hitIdx = 0;
  const nextHostile = () => { const alive = SAMPLE_MOBS.filter((m) => m.kind === "hostile" && s.entities.get(m.id)?.alive); return alive.length ? alive[hitIdx++ % alive.length] : null; };
  const look = (): { target?: string; point: Vec } => { const m = SAMPLE_MOBS.find((x) => x.kind === "hostile" && s.entities.get(x.id)?.alive); return m ? { target: m.id, point: [m.d, 64, 0] } : { point: [12, 64, 0] }; };
  const ev = (e: SimEvent) => s.event(e);
  for (const st of steps.slice(0, MAX_SIM_STEPS)) {
    switch (st.k) {
      case "hit": { t += 14; const m = st.who === "animal" ? SAMPLE_MOBS.find((x) => x.kind === "animal")! : nextHostile(); if (m) ev({ tick: t, type: "hit", player: "you", target: m.id }); else s.notes.push("no hostile left to hit"); break; }
      case "kill": { t += 14; const m = nextHostile(); if (m) ev({ tick: t, type: "kill", player: "you", target: m.id }); break; }
      case "click": t += 10; ev({ tick: t, type: "right_click", player: "you", look: look() }); break;
      case "sneak_click": t += 10; ev({ tick: t, type: "sneak_start", player: "you" }); ev({ tick: t + 1, type: "right_click", player: "you", look: look() }); ev({ tick: t + 2, type: "sneak_stop", player: "you" }); t += 2; break;
      case "charge": {
        const held = Math.max(1, Math.min(400, Math.round(st.ticks)));
        t += 4; ev({ tick: t, type: "sneak_start", player: "you" }); bars.push({ lane: "Charge", from: t, to: t + held, tone: "accent" });
        const rel = d.abilities.find((a) => a.trigger.type === "charge_release");
        const byClick = rel?.trigger.type === "charge_release" && rel.trigger.release === "right_click";
        if (byClick) { ev({ tick: t + held, type: "right_click", player: "you", look: look() }); ev({ tick: t + held + 1, type: "sneak_stop", player: "you" }); t += held + 1; }
        else { ev({ tick: t + held, type: "sneak_stop", player: "you", look: look() }); t += held; }
        break;
      }
      case "wait": t += Math.max(1, Math.min(2400, Math.round(st.ticks))); ev({ tick: t, type: "advance" }); s.log.push({ tick: t, ability: "-", kind: "waited", detail: { ticks: st.ticks } }); break;
      case "consume": t += 32; ev({ tick: t, type: "consume", player: "you" }); break;
      case "projectile": { t += 6; const tag = d.abilities.find((a) => a.trigger.type === "projectile_hit")?.trigger; const m = nextHostile(); if (tag?.type === "projectile_hit") ev({ tick: t, type: "projectile_hit", player: "you", tag: tag.tag, item: d.id, target: m?.id, point: m ? [m.d, 64, 0] : [12, 64, 0] }); break; }
      case "join": t += 10; ev({ tick: t, type: "join", player: "you" }); break;
      case "die": t += 10; ev({ tick: t, type: "death", player: "you" }); break;
    }
    marks.push({ tick: t, count: markCount() });
  }
  const withCd = d.abilities.filter((a) => a.cooldownTicks && !a.manualCooldown).length;
  // cooldown bars from the fired log + the ability's cooldown parameter as the simulator read it
  for (const l of s.log) {
    if (l.kind !== "fired") continue;
    const ab = d.abilities.find((a) => `${d.id}.${a.id}` === l.ability);
    if (!ab?.cooldownTicks || ab.manualCooldown) continue;
    const cd = Number(s.value(`items.${d.id}.abilities.${ab.id}.cooldown_ticks`));
    if (cd > 0) bars.push({ lane: withCd > 1 ? `${ab.name}` : "Cooldown", from: l.tick, to: l.tick + cd, tone: "warn" });
  }
  const log = s.log.flatMap((l) => (l.kind === "waited" ? [{ tick: l.tick, text: `waited ${+(Number((l.detail as { ticks: number }).ticks) / 20).toFixed(2)} s`, tone: "note" as const }] : (() => { const x = line(l, namespace); return x ? [{ tick: l.tick, ...x }] : []; })()));
  const lanes = [...new Set(["Charge", ...bars.map((b) => b.lane)])].filter((l) => l !== "Charge" || d.abilities.some((a) => a.trigger.type === "charge_release"));
  return {
    end: t, log, bars, lanes, marks, markCap: markDefs.length ? markDefs.reduce((n, m) => n + Number(s.value(`items.${d.id}.marks.${m.name}.max_per_owner`)), 0) : null,
    dots: s.log.filter((l) => l.kind === "fired" || l.kind === "blocked").map((l) => ({ tick: l.tick, tone: l.kind as "fired" | "blocked" })),
    notes: [...new Set(s.notes)].slice(0, 6),
  };
}

// --------------------------------------------------------------------------------------------- menus (Try it)
export type SamplePlayer = { currency: Record<string, number>; levels: number; vault: boolean; freeSlots: number; perms: boolean };
export const SAMPLE_PLAYER: SamplePlayer = { currency: { "minecraft:emerald": 9 }, levels: 7, vault: false, freeSlots: 6, perms: true };

