// Cyrus designer WEAPON components (2026-10-12, universal-modder finding 5): hitscan, beam and area_blast for the item /
// ability designer. FIXED Java like the rest of the component library (./java.ts), added to a mod ONLY when one of its
// designs uses a weapon action (like ModelStates), so every existing designer mod keeps its byte-identical sources and
// golden hashes. Every Paper API it calls was checked with javap on paper-api 1.21.1 / 1.21.4 / 1.21.8 / 1.21.11 and
// 26.2 (2026-10-12): World.rayTrace(Location, Vector, double, FluidCollisionMode, boolean, double, Predicate<Entity>),
// World.rayTraceBlocks(Location, Vector, double, FluidCollisionMode, boolean), RayTraceResult.getHitEntity /
// getHitPosition, LivingEntity.setNoDamageTicks(int) / getEyeLocation, Damageable.damage(double, Entity) (via Effects),
// World.spawnParticle(Particle, Location, int, double, double, double, double), Vector.getCrossProduct.
//
// Mechanics that bite (field notes, second hand, kept because they are vanilla rules the API cannot hide):
//   - a shotgun's pellets must be SUMMED per target and dealt as one hit, and the target's hurt-invulnerability reset
//     (setNoDamageTicks(0)), or vanilla's 10-tick invulnerability swallows most pellets / the next shots;
//   - a ray stops at the first block (World.rayTrace returns the nearer of the block and the entity hit);
//   - FULL-AUTO is not possible server-side: the client only repeats a held right-click every 4 ticks (5 shots/s) and
//     sends no "button held" state, so the fastest server-side fire rate is that repeat. Real full-auto needs a client
//     mod sending its own fire packets (the client-mod lane). The validator therefore requires cooldownTicks >= 4 for a
//     weapon on a click trigger (spec.ts WEAPON_LIMITS.minClickCooldown).
// Lag-bomb proof: rays and line-of-sight checks spend the activation's ACTION budget (64), particles its particle budget
// (512), hits its ENTITY budget (32); fixed caps below; a beam is a chain of single delayed steps (no timer), one live beam
// per player and at most LIVE_BEAMS plugin-wide. Nothing here changes a block (no explosion is ever created).
import { WEAPON_LIMITS } from "../spec";

export const WEAPONS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.bukkit.FluidCollisionMode;
import org.bukkit.Location;
import org.bukkit.Particle;
import org.bukkit.World;
import org.bukkit.entity.ArmorStand;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.util.RayTraceResult;
import org.bukkit.util.Vector;

/**
 * Component designer-weapons v1: hitscan, beam and area_blast. Rays and line-of-sight checks spend the activation's
 * action budget, particles its particle budget, hits its entity budget (Budget), so config.yml cannot turn them into a
 * lag bomb. Never changes blocks; damage goes through Bukkit's damage events with the player as the source (PvP and
 * protection plugins apply). Full-auto beyond vanilla's 4-tick right-click repeat is not possible server-side.
 */
public final class Weapons {
    public static final int MAX_PELLETS = 12;
    public static final int TRACER_POINTS = ${WEAPON_LIMITS.tracerPoints};
    public static final int BEAM_POINTS = ${WEAPON_LIMITS.beamPoints};
    public static final int BEAM_PULSES = ${WEAPON_LIMITS.beamPulses};
    public static final int LIVE_BEAMS = ${WEAPON_LIMITS.liveBeams};
    public static final int BLAST_MAX = 16;
    public static final int BLAST_PARTICLES = ${WEAPON_LIMITS.blastParticles};
    private static final double RAY_SIZE = ${WEAPON_LIMITS.raySize};
    /** player -> serial of the live beam (a new beam replaces the old one; at most LIVE_BEAMS players at once). */
    private static final Map<UUID, Integer> BEAMS = new HashMap<>();
    private static int serial;

    private Weapons() {}

    private static boolean foe(Entity e, Player p, boolean players) {
        return e != p && e instanceof LivingEntity le && !(e instanceof ArmorStand) && e.isValid() && !le.isDead() && (players || !(e instanceof Player));
    }

    /** Pellet i of n in a cone of spreadDeg degrees: a FIXED sunflower pattern (one pellet = dead centre), the same maths as the TS simulator. */
    public static Vector pelletDir(Vector look, int i, int n, double spreadDeg) {
        Vector d = look.clone().normalize();
        if (n <= 1 || spreadDeg <= 0) return d;
        double r = Math.toRadians(spreadDeg) * Math.sqrt((i + 0.5) / n);
        double th = i * 2.399963229728653;
        Vector up = Math.abs(d.getY()) > 0.999 ? new Vector(1, 0, 0) : new Vector(0, 1, 0);
        Vector right = d.getCrossProduct(up).normalize();
        Vector up2 = right.getCrossProduct(d).normalize();
        double t = Math.tan(r);
        return d.add(right.multiply(t * Math.cos(th))).add(up2.multiply(t * Math.sin(th))).normalize();
    }

    /** Particle points along a ray (at most maxPoints, two per block), from the particle budget. */
    private static void line(Activation a, World w, Location from, Vector dir, double dist, Particle type, int maxPoints) {
        int want = (int) Math.min(maxPoints, Math.max(1, Math.ceil(dist * 2)));
        int n = a.budget().particles(want);
        if (n <= 0) return;
        Vector step = dir.clone().normalize().multiply(dist / want);
        Location at = from.clone();
        for (int k = 0; k < n; k++) { at.add(step); w.spawnParticle(type, at, 1, 0, 0, 0, 0); }
    }

    /**
     * Instant shot: each pellet's ray (one action each) stops at the first block or entity within range; damage per pellet
     * is SUMMED per target and dealt ONCE per target (one damage event, one entity of the budget), after resetting the
     * target's hurt-invulnerability when asked. Returns the targets hit (first hit first) for the per-target actions.
     */
    public static List<LivingEntity> hitscan(Designer d, Activation a, double range, double damage, int pellets, double spreadDeg, boolean resetInvulnerability, boolean players, Particle tracer) {
        Player p = a.player();
        Location eye = p.getEyeLocation();
        World w = p.getWorld();
        Vector look = eye.getDirection();
        int n = Math.max(1, Math.min(MAX_PELLETS, pellets));
        Map<LivingEntity, Double> sum = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            if (!a.budget().action()) break;
            Vector dir = pelletDir(look, i, n, spreadDeg);
            RayTraceResult r = w.rayTrace(eye, dir, range, FluidCollisionMode.NEVER, true, RAY_SIZE, e -> foe(e, p, players));
            double dist = r == null ? range : r.getHitPosition().distance(eye.toVector());
            if (tracer != null) line(a, w, eye, dir, dist, tracer, TRACER_POINTS);
            if (r != null && r.getHitEntity() instanceof LivingEntity t) sum.merge(t, damage, Double::sum);
        }
        List<LivingEntity> hit = new ArrayList<>();
        for (Map.Entry<LivingEntity, Double> e : sum.entrySet()) {
            LivingEntity t = e.getKey();
            if (!t.isValid() || t.isDead()) continue;
            if (resetInvulnerability) t.setNoDamageTicks(0);
            d.effects().damage(a, t, e.getValue());
            hit.add(t);
        }
        return hit;
    }

    /**
     * Continuous beam that follows the aim: every intervalTicks (>= 2) for durationTicks (at most BEAM_PULSES pulses), a
     * ray from the player's CURRENT eye along the CURRENT look; the FIRST entity on it takes damage (one action + one
     * entity per pulse), a particle line shows it. One live beam per player (a new beam replaces the old), at most
     * LIVE_BEAMS plugin-wide; it ends when the player leaves or dies, stops holding this item, or the budget runs out.
     */
    public static boolean beam(Designer d, Activation a, double range, double damage, long durationTicks, long intervalTicks, boolean resetInvulnerability, boolean players, Particle particle) {
        UUID id = a.player().getUniqueId();
        if (!BEAMS.containsKey(id) && BEAMS.size() >= LIVE_BEAMS) return false;
        if (!a.budget().task()) return false;
        int mine = ++serial;
        BEAMS.put(id, mine);
        long interval = Math.max(2L, intervalTicks);
        int pulses = (int) Math.max(1L, Math.min(BEAM_PULSES, durationTicks / interval));
        pulse(d, a, a.ability().itemId(), id, mine, range, damage, interval, pulses, resetInvulnerability, players, particle);
        return true;
    }

    private static void pulse(Designer d, Activation a, String item, UUID id, int mine, double range, double damage, long interval, int left, boolean reset, boolean players, Particle particle) {
        Integer cur = BEAMS.get(id);
        if (cur == null || cur.intValue() != mine) return;
        Player p = a.player();
        if (left <= 0 || !p.isOnline() || p.isDead() || !d.identity().is(p.getInventory().getItemInMainHand(), item) || !a.budget().action()) { BEAMS.remove(id, mine); return; }
        Location eye = p.getEyeLocation();
        Vector dir = eye.getDirection();
        RayTraceResult r = p.getWorld().rayTrace(eye, dir, range, FluidCollisionMode.NEVER, true, RAY_SIZE, e -> foe(e, p, players));
        double dist = r == null ? range : r.getHitPosition().distance(eye.toVector());
        if (particle != null) line(a, p.getWorld(), eye, dir, dist, particle, BEAM_POINTS);
        if (r != null && r.getHitEntity() instanceof LivingEntity t) { if (reset) t.setNoDamageTicks(0); d.effects().damage(a, t, damage); }
        if (left <= 1 || !d.tasks().later(interval, () -> pulse(d, a, item, id, mine, range, damage, interval, left - 1, reset, players, particle))) BEAMS.remove(id, mine);
    }

    /**
     * Radius damage around center with LINEAR falloff (full at the centre, none at the edge; distance to the target's
     * middle), nearest first, at most max targets; players take playerScale of it (0 = never), the user is never hit;
     * optional knockback away from the centre with the same falloff; line of sight from the centre to the target's eyes
     * (one action each) when asked. Creates no explosion and changes no block.
     */
    public static List<LivingEntity> areaBlast(Designer d, Activation a, Location center, double radius, double damage, double playerScale, int max, double knockback, boolean lineOfSight, Particle particle) {
        List<LivingEntity> hit = new ArrayList<>();
        if (center == null || center.getWorld() == null) return hit;
        World w = center.getWorld();
        if (particle != null) { int n = a.budget().particles(BLAST_PARTICLES); if (n > 0) w.spawnParticle(particle, center, n, radius / 3, radius / 3, radius / 3, 0); }
        for (LivingEntity t : Targets.nearby(a.player(), center, radius, Math.max(1, Math.min(BLAST_MAX, max)), 0, null, true)) {
            boolean player = t instanceof Player;
            if (player && playerScale <= 0) continue;
            double f = Math.max(0, 1 - t.getLocation().add(0, t.getHeight() / 2, 0).distance(center) / radius);
            if (f <= 0) continue;
            if (lineOfSight) {
                if (!a.budget().action()) break;
                Vector to = t.getEyeLocation().toVector().subtract(center.toVector());
                double len = to.length();
                if (len > 0.01 && w.rayTraceBlocks(center, to, len, FluidCollisionMode.NEVER, true) != null) continue;
            }
            d.effects().damage(a, t, damage * f * (player ? playerScale : 1.0));
            if (knockback > 0) d.effects().pushFrom(a, t, center, knockback * f, 0.2 + 0.3 * f);
            hit.add(t);
        }
        return hit;
    }
}
`;

