import { WEAPONS_JAVA, WEAPONS_META } from "./components/weapons";''')
s=s.replace('''  CAPS, CONSUMABLE_BASES, DESIGN_SPEC_VERSION, RUNTIME_CAPS, validateDesigns, walkActions,''','''  CAPS, CONSUMABLE_BASES, DESIGN_SPEC_VERSION, RUNTIME_CAPS, WEAPON_DEFAULTS, validateDesigns, walkActions,''')
s=s.replace('''      case "launch_projectile": addParam(s, `${p}.speed`, "num", "projectileSpeed", a.speed, `${a.kind} speed`, "speed"); addParam(s, `${p}.lifetime_ticks`, "ticks", "projectileLifetime", a.lifetimeTicks ?? DEFAULTS.lifetimeTicks, `${a.kind} lifetime (ticks)`, "duration"); break;''','''      case "launch_projectile": addParam(s, `${p}.speed`, "num", "projectileSpeed", a.speed, `${a.kind} speed`, "speed"); addParam(s, `${p}.lifetime_ticks`, "ticks", "projectileLifetime", a.lifetimeTicks ?? DEFAULTS.lifetimeTicks, `${a.kind} lifetime (ticks)`, "duration"); break;
      case "hitscan":
        addParam(s, `${p}.range`, "num", "hitscanRange", a.range, "shot range (blocks)", "range"); addParam(s, `${p}.damage`, "num", "damage", a.damage, "damage per pellet (health points)", "damage");
        addParam(s, `${p}.pellets`, "int", "pellets", a.pellets ?? WEAPON_DEFAULTS.pellets, "pellets per shot", "count"); addParam(s, `${p}.spread`, "num", "spreadDegrees", a.spread ?? WEAPON_DEFAULTS.spread, "spread (degrees)", "other"); break;
      case "beam":
        addParam(s, `${p}.range`, "num", "beamRange", a.range, "beam range (blocks)", "range"); addParam(s, `${p}.damage`, "num", "damage", a.damage, "damage per pulse (health points)", "damage");
        addParam(s, `${p}.duration_ticks`, "ticks", "beamDurationTicks", a.durationTicks, "beam duration (ticks)", "duration"); addParam(s, `${p}.interval_ticks`, "ticks", "beamIntervalTicks", a.intervalTicks, "ticks between pulses", "duration"); break;
      case "area_blast":
        addParam(s, `${p}.radius`, "num", "blastRadius", a.radius, "blast radius (blocks)", "radius"); addParam(s, `${p}.damage`, "num", "damage", a.damage, "damage at the centre (health points)", "damage");
        addParam(s, `${p}.player_scale`, "num", "playerScale", a.playerScale ?? WEAPON_DEFAULTS.playerScale, "share of the damage players take (0-1)", "other"); addParam(s, `${p}.max`, "int", "blastMax", a.max ?? WEAPON_DEFAULTS.blastMax, "max targets", "count");
        if (a.knockback !== undefined) addParam(s, `${p}.knockback`, "num", "strength", a.knockback, "blast knockback strength", "strength");
        break;''')
s=s.replace('''      case "launch_projectile": o.push(ind, `d.effects().launch(${A}, ${jstr(a.kind)}, ${P(g, `${rel}.speed`)}, ${a.tag ? jstr(a.tag) : "null"}, ${P(g, `${rel}.lifetime_ticks`)});`); break;''','''      case "launch_projectile": o.push(ind, `d.effects().launch(${A}, ${jstr(a.kind)}, ${P(g, `${rel}.speed`)}, ${a.tag ? jstr(a.tag) : "null"}, ${P(g, `${rel}.lifetime_ticks`)});`); break;
      case "hitscan": {
        g.weapons = true;
        const call = `Weapons.hitscan(d, ${A}, ${P(g, `${rel}.range`)}, ${P(g, `${rel}.damage`)}, ${P(g, `${rel}.pellets`)}, ${P(g, `${rel}.spread`)}, ${a.resetInvulnerability ?? true}, ${a.players ?? true}, ${a.tracer ? `Particle.${a.tracer.toUpperCase()}` : "null"})`;
        if (!a.actions?.length) { o.push(ind, `${call};`); break; }
        const n = ++g.loopN;
        o.push(ind, `for (LivingEntity t${n} : ${call}) {`);
        o.push(ind + 1, `Activation a${n} = ${A}.withTarget(t${n});`);
        actions(g, o, a.actions, `${rel}.n`, `a${n}`, ind + 1);
        o.push(ind, `}`);
        break;
      }
      case "beam": g.weapons = true; o.push(ind, `Weapons.beam(d, ${A}, ${P(g, `${rel}.range`)}, ${P(g, `${rel}.damage`)}, ${P(g, `${rel}.duration_ticks`)}, ${P(g, `${rel}.interval_ticks`)}, ${a.resetInvulnerability ?? true}, ${a.players ?? true}, ${a.particle ? `Particle.${a.particle.toUpperCase()}` : "null"});`); break;
      case "area_blast": g.weapons = true; o.push(ind, `Weapons.areaBlast(d, ${A}, ${at(a.at ?? "point")}, ${P(g, `${rel}.radius`)}, ${P(g, `${rel}.damage`)}, ${P(g, `${rel}.player_scale`)}, ${P(g, `${rel}.max`)}, ${a.knockback !== undefined ? P(g, `${rel}.knockback`) : "0.0"}, ${a.lineOfSight ?? true}, ${a.particle ? `Particle.${a.particle.toUpperCase()}` : "null"});`); break;''')
s=s.replace('''type AbGen = { item: ItemDesign; ab: Ability; params: Map<string, Param>; statics: string[]; ns: string; loopN: number };''','''type AbGen = { item: ItemDesign; ab: Ability; params: Map<string, Param>; statics: string[]; ns: string; loopN: number; /** uses designer/Weapons.java (import only then: other abilities stay byte-identical) */ weapons?: boolean };''')
s=s.replace('''    `import ${pkg}.designer.Trigger;`,
    ``,
    `/** Ability "${javadocText(ab.name)}"''','''    `import ${pkg}.designer.Trigger;`,
    ...(g.weapons ? [`import ${pkg}.designer.Weapons;`] : []),
    ``,
    `/** Ability "${javadocText(ab.name)}"''')
s=s.replace('''  if (ms) add(`${dir}/designer/ModelStates.java`, renderComponent(MODEL_STATES_JAVA, pkg), "component");''','''  if (ms) add(`${dir}/designer/ModelStates.java`, renderComponent(MODEL_STATES_JAVA, pkg), "component");
  const weapons = designs.some(usesWeapons);
  if (weapons) add(`${dir}/${WEAPONS_META.file}`, renderComponent(WEAPONS_JAVA, pkg), "component");''')
s=s.replace('''  notes.push(...stateNotes(designs, fe));''','''  notes.push(...stateNotes(designs, fe));
  if (weapons) notes.push("Guns and beams fire at most every 4 ticks (5 times a second) while right-click is held: that is how often the game client repeats a held click; true full-auto needs a client mod. Shots go through damage events, so PvP settings and protection plugins apply, and they never break blocks.");''')
s=s.replace('''compiler: COMPILER_VERSION, library: COMPONENT_LIBRARY_VERSION, libraryHash: libraryHash(), designs,''','''compiler: COMPILER_VERSION, library: COMPONENT_LIBRARY_VERSION, libraryHash: weapons ? sha256(libraryHash() + sha256(WEAPONS_JAVA)) : libraryHash(), designs,''')
s=s.replace('''export const DESIGN_VERSION = DESIGN_SPEC_VERSION;''','''/** Does a design use a weapon action anywhere (then designer/Weapons.java is part of the mod)? */
export function usesWeapons(d: ItemDesign): boolean {
  let yes = false;
  for (const ab of d.abilities) walkActions(ab.actions, (a) => { if (a.type === "hitscan" || a.type === "beam" || a.type === "area_blast") yes = true; });
  return yes;
}

export const DESIGN_VERSION = DESIGN_SPEC_VERSION;''')
open(p,'w').write(s)
EOF
grep -n "g.weapons\|usesWeapons" lib/cyrus/designer/compile.ts | head

