/** Kept server dir: did the plugin write config.yml (and the backup), and what config_version is on disk. */
function harvest(runId: string | null) {
  const out: Record<string, unknown> = {};
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF, "runs", runId);
  const pd = path.join(dir, "plugins/VoidArsenal");
  out.configOnDisk = existsSync(path.join(pd, "config.yml"));
  if (out.configOnDisk) { const t = readFileSync(path.join(pd, "config.yml"), "utf8"); out.configVersionOnDisk = Number(/^config_version:\s*(\d+)/m.exec(t)?.[1] ?? NaN); out.designerValuesOnDisk = /^# designer-values: ([0-9a-f]{16})/m.exec(t)?.[1] ?? null; }
  out.backups = existsSync(pd) ? readdirSync(pd).filter((n) => n.startsWith("config.yml.bak")) : [];
  const log = path.join(dir, "logs/latest.log");
  out.pluginLog = existsSync(log) ? readFileSync(log, "utf8").split("\n").filter((l) => /VoidArsenal|voidarsenal|migrated|clamped/i.test(l) && !/Preparing/.test(l)).map((l) => l.slice(0, 300)).slice(0, 30) : [];
  // ERROR/exception lines that are ours (the sandbox's no-internet noise is ignored by Test Flight and listed apart)
  const lines = existsSync(log) ? readFileSync(log, "utf8").split("\n") : [];
  out.pluginErrorLines = lines.filter((l) => /\/(ERROR|FATAL)\]|Exception/.test(l) && /VoidArsenal|voidarsenal/.test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.sandboxNoiseLines = lines.filter((l) => /\/(ERROR|FATAL)\]/.test(l) && !/VoidArsenal|voidarsenal/.test(l)).length;
  rmSync(dir, { recursive: true, force: true }); // keepDir was only for this check
  return out;
}

