// Cyrus perf safety (5): designer + data pack/worldgen caps audited against the perf rules (lib/cyrus/safety/perf-caps.ts),
// and the caps added on 2026-10-11 (data pack tick limits, the designer click-ability floor).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { perfCapAudit, perfCapGaps } from "../lib/cyrus/safety/perf-caps";
import { checkFunctions } from "../lib/cyrus/datapack/functions";
import { ABILITY_JAVA } from "../lib/cyrus/designer/components/java";

const tick = (commands: string[]) => checkFunctions([{ id: "tick", commands, runOn: "tick" } as never], { namespace: "nx_test" } as never).findings;
const any = (commands: string[]) => checkFunctions([{ id: "f", commands } as never], { namespace: "nx_test" } as never).findings;
const rules = (f: { rule: string; severity: string }[]) => f.map((x) => `${x.severity}:${x.rule}`);

describe("perf cap audit", () => {
  it("every emitter row carries a real number or rule, no open gaps, the snapshot of the caps holds", () => {
    const rows = perfCapAudit();
    assert.deepEqual(perfCapGaps(rows), []);
    const by = (e: string, c: string) => rows.find((r) => r.emitter === e && r.cap === c)!.value;
    assert.equal(by("item designer", "entities per activation"), 32);
    assert.equal(by("item designer", "held_interval period (ticks, minimum)"), 10);
    assert.equal(by("boss designer", "live minions plugin-wide"), 48);
    assert.equal(by("data pack", "commands every tick (whole call graph)"), 64);
    assert.equal(by("data pack", "particles per command"), 1000);
    assert.equal(by("worldgen", "per-chunk cost ceiling (cost units)"), 100);
    for (const r of ["R1", "R2", "R3", "R4", "R5", "R6", "R7", "R8"]) assert.ok(rows.some((x) => x.rule === r), `rule ${r} covered`);
  });
});

describe("data pack tick limits (added 2026-10-11)", () => {
  it("an unconditional summon every tick is refused; behind a condition it is a warning", () => {
    assert.ok(rules(tick(["summon minecraft:pig ~ ~ ~"])).includes("error:tick_summon_unbounded"));
    const guarded = rules(tick(["execute if score #t nx_test matches 0 run summon minecraft:pig ~ ~ ~"]));
    assert.ok(!guarded.includes("error:tick_summon_unbounded") && guarded.includes("warn:tick_summon"));
  });
  it("particles: per command anywhere, smaller in tick functions", () => {
    assert.ok(rules(any(["particle minecraft:flame ~ ~ ~ 1 1 1 0 5000"])).includes("error:particle_count"));
    assert.ok(rules(tick(["particle minecraft:flame ~ ~ ~ 1 1 1 0 200"])).includes("error:tick_particles"));
    assert.ok(!rules(tick(["particle minecraft:flame ~ ~ ~ 1 1 1 0 8"])).some((r) => r.startsWith("error:")));
  });
  it("fill/clone: big volumes warn, any sizable fill every tick is refused, small relative fills are fine", () => {
    assert.ok(rules(any(["fill 0 0 0 63 63 63 minecraft:stone"])).includes("warn:fill_volume"));
    assert.ok(rules(tick(["fill 0 0 0 9 9 9 minecraft:stone"])).includes("error:tick_fill"));
    assert.ok(!rules(tick(["execute as @a at @s run fill ~-1 ~-1 ~-1 ~1 ~-1 ~1 minecraft:glass"])).some((r) => r.startsWith("error:")));
  });
  it("execute as @e without a filter every tick is a warning", () => {
    assert.ok(rules(tick(["execute as @e at @s run particle minecraft:flame ~ ~ ~ 0 0 0 0 1"])).includes("warn:tick_all_entities"));
    assert.ok(!rules(tick(["execute as @e[type=minecraft:zombie,limit=4] at @s run particle minecraft:flame ~ ~ ~ 0 0 0 0 1"])).includes("warn:tick_all_entities"));
  });
});

describe("designer click abilities", () => {
  it("the cooldown-0 click floor is an owner decision (golden jars stay byte-identical), recorded in the audit", () => {
    const row = perfCapAudit().find((r) => r.emitter === "item designer" && r.rule === "R6" && r.status === "owner-decision");
    assert.ok(row && /golden/.test(row.note ?? ""));
    assert.doesNotMatch(ABILITY_JAVA, /MIN_GAP_TICKS/);
  });
});

