// REAL runs of the designer WEAPON components ON node-2 (not part of the unit suite). Branch feature/cyrus-mc-testing-weapons.
//   scripts/devhost run --lock --max 1500 -- npx tsx test/cyrus-designer-weapons-real.ts [--out <json>]
// 1. javac --release 21 against the resolved Paper classpath of 1.21.1 / 1.21.4 / 1.21.8 / 1.21.11 and --release 25
//    against 26.2 (the five weapon fixtures compiled into one mod, NxArmory), -Xlint, strict safety scan (bytecode + source).
// 2. Test Flight on Paper 1.21.11 with the pinned Mineflayer bot (survival, the server's default): the bot holds each
//    weapon, faces a NoAI pig and right-clicks; the pig's health is read back over RCON. The numbers prove the mechanics:
//    T-1 hitscan 4 damage -> 6.0; T-2 four 1-damage pellets SUMMED -> 6.0 (vanilla invulnerability would leave 9.0) and a
//    second shot 5 ticks later lands too (invulnerability reset) -> 2.0; T-3 area_blast 6 at the target: the target 4.0,
//    a pig 2 blocks from the centre takes half (7.0), the user is never hit (20.0); T-4 beam 0.5 x 10 pulses -> 5.0.
// No AI model, no real Minecraft client; peaceful flat test world (pigs are passive, so they stay).
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileDesigns, type CompileOk } from "../lib/cyrus/designer/compile";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { PlaytestPlan } from "../lib/cyrus/playtest/plan";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-weapons/run-${Date.now().toString(36)}`;
const NS = "nx_r7weapon";
const PLUGIN = "NxArmory";
const CMD = "nxarmory";
const LANES = [
  { version: "1.21.1", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.1.txt` },
  { version: "1.21.4", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.4.txt` },
  { version: "1.21.8", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.8.txt` },
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const FLY = "1.21.11";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const designs = () => ["tap_pistol", "scatter_gun", "blast_rod", "ion_beam", "rocket_launcher"].map((n) => JSON.parse(readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer-weapons", `${n}.json`), "utf8")));
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

function build(r: CompileOk, lane: (typeof LANES)[number]) {
  const dir = path.join(RUN, lane.version);
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  let out = "";
  try { out = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; return { ok: false as const, error: `${x.stderr ?? ""}${x.stdout ?? ""}`.slice(0, 6000) }; }
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jarPath = path.join(dir, `${PLUGIN}-${lane.version}.jar`);
  execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", jarPath, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  let findings: { severity: string; rule: string; where: string }[] = [];
  try {
    findings = [...S.scanBytecode(classes, { profile: "strict" }), ...S.scanSource(sources.map((abs) => ({ abs, rel: path.relative(path.join(dir, "ws"), abs) })), { profile: "strict" })];
  } finally { process.env.PATH = oldPath; }
  return { ok: true as const, jarPath, jarSha256: sha(readFileSync(jarPath)), sources: sources.length, javacWarnings: (out.match(/warning: [^\n]*/g) ?? []).slice(0, 10), scanBlocks: findings.filter((f) => f.severity === "block").map((f) => `${f.rule}@${f.where}`), scanWarns: findings.filter((f) => f.severity === "warn").map((f) => `${f.rule}@${f.where}`) };
}

const pig = (x: number, z: number, tag: string) => ({ kind: "server" as const, command: `summon minecraft:pig ${x} -59 ${z} {NoAI:1b,NoGravity:1b,Silent:1b,Tags:["${tag}"]}` });
const health = (sel: string, want: string) => ({ kind: "server" as const, command: `data get entity ${sel} Health`, expect: [want] });
const setup = (item: string, mat: string) => [
  { kind: "server" as const, command: `kill @e[type=pig]` },
  { kind: "server" as const, command: `${CMD} give ${item} {bot}`, expect: [`Gave 1 x ${item} to`] },
  { kind: "hold" as const, item: `minecraft:${mat}` },
  { kind: "server" as const, command: "tp {bot} 0.5 -60 0.5 0 0", note: "face +z, pitch 0: the eye ray is at y -58.38" },
];
const PLAN: PlaytestPlan = {
  schema: 1, totalSec: 150,
  scenarios: [
    { id: "T-1", title: "hitscan: one ray, the first entity takes the damage", steps: [
      { kind: "join" }, ...setup("tap_pistol", "iron_horse_armor"), pig(0.5, 4.5, "nxt"), { kind: "wait", ms: 600 },
      { kind: "use_item" }, { kind: "wait", ms: 500 }, health("@e[type=pig,tag=nxt,limit=1]", "6.0f"),
    ] },
    { id: "T-2", title: "shotgun: pellets summed per target and the hurt-invulnerability reset", reset: false, steps: [
      ...setup("scatter_gun", "golden_horse_armor"), pig(0.5, 4.5, "nxs"), { kind: "wait", ms: 600 },
      { kind: "use_item" }, { kind: "wait", ms: 400 }, health("@e[type=pig,tag=nxs,limit=1]", "6.0f"),
      { kind: "use_item" }, { kind: "wait", ms: 400 }, health("@e[type=pig,tag=nxs,limit=1]", "2.0f"),
    ] },
    { id: "T-3", title: "area blast: linear falloff from the target, never the user", reset: false, steps: [
      ...setup("blast_rod", "diamond_horse_armor"), pig(0.5, 3.0, "nxa"), pig(2.5, 3.0, "nxb"), { kind: "wait", ms: 600 },
      { kind: "use_item" }, { kind: "wait", ms: 500 },
      health("@e[type=pig,tag=nxa,limit=1]", "4.0f"), health("@e[type=pig,tag=nxb,limit=1]", "7.0f"), health("{bot}", "20.0f"),
    ] },
    { id: "T-4", title: "beam: 10 pulses of 0.5 on the first entity while the item is held", reset: false, steps: [
      ...setup("ion_beam", "leather_horse_armor"), pig(0.5, 4.5, "nxc"), { kind: "wait", ms: 600 },
      { kind: "use_item" }, { kind: "wait", ms: 2800 }, health("@e[type=pig,tag=nxc,limit=1]", "5.0f"),
    ] },
  ],
};

(async () => {
  mkdirSync(RUN, { recursive: true });
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, aiModel: "none (fixture designs)", lanes: [] as unknown[] };
  let flyJar: { path: string; sha: string } | null = null;
  for (const lane of LANES) {
    const c = compileDesigns(designs(), { version: lane.version, namespace: NS, pluginName: PLUGIN });
    if (!c.ok) { (res.lanes as unknown[]).push({ version: lane.version, compile: c.errors }); console.log(`${lane.version}: compile refused ${JSON.stringify(c.errors).slice(0, 300)}`); continue; }
    const b = build(c, lane);
    (res.lanes as unknown[]).push({ version: lane.version, jdk: lane.release, files: c.files.length, hash: c.hash, ...b });
    console.log(`${lane.version}: javac ${b.ok ? `ok (${b.sources} sources, ${b.javacWarnings.length} warnings), scan blocks ${b.scanBlocks.length}, warns ${b.scanWarns.length}` : `FAILED\n${b.error}`}`);
    if (b.ok && lane.version === FLY) flyJar = { path: b.jarPath, sha: b.jarSha256 };
  }
  if (flyJar) {
    const r = await fly({
      version: FLY, plugins: [{ localPath: flyJar.path, sha256: flyJar.sha }], playtest: PLAN, timeouts: { totalSec: 600 },
      rcon: [
        { id: "plugins", command: "plugins", expect: [PLUGIN] },
        { id: "list", command: `${CMD} list`, expect: ["tap_pistol: identity=ok material=iron_horse_armor abilities=1", "ion_beam: identity=ok material=leather_horse_armor abilities=1", "rocket_launcher: identity=ok material=stick abilities=2"], expectNot: ["MISSING", "Exception"] },
        { id: "params", command: `${CMD} params scatter_gun`, expect: ["items.scatter_gun.abilities.blast.a0.pellets=4", "items.scatter_gun.abilities.blast.a0.spread=0.0"] },
      ],
    }, `flight ${FLY}`);
    const pt = r.report.playtest as { scenarios?: { id: string; status: string; steps: { kind: string; status: string; evidence: string[] }[] }[] } | undefined;
    res.flight = { overall: r.summary.overall, line: describeSummary(r.summary), checks: Object.fromEntries(r.report.checks.map((x) => [x.id, x.status])), rcon: r.report.checks.find((x) => x.id === "rcon_checks")?.evidence ?? [], log: r.report.checks.find((x) => x.id === "startup_log_clean")?.evidence ?? [],
      scenarios: (pt?.scenarios ?? []).map((s) => ({ id: s.id, status: s.status, steps: s.steps.map((x) => ({ kind: x.kind, status: x.status, evidence: x.evidence.slice(0, 3) })) })), runId: r.report.runId, engine: r.report.engine ? { runner: r.report.engine.runner, paper: r.report.engine.paper.build } : null };
    console.log(describeSummary(r.summary));
    for (const s of (res.flight as { scenarios: { id: string; status: string; steps: { kind: string; status: string; evidence: string[] }[] }[] }).scenarios) {
      console.log(`  ${s.id} ${s.status}`);
      for (const st of s.steps) if (st.kind === "server" && /Health/.test(st.evidence.join(" ")) || st.status !== "pass") console.log(`    ${st.kind} ${st.status}: ${st.evidence.join(" / ").slice(0, 300)}`);
    }
  }
  const o = arg("--out");
  if (o) { mkdirSync(path.dirname(o), { recursive: true }); writeFileSync(o, JSON.stringify(res, null, 1)); console.log(`wrote ${o}`); }
  rmSync(RUN, { recursive: true, force: true });
})().catch((e) => { console.error(e); rmSync(RUN, { recursive: true, force: true }); process.exit(1); });

