(async () => {
  mkdirSync(RUN, { recursive: true });
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, aiModel: "none (fixture designs)", lanes: [] as unknown[] };
  let flyJar: { path: string; sha: string } | null = null;
  for (const lane of LANES) {
    const c = compileDesigns(designs(), { version: lane.version, namespace: NS, pluginName: PLUGIN });
    if (!c.ok) { (res.lanes as unknown[]).push({ version: lane.version, compile: c.errors }); console.log(`${lane.version}: compile refused ${JSON.stringify(c.errors).slice(0, 300)}`); continue; }
    const b = build(c, lane);
    (res.lanes as unknown[]).push({ version: lane.version, jdk: lane.release, files: c.files.length, hash: c.hash, ...b });
    console.log(`${lane.version}: javac ${b.ok ? `ok (${b.sources} sources, ${b.javacWarnings.length} warnings), scan blocks ${b.scanBlocks.length}, warns ${b.scanWarns.length}` : `FAILED\n${b.error}`}`);
    if (b.ok && lane.version === FLY) flyJar = { path: b.jarPath, sha: b.jarSha256 };
  }
  if (flyJar) {
    const r = await fly({
      version: FLY, plugins: [{ localPath: flyJar.path, sha256: flyJar.sha }], playtest: PLAN, timeouts: { totalSec: 600 },
      rcon: [
        { id: "plugins", command: "plugins", expect: [PLUGIN] },
        { id: "list", command: `${CMD} list`, expect: ["tap_pistol: identity=ok material=iron_horse_armor abilities=1", "ion_beam: identity=ok material=leather_horse_armor abilities=1", "rocket_launcher: identity=ok material=stick abilities=2"], expectNot: ["MISSING", "Exception"] },
        { id: "params", command: `${CMD} params scatter_gun`, expect: ["items.scatter_gun.abilities.blast.a0.pellets=4", "items.scatter_gun.abilities.blast.a0.spread=0.0"] },
      ],
    }, `flight ${FLY}`);
    const pt = r.report.playtest as { scenarios?: { id: string; status: string; steps: { kind: string; status: string; evidence: string[] }[] }[] } | undefined;
    res.flight = { overall: r.summary.overall, line: describeSummary(r.summary), checks: Object.fromEntries(r.report.checks.map((x) => [x.id, x.status])), rcon: r.report.checks.find((x) => x.id === "rcon_checks")?.evidence ?? [], log: r.report.checks.find((x) => x.id === "startup_log_clean")?.evidence ?? [],
      scenarios: (pt?.scenarios ?? []).map((s) => ({ id: s.id, status: s.status, steps: s.steps.map((x) => ({ kind: x.kind, status: x.status, evidence: x.evidence.slice(0, 3) })) })), runId: r.report.runId, engine: r.report.engine ? { runner: r.report.engine.runner, paper: r.report.engine.paper.build } : null };
    console.log(describeSummary(r.summary));
    for (const s of (res.flight as { scenarios: { id: string; status: string; steps: { kind: string; status: string; evidence: string[] }[] }[] }).scenarios) {
      console.log(`  ${s.id} ${s.status}`);
      for (const st of s.steps) if (st.kind === "server" && /Health/.test(st.evidence.join(" ")) || st.status !== "pass") console.log(`    ${st.kind} ${st.status}: ${st.evidence.join(" / ").slice(0, 300)}`);
    }
  }
  const o = arg("--out");
  if (o) { mkdirSync(path.dirname(o), { recursive: true }); writeFileSync(o, JSON.stringify(res, null, 1)); console.log(`wrote ${o}`); }
  rmSync(RUN, { recursive: true, force: true });
})().catch((e) => { console.error(e); rmSync(RUN, { recursive: true, force: true }); process.exit(1); });

